"use client";

import { createContext, useContext, useRef } from "react";
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
  type MotionValue,
} from "motion/react";

import { cn } from "@/lib/utils";

interface DockContextValue {
  mouseX: MotionValue<number>;
  baseSize: number;
  magnification: number;
  distance: number;
}

const DockContext = createContext<DockContextValue | null>(null);

interface DockProps {
  children: React.ReactNode;
  className?: string;
  /** Icon size at rest, px */
  baseSize?: number;
  /** Icon size under the cursor, px */
  magnification?: number;
  /** Cursor influence radius, px */
  distance?: number;
}

export function Dock({
  children,
  className,
  baseSize = 40,
  magnification = 64,
  distance = 140,
}: DockProps) {
  const mouseX = useMotionValue(Infinity);

  return (
    <DockContext.Provider value={{ mouseX, baseSize, magnification, distance }}>
      <motion.div
        data-slot="dock"
        onMouseMove={(e) => mouseX.set(e.clientX)}
        onMouseLeave={() => mouseX.set(Infinity)}
        className={cn(
          "mx-auto flex h-16 w-fit items-end gap-2 rounded-2xl border bg-card/70 px-3 pb-2 backdrop-blur-xl",
          className
        )}
      >
        {children}
      </motion.div>
    </DockContext.Provider>
  );
}

interface DockIconProps {
  children: React.ReactNode;
  className?: string;
  /** Accessible name; also used as the tooltip title */
  label?: string;
  /** Render as a link to this URL instead of a button */
  href?: string;
  /** Click handler for the button (or link) */
  onClick?: React.MouseEventHandler<HTMLElement>;
}

export function DockIcon({
  children,
  className,
  label,
  href,
  onClick,
}: DockIconProps) {
  const ref = useRef<HTMLElement>(null);
  const reducedMotion = useReducedMotion();
  const fallbackX = useMotionValue(Infinity);
  const ctx = useContext(DockContext);
  const mouseX = ctx?.mouseX ?? fallbackX;
  const baseSize = ctx?.baseSize ?? 40;
  const magnification = ctx?.magnification ?? 64;
  const distance = ctx?.distance ?? 140;

  const distanceFromCursor = useTransform(mouseX, (x) => {
    const bounds = ref.current?.getBoundingClientRect() ?? { x: 0, width: 0 };
    return x - bounds.x - bounds.width / 2;
  });

  const sizeTarget = useTransform(
    distanceFromCursor,
    [-distance, 0, distance],
    [baseSize, magnification, baseSize]
  );
  const size = useSpring(sizeTarget, {
    mass: 0.1,
    stiffness: 160,
    damping: 13,
  });

  const shared = {
    "data-slot": "dock-icon",
    "aria-label": label,
    title: label,
    onClick,
    // Magnify around the focused icon for keyboard users, like a hover would
    onFocus: () => {
      const bounds = ref.current?.getBoundingClientRect();
      if (bounds) mouseX.set(bounds.x + bounds.width / 2);
    },
    onBlur: () => mouseX.set(Infinity),
    style: reducedMotion
      ? { width: baseSize, height: baseSize }
      : { width: size, height: size },
    className: cn(
      "flex aspect-square cursor-pointer items-center justify-center rounded-full bg-muted text-muted-foreground transition-colors hover:text-foreground focus-visible:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
      className
    ),
  };

  return href ? (
    <motion.a
      ref={ref as React.RefObject<HTMLAnchorElement>}
      href={href}
      {...shared}
    >
      {children}
    </motion.a>
  ) : (
    <motion.button
      ref={ref as React.RefObject<HTMLButtonElement>}
      type="button"
      {...shared}
    >
      {children}
    </motion.button>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

interface FloatingNavbarProps extends React.HTMLAttributes<HTMLElement> {
  /** Pixels scrolled before the bar is allowed to hide */
  revealAfter?: number;
  /** Scrollable element to watch instead of the window */
  scrollContainer?: React.RefObject<HTMLElement | null>;
  children: React.ReactNode;
}

/**
 * Header that slides away as you scroll down and returns the moment you
 * scroll back up. Renders visible on the server, so there is no flash, and
 * slides back in whenever focus moves into it.
 */
export function FloatingNavbar({
  revealAfter = 120,
  scrollContainer,
  children,
  className,
  onFocus,
  ...props
}: FloatingNavbarProps) {
  const [hidden, setHidden] = useState(false);
  const lastY = useRef(0);
  const ref = useRef<HTMLElement>(null);

  useEffect(() => {
    const container = scrollContainer?.current;
    const target = container ?? window;
    const readY = () => (container ? container.scrollTop : window.scrollY);
    lastY.current = readY();
    let frame = 0;

    const onScroll = () => {
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        const y = readY();
        const delta = y - lastY.current;
        // Ignore sub-pixel jitter and rubber-band scroll past the top.
        if (Math.abs(delta) < 4) return;
        const focused = ref.current?.contains(document.activeElement);
        setHidden(delta > 0 && y > revealAfter && !focused);
        lastY.current = y;
      });
    };

    target.addEventListener("scroll", onScroll, { passive: true });
    return () => {
      target.removeEventListener("scroll", onScroll);
      if (frame) cancelAnimationFrame(frame);
    };
  }, [revealAfter, scrollContainer]);

  return (
    <header
      {...props}
      ref={ref}
      data-slot="floating-navbar"
      onFocus={(event) => {
        // Keyboard focus must never land on an off-screen link.
        setHidden(false);
        onFocus?.(event);
      }}
      className={cn(
        "fixed inset-x-0 top-4 z-50 mx-auto flex w-[calc(100%-2rem)] max-w-3xl items-center justify-between gap-4 rounded-full border bg-background/80 px-5 py-2.5 shadow-lg shadow-foreground/5 backdrop-blur-md transition-transform duration-300 ease-out motion-reduce:transition-none",
        hidden ? "-translate-y-[calc(100%+1.5rem)]" : "translate-y-0",
        className
      )}
    >
      {children}
    </header>
  );
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

const MenuContext = createContext<{
  active: string | null;
  setActive: (value: string | null) => void;
}>({ active: null, setActive: () => {} });

/**
 * Hover-driven navigation menu whose panel morphs between items.
 * Wrap `MenuItem`s in `NavbarMenu`. The panel closes when the pointer or
 * keyboard focus leaves the menu, and on Escape.
 */
export function NavbarMenu({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  const [active, setActive] = useState<string | null>(null);

  // Escape also dismisses a panel opened by hover, wherever focus is.
  useEffect(() => {
    if (!active) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setActive(null);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [active]);

  return (
    <MenuContext.Provider value={{ active, setActive }}>
      <nav
        data-slot="navbar-menu"
        onMouseLeave={() => setActive(null)}
        onBlur={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
            setActive(null);
          }
        }}
        className={cn(
          "relative flex items-center gap-1 rounded-full border bg-background/80 px-3 py-1.5 backdrop-blur-md",
          className
        )}
      >
        {children}
      </nav>
    </MenuContext.Provider>
  );
}

export function MenuItem({
  label,
  href,
  children,
  className,
}: {
  label: string;
  /** Renders the item as a link; ignored when the item has a panel */
  href?: string;
  children?: React.ReactNode;
  className?: string;
}) {
  const { active, setActive } = useContext(MenuContext);
  const reducedMotion = useReducedMotion();
  const triggerRef = useRef<HTMLButtonElement & HTMLAnchorElement>(null);
  const panelId = useId();
  const open = active === label;
  const hasPanel = Boolean(children);

  const triggerClass = cn(
    "relative rounded-full px-3.5 py-1.5 text-sm transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
    open ? "text-foreground" : "text-muted-foreground hover:text-foreground",
    className
  );
  const pill = open && (
    <motion.span
      layoutId="navbar-menu-pill"
      className="absolute inset-0 -z-10 rounded-full bg-muted"
      transition={
        reducedMotion
          ? { duration: 0 }
          : { type: "spring", stiffness: 380, damping: 32 }
      }
    />
  );

  return (
    <div
      className="relative"
      onMouseEnter={() => setActive(label)}
      onFocus={(event) => {
        // Only open when focus arrives from outside this item, so Escape
        // can return focus to the trigger without reopening the panel.
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
          setActive(label);
        }
      }}
      onKeyDown={(event) => {
        if (event.key !== "Escape" || !open) return;
        setActive(null);
        triggerRef.current?.focus();
      }}
    >
      {href && !hasPanel ? (
        <a ref={triggerRef} href={href} className={cn("block", triggerClass)}>
          {pill}
          {label}
        </a>
      ) : (
        <button
          ref={triggerRef}
          type="button"
          aria-expanded={hasPanel ? open : undefined}
          aria-controls={hasPanel && open ? panelId : undefined}
          onClick={() => setActive(label)}
          className={triggerClass}
        >
          {pill}
          {label}
        </button>
      )}

      <AnimatePresence>
        {open && hasPanel && (
          <motion.div
            id={panelId}
            initial={{ opacity: 0, y: 6, scale: 0.97 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 6, scale: 0.97 }}
            transition={{ duration: reducedMotion ? 0 : 0.18, ease: "easeOut" }}
            className="absolute left-1/2 top-full z-50 mt-3 w-max -translate-x-1/2 rounded-2xl border bg-popover p-3 text-popover-foreground shadow-xl shadow-foreground/5"
          >
            {children}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

