} from "@/components/ui/table";
import { cn } from "@/lib/utils";

export type { ColumnDef } from "@tanstack/react-table";

export interface DataGridFilter {
  /** Column id (usually the accessorKey) to filter */
  column: string;
  /** Label on the filter button */
  title: string;
  /** Choices; read from the data when omitted */
  options?: { label: string; value: string }[];
}

export interface DataGridProps<TData, TValue> {
  /** Rows to display */
  data: TData[];
  /** TanStack Table column definitions; set `meta.label` for a readable name in menus */
  columns: ColumnDef<TData, TValue>[];
  /** Stable row id, so selection survives sorting and new data. Defaults to the row index */
  getRowId?: (row: TData, index: number) => string;
  /** Show a search box that matches text in every column @default true */
  searchable?: boolean;
  /** @default "Search…" */
  searchPlaceholder?: string;
  /** Multi-select filter buttons, one per column */
  filters?: DataGridFilter[];
  /** Add a checkbox column @default false */
  selectable?: boolean;
  /** Called with the selected rows' data whenever the selection changes */
  onSelectionChange?: (rows: TData[]) => void;
  /** Actions shown in a bar while rows are selected */
  bulkActions?: (rows: TData[], clearSelection: () => void) => React.ReactNode;
  /** Show the column visibility menu @default true */
  columnToggle?: boolean;
  /** @default 10 */
  pageSize?: number;
  /** Options in the rows-per-page menu @default [10, 20, 50] */
  pageSizes?: number[];
  /** Initial sort, e.g. `[{ id: "date", desc: true }]` */
  defaultSort?: SortingState;
  /** Show skeleton rows instead of data @default false */
  loading?: boolean;
  /** Shown when no row matches @default "No results." */
  empty?: React.ReactNode;
  /** Row height @default "comfortable" */
  density?: "compact" | "comfortable";
  /** Accessible name for the table @default "Data table" */
  label?: string;
  className?: string;
}

// Faceted filters store an array of accepted values; an empty array means "any".
const inSet: FilterFn<unknown> = (row, id, value: string[]) =>
  !value?.length || value.includes(String(row.getValue(id)));

const labelOf = <TData,>(column: Column<TData, unknown>) =>
  (column.columnDef.meta as { label?: string } | undefined)?.label ??
  (typeof column.columnDef.header === "string"
    ? column.columnDef.header
    : column.id);

// A native checkbox, so selection works the same whether the project's
// shadcn/ui primitives are built on Radix or Base UI.
function SelectBox({
  checked,
  indeterminate = false,
  onChange,
  label,
}: {
  checked: boolean;
  indeterminate?: boolean;
  onChange: (value: boolean) => void;
  label: string;
}) {
  const ref = React.useRef<HTMLInputElement>(null);
  React.useEffect(() => {
    if (ref.current) ref.current.indeterminate = indeterminate;
  }, [indeterminate]);
  return (
    <input
      ref={ref}
      type="checkbox"
      checked={checked}
      onChange={(e) => onChange(e.target.checked)}
      aria-label={label}
      className="size-4 translate-y-0.5 cursor-pointer rounded accent-primary"
    />
  );
}

function FacetFilter<TData>({
  column,
  title,
  options,
}: {
  column: Column<TData, unknown>;
  title: string;
  options?: DataGridFilter["options"];
}) {
  const facets = column.getFacetedUniqueValues();
  const choices =
    options ??
    [...facets.keys()]
      .map((v) => ({ label: String(v), value: String(v) }))
      .sort((a, b) => a.label.localeCompare(b.label));
  const selected = new Set(
    (column.getFilterValue() as string[] | undefined) ?? [],
  );

  const toggle = (value: string, on: boolean) => {
    const next = new Set(selected);
    if (on) next.add(value);
    else next.delete(value);
    column.setFilterValue(next.size ? [...next] : undefined);
  };

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        className={cn(
          buttonVariants({ variant: "outline", size: "sm" }),
          "border-dashed",
        )}
      >
        <PlusCircleIcon aria-hidden />
        <span className="sr-only">Filter by </span>
        {title}
        {selected.size > 0 && (
          <span className="rounded-sm bg-primary/10 px-1.5 text-xs font-medium tabular-nums text-foreground">
            {selected.size}
            <span className="sr-only"> selected</span>
          </span>
        )}
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="min-w-48">
        <DropdownMenuGroup>
          <DropdownMenuLabel>{title}</DropdownMenuLabel>
        </DropdownMenuGroup>
        <DropdownMenuSeparator />
        {choices.map((choice) => (
          <DropdownMenuCheckboxItem
            key={choice.value}
            checked={selected.has(choice.value)}
            onCheckedChange={(on) => toggle(choice.value, on === true)}
            onSelect={(e) => e.preventDefault()}
          >
            <span className="flex-1">{choice.label}</span>
            <span className="ml-4 text-xs text-muted-foreground tabular-nums">
              {facets.get(choice.value) ?? 0}
            </span>
          </DropdownMenuCheckboxItem>
        ))}
        {selected.size > 0 && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              onClick={() => column.setFilterValue(undefined)}
              className="justify-center text-muted-foreground"
            >
              Clear filter
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * Sortable, filterable, paginated table built on TanStack Table and the
 * shadcn/ui table primitives. Pass column definitions and rows; search,
 * faceted filters, selection and column visibility are opt-in props.
 */
export function DataGrid<TData, TValue>({
  data,
  columns,
  getRowId,
  searchable = true,
  searchPlaceholder = "Search…",
  filters = [],
  selectable = false,
  onSelectionChange,
  bulkActions,
  columnToggle = true,
  pageSize = 10,
  pageSizes = [10, 20, 50],
  defaultSort = [],
  loading = false,
  empty = "No results.",
  density = "comfortable",
  label = "Data table",
  className,
}: DataGridProps<TData, TValue>) {
  const [sorting, setSorting] = React.useState<SortingState>(defaultSort);
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>(
    [],
  );
  const [globalFilter, setGlobalFilter] = React.useState("");
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({});
  const [columnVisibility, setColumnVisibility] =
    React.useState<VisibilityState>({});

  const allColumns = React.useMemo<ColumnDef<TData, TValue>[]>(() => {
    if (!selectable) return columns;
    const select: ColumnDef<TData, TValue> = {
      id: "__select",
      enableSorting: false,
      enableHiding: false,
      header: ({ table }) => (
        <SelectBox
          label="Select all rows on this page"
          checked={table.getIsAllPageRowsSelected()}
          indeterminate={table.getIsSomePageRowsSelected()}
          onChange={(v) => table.toggleAllPageRowsSelected(v)}
        />
      ),
      cell: ({ row }) => (
        <SelectBox
          label={`Select row ${row.index + 1}`}
          checked={row.getIsSelected()}
          onChange={(v) => row.toggleSelected(v)}
        />
      ),
    };
    return [select, ...columns];
  }, [columns, selectable]);

  // TanStack returns a mutable table instance, so React Compiler skips this
  // component instead of memoizing it — the intended behavior.
  // eslint-disable-next-line react-hooks/incompatible-library
  const table = useReactTable({
    data,
    columns: allColumns,
    getRowId,
    state: {
      sorting,
      columnFilters,
      globalFilter,
      rowSelection,
      columnVisibility,
    },
    initialState: { pagination: { pageSize } },
    defaultColumn: { filterFn: inSet as FilterFn<TData> },
    globalFilterFn: "includesString",
    enableRowSelection: selectable,
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onGlobalFilterChange: setGlobalFilter,
    onRowSelectionChange: setRowSelection,
    onColumnVisibilityChange: setColumnVisibility,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
  });

  const selectedRows = table.getSelectedRowModel().rows.map((r) => r.original);
  const onSelectionChangeRef = React.useRef(onSelectionChange);
  onSelectionChangeRef.current = onSelectionChange;
  React.useEffect(() => {
    onSelectionChangeRef.current?.(
      table.getSelectedRowModel().rows.map((r) => r.original),
    );
  }, [rowSelection, table]);

  const filtered = table.getFilteredRowModel().rows.length;
  const { pageIndex, pageSize: size } = table.getState().pagination;
  const first = filtered ? pageIndex * size + 1 : 0;
  const last = Math.min((pageIndex + 1) * size, filtered);
  const isFiltered = globalFilter !== "" || columnFilters.length > 0;
  const cellPad = density === "compact" ? "py-1.5" : "py-3";
  const visibleColumns = table.getVisibleLeafColumns().length;
  const clearSelection = () => table.resetRowSelection();

  return (
    <div data-slot="data-grid" className={cn("flex flex-col gap-3", className)}>
      <div className="flex flex-wrap items-center gap-2">
        {searchable && (
          <div className="relative w-full sm:w-64">
            <SearchIcon
              aria-hidden
              className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground"
            />
            <Input
              type="search"
              value={globalFilter}
              onChange={(e) => {
                setGlobalFilter(e.target.value);
                table.setPageIndex(0);
              }}
              placeholder={searchPlaceholder}
              aria-label={searchPlaceholder.replace(/…$/, "")}
              className="h-8 pl-8"
            />
          </div>
        )}
        {filters.map((f) => {
          const column = table.getColumn(f.column);
          return column ? (
            <FacetFilter
              key={f.column}
              column={column as Column<TData, unknown>}
              title={f.title}
              options={f.options}
            />
          ) : null;
        })}
        {isFiltered && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setGlobalFilter("");
              setColumnFilters([]);
            }}
          >
            Reset
            <XIcon aria-hidden />
          </Button>
        )}
        {columnToggle && (
          <DropdownMenu>
            <DropdownMenuTrigger
              className={cn(
                buttonVariants({ variant: "outline", size: "sm" }),
                "ml-auto",
              )}
            >
              <Settings2Icon aria-hidden />
              Columns
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="min-w-40">
              <DropdownMenuGroup>
                <DropdownMenuLabel>Show columns</DropdownMenuLabel>
              </DropdownMenuGroup>
              <DropdownMenuSeparator />
              {table
                .getAllLeafColumns()
                .filter((c) => c.getCanHide())
                .map((c) => (
                  <DropdownMenuCheckboxItem
                    key={c.id}
                    checked={c.getIsVisible()}
                    onCheckedChange={(v) => c.toggleVisibility(v === true)}
                    onSelect={(e) => e.preventDefault()}
                  >
                    {labelOf(c as Column<TData, unknown>)}
                  </DropdownMenuCheckboxItem>
                ))}
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </div>

      {selectable && selectedRows.length > 0 && (
        <div className="flex flex-wrap items-center gap-2 rounded-lg border bg-muted/50 px-3 py-1.5 text-sm motion-safe:animate-in motion-safe:fade-in motion-safe:slide-in-from-top-1">
          <span className="font-medium tabular-nums">
            {selectedRows.length} selected
          </span>
          <div className="ml-auto flex items-center gap-2">
            {bulkActions?.(selectedRows, clearSelection)}
            <Button variant="ghost" size="sm" onClick={clearSelection}>
              Clear
            </Button>
          </div>
        </div>
      )}

      <div className="overflow-hidden rounded-lg border">
        <Table aria-label={label} aria-busy={loading || undefined}>
          <TableHeader className="bg-muted/40">
            {table.getHeaderGroups().map((group) => (
              <TableRow key={group.id} className="hover:bg-transparent">
                {group.headers.map((header) => {
                  const sorted = header.column.getIsSorted();
                  const content = header.isPlaceholder
                    ? null
                    : flexRender(
                        header.column.columnDef.header,
                        header.getContext(),
                      );
                  return (
                    <TableHead
                      key={header.id}
                      className="px-3"
                      aria-sort={
                        sorted === "asc"
                          ? "ascending"
                          : sorted === "desc"
                            ? "descending"
                            : header.column.getCanSort()
                              ? "none"
                              : undefined
                      }
                    >
                      {header.column.getCanSort() ? (
                        <button
                          type="button"
                          onClick={header.column.getToggleSortingHandler()}
                          className="-mx-1.5 inline-flex cursor-pointer items-center gap-1 rounded-md px-1.5 py-1 hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                        >
                          {content}
                          {sorted === "asc" ? (
                            <ArrowUpIcon aria-hidden className="size-3.5" />
                          ) : sorted === "desc" ? (
                            <ArrowDownIcon aria-hidden className="size-3.5" />
                          ) : (
                            <ChevronsUpDownIcon
                              aria-hidden
                              className="size-3.5 text-muted-foreground/60"
                            />
                          )}
                        </button>
                      ) : (
                        content
                      )}
                    </TableHead>
                  );
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {loading ? (
              Array.from({ length: size }, (_, i) => (
                <TableRow key={i} className="hover:bg-transparent">
                  {table.getVisibleLeafColumns().map((c) => (
                    <TableCell key={c.id} className={cn("px-3", cellPad)}>
                      <Skeleton className="h-4 w-full max-w-32" />
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() ? "selected" : undefined}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className={cn("px-3", cellPad)}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow className="hover:bg-transparent">
                <TableCell
                  colSpan={visibleColumns}
                  className="h-28 text-center text-muted-foreground"
                >
                  {empty}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <div className="flex flex-wrap items-center justify-between gap-3 text-sm text-muted-foreground">
        <p aria-live="polite" className="tabular-nums">
          {loading
            ? "Loading…"
            : filtered
              ? `${first}–${last} of ${filtered}`
              : "0 results"}
        </p>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <span aria-hidden className="hidden sm:inline">
              Rows per page
            </span>
            <Select
              value={String(size)}
              onValueChange={(v) => table.setPageSize(Number(v))}
            >
              <SelectTrigger
                size="sm"
                aria-label="Rows per page"
                className="w-[4.5rem]"
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {pageSizes.map((n) => (
                  <SelectItem key={n} value={String(n)}>
                    {n}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <span className="tabular-nums">
            Page {table.getPageCount() ? pageIndex + 1 : 0} of{" "}
            {table.getPageCount()}
          </span>
          <div className="flex items-center gap-1">
            {(
              [
                [
                  "First page",
                  ChevronsLeftIcon,
                  () => table.firstPage(),
                  !table.getCanPreviousPage(),
                ],
                [
                  "Previous page",
                  ChevronLeftIcon,
                  () => table.previousPage(),
                  !table.getCanPreviousPage(),
                ],
                [
                  "Next page",
                  ChevronRightIcon,
                  () => table.nextPage(),
                  !table.getCanNextPage(),
                ],
                [
                  "Last page",
                  ChevronsRightIcon,
                  () => table.lastPage(),
                  !table.getCanNextPage(),
                ],
              ] as const
            ).map(([name, Icon, go, disabled]) => (
              <Button
                key={name}
                variant="outline"
                size="icon-sm"
                onClick={go}
                disabled={disabled}
                aria-label={name}
              >
                <Icon aria-hidden />
              </Button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import * as React from "react"
import { createMap } from "svg-dotted-map"

import { cn } from "@/lib/utils"

export interface Marker {
  lat: number
  lng: number
  size?: number
  pulse?: boolean
}

/** addMarkers returns markers with lat/lng removed; only x, y and other props (e.g. size) remain */
type MapMarker<M extends Marker> = Omit<M, "lat" | "lng"> & {
  x: number
  y: number
}

export interface DottedMapProps<
  M extends Marker = Marker,
> extends React.SVGProps<SVGSVGElement> {
  width?: number
  height?: number
  mapSamples?: number
  markers?: M[]
  dotColor?: string
  markerColor?: string
  dotRadius?: number
  stagger?: boolean
  pulse?: boolean

  renderMarkerOverlay?: (args: {
    marker: MapMarker<M>
    index: number
    x: number
    y: number
    r: number
  }) => React.ReactNode
}

export function DottedMap<M extends Marker = Marker>({
  width = 150,
  height = 75,
  mapSamples = 5000,
  markers = [],
  dotColor = "currentColor",
  markerColor = "#FF6900",
  dotRadius = 0.2,
  stagger = true,
  pulse = false,
  renderMarkerOverlay,
  className,
  style,
  ...svgProps
}: DottedMapProps<M>) {
  const { points, addMarkers } = React.useMemo(
    () => createMap({ width, height, mapSamples }),
    [width, height, mapSamples]
  )
  const processedMarkers = addMarkers(markers)

  // Compute stagger helpers in a single, simple pass
  const { xStep, yToRowIndex } = React.useMemo(() => {
    const sorted = [...points].sort((a, b) => a.y - b.y || a.x - b.x)
    const rowMap = new Map<number, number>()
    let step = 0
    let prevY = Number.NaN
    let prevXInRow = Number.NaN

    for (const p of sorted) {
      if (p.y !== prevY) {
        // new row
        prevY = p.y
        prevXInRow = Number.NaN
        if (!rowMap.has(p.y)) rowMap.set(p.y, rowMap.size)
      }
      if (!Number.isNaN(prevXInRow)) {
        const delta = p.x - prevXInRow
        if (delta > 0) step = step === 0 ? delta : Math.min(step, delta)
      }
      prevXInRow = p.x
    }

    return { xStep: step || 1, yToRowIndex: rowMap }
  }, [points])

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className={cn("text-gray-500 dark:text-gray-500", className)}
      style={{ width: "100%", height: "100%", ...style }}
      {...svgProps}
    >
      {points.map((point, index) => {
        const rowIndex = yToRowIndex.get(point.y) ?? 0
        const offsetX = stagger && rowIndex % 2 === 1 ? xStep / 2 : 0
        return (
          <circle
            cx={point.x + offsetX}
            cy={point.y}
            r={dotRadius}
            fill={dotColor}
            key={`${point.x}-${point.y}-${index}`}
          />
        )
      })}

      {processedMarkers.map((marker, index) => {
        const rowIndex = yToRowIndex.get(marker.y) ?? 0
        const offsetX = stagger && rowIndex % 2 === 1 ? xStep / 2 : 0

        const x = marker.x + offsetX
        const y = marker.y
        const r = marker.size ?? dotRadius
        const shouldPulse = pulse
          ? marker.pulse !== false
          : marker.pulse === true
        const pulseTo = r * 2.8

        return (
          <g key={`${marker.x}-${marker.y}-${index}`}>
            <circle cx={x} cy={y} r={r} fill={markerColor} />

            {shouldPulse ? (
              <g pointerEvents="none">
                <circle
                  cx={x}
                  cy={y}
                  r={r}
                  fill="none"
                  stroke={markerColor}
                  strokeOpacity={1}
                  strokeWidth={0.35}
                >
                  <animate
                    attributeName="r"
                    values={`${r};${pulseTo}`}
                    dur="1.4s"
                    repeatCount="indefinite"
                  />
                  <animate
                    attributeName="opacity"
                    values="1;0"
                    dur="1.4s"
                    repeatCount="indefinite"
                  />
                </circle>
                <circle
                  cx={x}
                  cy={y}
                  r={r}
                  fill="none"
                  stroke={markerColor}
                  strokeOpacity={0.9}
                  strokeWidth={0.3}
                >
                  <animate
                    attributeName="r"
                    values={`${r};${pulseTo}`}
                    dur="1.4s"
                    begin="0.7s"
                    repeatCount="indefinite"
                  />
                  <animate
                    attributeName="opacity"
                    values="0.9;0"
                    dur="1.4s"
                    begin="0.7s"
                    repeatCount="indefinite"
                  />
                </circle>
              </g>
            ) : null}

            {renderMarkerOverlay?.({
              marker: { ...marker, x, y },
              index,
              x,
              y,
              r,
            })}
          </g>
        )
      })}
    </svg>
  )
}

"use client";

import { useState } from "react";

import { cn } from "@/lib/utils";

export interface FileNode {
  name: string;
  /** Presence of `children` makes the node a folder */
  children?: FileNode[];
  /** Folders start open unless this is false */
  defaultOpen?: boolean;
}

interface FileTreeProps {
  tree: FileNode[];
  className?: string;
}

function Node({ node, depth }: { node: FileNode; depth: number }) {
  const isFolder = Array.isArray(node.children);
  const [open, setOpen] = useState(node.defaultOpen ?? true);

  return (
    <li>
      <div
        style={{ paddingLeft: depth * 14 }}
        className="flex items-center gap-1.5 rounded-md py-1 pr-2 text-sm"
      >
        {isFolder ? (
          <button
            type="button"
            onClick={() => setOpen((value) => !value)}
            aria-expanded={open}
            className="flex flex-1 cursor-pointer items-center gap-1.5 rounded-md px-1 py-0.5 text-left transition-colors hover:bg-muted"
          >
            <svg
              width="12"
              height="12"
              viewBox="0 0 12 12"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.75"
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden
              className={cn(
                "shrink-0 text-muted-foreground transition-transform duration-150 motion-reduce:transition-none",
                open && "rotate-90"
              )}
            >
              <path d="M4.5 2.5L8 6l-3.5 3.5" />
            </svg>
            <span className="font-medium">{node.name}</span>
          </button>
        ) : (
          <span className="flex items-center gap-1.5 px-1 py-0.5 pl-[1.125rem] text-muted-foreground">
            {node.name}
          </span>
        )}
      </div>

      {isFolder && open && (
        <ul>
          {node.children!.map((child) => (
            <Node key={child.name} node={child} depth={depth + 1} />
          ))}
        </ul>
      )}
    </li>
  );
}

/**
 * Collapsible file tree for documenting project structure. Renders as nested
 * lists, so it stays readable with CSS off.
 */
export function FileTree({ tree, className }: FileTreeProps) {
  return (
    <ul
      data-slot="file-tree"
      className={cn("w-full rounded-xl border bg-card p-3 font-mono", className)}
    >
      {tree.map((node) => (
        <Node key={node.name} node={node} depth={0} />
      ))}
    </ul>
  );
}

"use client";

import { useEffect, useRef } from "react";

import { cn } from "@/lib/utils";

// Land mask derived from Natural Earth (public domain): 240×120 cells, run-length encoded.
const LAND = "_0_0_0_0_0_0_0_0_0_0_0_0_0_0_0_0HDBH_0_0_0211r_0_0wI1ZI118D3R6_0Z143121D2ZK8m7_0Q42284184ZM322S1M412_0M128231B7Xp7EHF611w522ABFPn4EL21G141uE271ADMo3833Y76L1D4J31A252DANU4E46$D1BG3A2B162D8LSBH32_0416127h1814387ISH222G1_0D4u585EB1J_0m152v3A79A7G8181_0W615n14212688C5F_0pAo513413A6V92_0h9mB6D5V92_0R29H6116WA622j93_0P33P4BU9Bb375311_0FA5N3GV7Ba3663_0FC5L2KX2FW21352112_0HC5h11X1GU3142_0U83mmU2241_0V82mk12X_0byf44W_0aze44X_0W12zhdL13182v_02c12fA1931272v33yaf85318852u34yaf841141K2q61_Yh65232131G2j1572_Wi683322F3h4371_01Wi52621422_012343_02VkBF11u4226_04RkDGw55_08PkH337w52_0BOl_0P_0J11G32ld1n_0I21A92ig1l_0K218A2hX1A211g_0M217tY1A12231Z11_0M12693gZ2E5X21_0P66143ea1E6E1Fy1W7336212aa1D9A4921_0X7146123Za2BA95912_0Z9mb29C68982_0U9jc17E5911871_0Y7hjG5B872_0a4ifK4B87111_0a354Ze23G4B2158111_0a2211BUiH3B231B1_0cHUhH112A2E4_0eEUfK2B2E2_0fHS73UU22274_0jIeQW21264_0jKdPY545_0jKdOa3371321_0bNbMc4351352_0YQYMd425136213_0TTWKf3521321111941_0LVVIh2A19713_0LVVIi5H741_0KUVJk411113177_0PTWJq122E2_0PSXIz1_0bQXJ51s432_0UPYJ52o11533_0UOYJ34n923E1_0HMXJ34mHK1_0BLYG54mH_0WKZG54jL_0VKaF53iOA1_0JJbF53iP_0TGeE63hR_0RGgCsQ_0RGgCsQ_0RFiAtR_0QFiAuP_0REk8v92E_0RDl6x67B_0RB_0r1CAE1_0CB_0_057G1_0BB_0_065H3_098_0_0V2_098_0_0C3F4_098_0_0D2F2_0B7_0_0T3_0C5_0_0U3_0D6_0_0_0i7_0R1_0_0H5_0_0_0k452_0_0_0f4_0_0_0m4_0_0_0_0_0_0_0_0_0_0_0_0_0_0_0_0_0_0_0_0_0_0w2_0_0_0k2_0_0_0l3_0C6G82W_0Z2_08I6n_0S6l131135S2w_0K9Yr2_03v45398U_0zYI5SU_0yUtQ_0_01OvR_0_05M31sH55_0_09Up44477_0_03T_014_0_0JT_0_0_0Q7E141_0_0_0_0_0_0_0_0_0_0_0_0_0_0w";
const RLE = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz$_";
let mask: Uint8Array | undefined;
const isLand = (lat: number, lng: number) => {
  if (!mask) {
    mask = new Uint8Array(28800);
    let p = 0;
    let v = 0;
    for (const c of LAND) {
      mask.fill(v, p, (p += RLE.indexOf(c)));
      v ^= 1;
    }
  }
  return mask[((90 - lat) / 1.5 | 0) * 240 + ((lng + 180) / 1.5 | 0)];
};

const RAD = Math.PI / 180;
const vec = (lat: number, lng: number) => {
  const c = Math.cos(lat * RAD);
  return [c * Math.sin(lng * RAD), Math.sin(lat * RAD), c * Math.cos(lng * RAD)];
};

export interface GlobeMarker {
  /** Latitude in degrees */
  lat: number;
  /** Longitude in degrees */
  lng: number;
  /** Name drawn beside the marker and included in the accessible name */
  label?: string;
}

export interface GlobeArc {
  /** Start as [lat, lng] */
  from: [number, number];
  /** End as [lat, lng] */
  to: [number, number];
}

interface GlobeProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Highlighted points, as { lat, lng, label? } */
  markers?: GlobeMarker[];
  /** Great-circle connections, as { from: [lat, lng], to: [lat, lng] } */
  arcs?: GlobeArc[];
  /** [lat, lng] facing the viewer on first paint */
  center?: [number, number];
  /** Auto-rotation in degrees per second (negative spins west); 0 turns it off */
  speed?: number;
  /** Points sampled over the sphere; roughly 3 in 10 land and become dots */
  samples?: number;
  /** Land dot color: any CSS color, var() tokens included */
  dotColor?: string;
  /** Marker and arc color: any CSS color, var() tokens included */
  accentColor?: string;
  /** Accessible name; generated from marker labels when omitted */
  label?: string;
}

/**
 * Dotted 2D-canvas globe with markers and animated great-circle arcs.
 * Drag (with inertia) or use the arrow keys to rotate; auto-rotation pauses
 * while hovered or focused. Give it a width — height follows (it is square).
 */
export function Globe({
  markers = [],
  arcs = [],
  center = [20, 10],
  speed = 6,
  samples = 12000,
  dotColor = "var(--muted-foreground)",
  accentColor = "var(--brand)",
  label,
  className,
  ...props
}: GlobeProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const view = useRef<{ lat: number; lng: number; vx: number; vy: number }>(null);
  const [lat0, lng0] = center;

  useEffect(() => {
    const root = rootRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext("2d");
    if (!root || !canvas || !ctx) return;
    const v = (view.current ??= { lat: lat0, lng: lng0, vx: 0, vy: 0 });
    const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;

    // Fibonacci lattice: evenly spaced samples, kept where the mask says land.
    const dots: number[] = [];
    for (let i = 0; i < samples; i++) {
      const lat = Math.asin(1 - (2 * i + 1) / samples) / RAD;
      const lng = ((i * 137.508) % 360) - 180;
      if (isLand(lat, lng)) dots.push(...vec(lat, lng));
    }
    const pins = markers.map((m) => vec(m.lat, m.lng));
    const S = 40;
    const paths = arcs.map(({ from, to }) => {
      const a = vec(...from);
      const b = vec(...to);
      const w = Math.acos(Math.min(1, a[0] * b[0] + a[1] * b[1] + a[2] * b[2]));
      const pts: number[][] = [];
      for (let s = 0; s <= S && w > 1e-3; s++) {
        const t = s / S;
        const k = (1 + Math.min(w, 1.6) * 0.12 * Math.sin(Math.PI * t)) / Math.sin(w);
        const p = Math.sin((1 - t) * w) * k;
        const q = Math.sin(t * w) * k;
        pts.push([a[0] * p + b[0] * q, a[1] * p + b[1] * q, a[2] * p + b[2] * q]);
      }
      return pts;
    });

    let w = 0, h = 0, R = 0, raf = 0, last = 0;
    let inView = true, hover = false, focus = false;
    let drag: { x: number; y: number } | null = null;
    let dot = "", accent = "", text = "", font = "";

    const resolve = () => {
      const cs = getComputedStyle(root);
      canvas.style.color = dotColor;
      dot = getComputedStyle(canvas).color;
      canvas.style.color = accentColor;
      accent = getComputedStyle(canvas).color;
      text = cs.color;
      font = `500 11px ${cs.fontFamily}`;
    };

    const draw = (t: number) => {
      const cl = Math.cos(v.lng * RAD), sl = Math.sin(v.lng * RAD);
      const ct = Math.cos(v.lat * RAD), st = Math.sin(v.lat * RAD);
      const cx = w / 2, cy = h / 2;
      // Rotate so (v.lat, v.lng) faces the viewer; returns [x, y, depth].
      const proj = (x: number, y: number, z: number) => {
        const z0 = x * sl + z * cl;
        return [x * cl - z * sl, y * ct - z0 * st, y * st + z0 * ct];
      };
      const disc = (x: number, y: number, r: number) => {
        ctx.beginPath();
        ctx.arc(cx + x * R, cy - y * R, r, 0, 7);
      };
      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = dot;
      const r = Math.max(0.8, R / 130);
      for (let i = 0; i < dots.length; i += 3) {
        const [x, y, z] = proj(dots[i], dots[i + 1], dots[i + 2]);
        if (z <= 0) continue;
        ctx.globalAlpha = 0.12 + 0.78 * z;
        disc(x, y, r * (0.6 + 0.4 * z));
        ctx.fill();
      }

      ctx.fillStyle = ctx.strokeStyle = accent;
      ctx.lineWidth = 1.5;
      ctx.lineCap = "round";
      paths.forEach((pts, k) => {
        const head = reduced ? 2 : ((t / 2.8 + k * 0.37) % 1.5) * 1.1;
        const seen = pts.map((p) => {
          const q = proj(p[0], p[1], p[2]);
          return q[2] > 0 || q[0] * q[0] + q[1] * q[1] > 1 ? q : null;
        });
        for (let s = 0; s < S; s++) {
          const a = seen[s], b = seen[s + 1];
          if (!a || !b) continue;
          const d = head - s / S;
          ctx.globalAlpha = reduced ? 0.7 : d > 0 && d < 0.35 ? 1 - d / 0.35 : 0.2;
          ctx.beginPath();
          ctx.moveTo(cx + a[0] * R, cy - a[1] * R);
          ctx.lineTo(cx + b[0] * R, cy - b[1] * R);
          ctx.stroke();
        }
        const tip = seen[Math.round(head * S)];
        if (tip && head <= 1) {
          ctx.globalAlpha = 1;
          disc(tip[0], tip[1], 2.2);
          ctx.fill();
        }
        for (const e of [seen[0], seen[S]]) {
          if (!e) continue;
          ctx.globalAlpha = 0.9;
          disc(e[0], e[1], 2);
          ctx.fill();
        }
      });

      ctx.font = font;
      pins.forEach((p, k) => {
        const [x, y, z] = proj(p[0], p[1], p[2]);
        if (z <= 0) return;
        const fade = Math.min(1, z * 4);
        ctx.globalAlpha = fade;
        disc(x, y, 3);
        ctx.fill();
        const ph = reduced ? 0.4 : (t * 0.6 + k * 0.29) % 1;
        ctx.globalAlpha = fade * (1 - ph) * 0.7;
        disc(x, y, 3 + ph * 11);
        ctx.stroke();
        const name = markers[k].label;
        if (name && z > 0.3) {
          ctx.globalAlpha = Math.min(1, (z - 0.3) * 4) * 0.85;
          ctx.fillStyle = text;
          ctx.fillText(name, cx + x * R + 8, cy - y * R + 4);
          ctx.fillStyle = accent;
        }
      });
      ctx.globalAlpha = 1;
    };

    const moving = () => drag || Math.abs(v.vx) + Math.abs(v.vy) > 0.01;
    const frame = (now: number) => {
      raf = 0;
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 0;
      if (!drag) {
        v.lng += v.vx;
        v.lat += v.vy;
        v.vx *= 0.9;
        v.vy *= 0.9;
        if (!reduced && !hover && !focus) v.lng -= speed * dt;
      }
      v.lat = Math.max(-70, Math.min(70, v.lat));
      draw(now / 1000);
      last = now;
      if (inView && !document.hidden && (!reduced || moving())) {
        raf = requestAnimationFrame(frame);
      } else last = 0;
    };
    const kick = () => {
      if (!raf) raf = requestAnimationFrame(frame);
    };

    const resize = () => {
      const dpr = Math.min(devicePixelRatio || 1, 2);
      w = root.clientWidth;
      h = root.clientHeight;
      R = Math.min(w, h) * 0.42;
      canvas.width = w * dpr;
      canvas.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      kick();
    };

    const onDown = (e: PointerEvent) => {
      drag = { x: e.clientX, y: e.clientY };
      v.vx = v.vy = 0;
      root.setPointerCapture(e.pointerId);
      kick();
    };
    const onMove = (e: PointerEvent) => {
      if (!drag) return;
      const k = 57 / R;
      v.vx = -(e.clientX - drag.x) * k;
      v.vy = (e.clientY - drag.y) * k;
      v.lng += v.vx;
      v.lat += v.vy;
      drag = { x: e.clientX, y: e.clientY };
      kick();
    };
    const onUp = () => {
      drag = null;
      kick();
    };
    const onKey = (e: KeyboardEvent) => {
      const d = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, 1], ArrowDown: [0, -1] }[e.key];
      if (!d) return;
      e.preventDefault();
      if (reduced) {
        v.lng += d[0] * 15;
        v.lat += d[1] * 15;
      } else {
        v.vx += d[0];
        v.vy += d[1];
      }
      kick();
    };
    const flag = (e: Event) => {
      if (e.type.startsWith("pointer")) hover = e.type === "pointerenter";
      else focus = e.type === "focus";
      kick();
    };
    const onTheme = () => {
      resolve();
      kick();
    };

    const events: [string, EventListener][] = [
      ["pointerdown", onDown as EventListener],
      ["pointermove", onMove as EventListener],
      ["pointerup", onUp],
      ["pointercancel", onUp],
      ["keydown", onKey as EventListener],
      ["pointerenter", flag],
      ["pointerleave", flag],
      ["focus", flag],
      ["blur", flag],
    ];
    for (const [n, f] of events) root.addEventListener(n, f);
    document.addEventListener("visibilitychange", kick);
    const ro = new ResizeObserver(resize);
    ro.observe(root);
    const io = new IntersectionObserver(([e]) => {
      inView = e.isIntersecting;
      kick();
    });
    io.observe(root);
    const mo = new MutationObserver(onTheme);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style", "data-theme"] });
    resolve();

    return () => {
      cancelAnimationFrame(raf);
      for (const [n, f] of events) root.removeEventListener(n, f);
      document.removeEventListener("visibilitychange", kick);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
    };
  }, [markers, arcs, samples, speed, dotColor, accentColor, lat0, lng0]);

  const names = markers.flatMap((m) => m.label ?? []);

  return (
    <div
      ref={rootRef}
      role="img"
      tabIndex={0}
      aria-label={
        label ??
        `Globe${names.length ? ` marking ${names.join(", ")}` : ""}${
          arcs.length ? `, ${arcs.length} connection${arcs.length > 1 ? "s" : ""}` : ""
        }`
      }
      {...props}
      data-slot="globe"
      className={cn(
        "relative aspect-square w-full max-w-md cursor-grab touch-pan-y select-none rounded-full outline-none active:cursor-grabbing focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        className
      )}
    >
      <div
        aria-hidden
        className="absolute inset-[8%] rounded-full bg-background bg-radial-[at_30%_25%] from-brand/12 to-transparent to-75% shadow-[0_0_70px_-12px_color-mix(in_oklab,var(--brand)_45%,transparent)] ring-1 ring-brand/15"
      />
      <div
        aria-hidden
        className="absolute inset-[8%] rounded-full bg-radial from-transparent from-70% to-brand/20"
      />
      <canvas ref={canvasRef} aria-hidden className="absolute inset-0 size-full" />
    </div>
  );
}

"use client"

import React, { useEffect, useMemo, useRef, useState } from "react"
import { Pause, Play } from "lucide-react"
import { renderToString } from "react-dom/server"

import { Button } from "@/components/ui/button"

interface Icon {
  x: number
  y: number
  z: number
  scale: number
  opacity: number
  id: number
}

interface IconCloudProps {
  icons?: React.ReactNode[]
  images?: string[]
  showControl?: boolean
}

function easeOutCubic(t: number): number {
  return 1 - Math.pow(1 - t, 3)
}

export function IconCloud({
  icons,
  images,
  showControl = true,
}: IconCloudProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [isPaused, setIsPaused] = useState(false)
  const [lastMousePos, setLastMousePos] = useState({ x: 0, y: 0 })
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 })
  const [targetRotation, setTargetRotation] = useState<{
    x: number
    y: number
    startX: number
    startY: number
    distance: number
    startTime: number
    duration: number
  } | null>(null)
  const animationFrameRef = useRef<number>(0)
  const rotationRef = useRef({ x: 0, y: 0 })
  const iconCanvasesRef = useRef<HTMLCanvasElement[]>([])
  const imagesLoadedRef = useRef<boolean[]>([])

  // Pause animation if user prefers reduced motion
  useEffect(() => {
    const mediaQuery = window.matchMedia("(prefers-reduced-motion: reduce)")
    if (mediaQuery.matches) {
      setIsPaused(true)
    }

    const handleChange = (e: MediaQueryListEvent) => {
      setIsPaused(e.matches)
    }

    mediaQuery.addEventListener("change", handleChange)
    return () => mediaQuery.removeEventListener("change", handleChange)
  }, [])

  // Create icon canvases once when icons/images change
  useEffect(() => {
    if (!icons && !images) return

    const items = icons ?? images ?? []
    imagesLoadedRef.current = new Array(items.length).fill(false)

    const newIconCanvases = items.map((item, index) => {
      const offscreen = document.createElement("canvas")
      offscreen.width = 40
      offscreen.height = 40
      const offCtx = offscreen.getContext("2d")

      if (offCtx) {
        if (images) {
          // Handle image URLs directly
          const img = new Image()
          img.crossOrigin = "anonymous"
          img.src = items[index] as string
          img.onload = () => {
            offCtx.clearRect(0, 0, offscreen.width, offscreen.height)

            // Create circular clipping path
            offCtx.beginPath()
            offCtx.arc(20, 20, 20, 0, Math.PI * 2)
            offCtx.closePath()
            offCtx.clip()

            // Draw the image
            offCtx.drawImage(img, 0, 0, 40, 40)

            imagesLoadedRef.current[index] = true
          }
        } else {
          // Handle SVG icons
          offCtx.scale(0.4, 0.4)
          const svgString = renderToString(item as React.ReactElement)
          const img = new Image()
          img.src = "data:image/svg+xml;base64," + btoa(svgString)
          img.onload = () => {
            offCtx.clearRect(0, 0, offscreen.width, offscreen.height)
            offCtx.drawImage(img, 0, 0)
            imagesLoadedRef.current[index] = true
          }
        }
      }
      return offscreen
    })

    iconCanvasesRef.current = newIconCanvases
  }, [icons, images])

  // Generate initial icon positions on a sphere
  const iconPositions = useMemo(() => {
    const items = icons ?? images ?? []
    const newIcons: Icon[] = []
    const numIcons = items.length || 20

    // Fibonacci sphere parameters
    const offset = 2 / numIcons
    const increment = Math.PI * (3 - Math.sqrt(5))

    for (let i = 0; i < numIcons; i++) {
      const y = i * offset - 1 + offset / 2
      const r = Math.sqrt(1 - y * y)
      const phi = i * increment

      const x = Math.cos(phi) * r
      const z = Math.sin(phi) * r

      newIcons.push({
        x: x * 100,
        y: y * 100,
        z: z * 100,
        scale: 1,
        opacity: 1,
        id: i,
      })
    }
    return newIcons
  }, [icons, images])

  // Handle mouse events
  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const rect = canvasRef.current?.getBoundingClientRect()
    if (!rect || !canvasRef.current) return

    const x = e.clientX - rect.left
    const y = e.clientY - rect.top

    const ctx = canvasRef.current.getContext("2d")
    if (!ctx) return

    iconPositions.forEach((icon) => {
      const cosX = Math.cos(rotationRef.current.x)
      const sinX = Math.sin(rotationRef.current.x)
      const cosY = Math.cos(rotationRef.current.y)
      const sinY = Math.sin(rotationRef.current.y)

      const rotatedX = icon.x * cosY - icon.z * sinY
      const rotatedZ = icon.x * sinY + icon.z * cosY
      const rotatedY = icon.y * cosX + rotatedZ * sinX

      const screenX = canvasRef.current!.width / 2 + rotatedX
      const screenY = canvasRef.current!.height / 2 + rotatedY

      const scale = (rotatedZ + 200) / 300
      const radius = 20 * scale
      const dx = x - screenX
      const dy = y - screenY

      if (dx * dx + dy * dy < radius * radius) {
        const targetX = -Math.atan2(
          icon.y,
          Math.sqrt(icon.x * icon.x + icon.z * icon.z)
        )
        const targetY = Math.atan2(icon.x, icon.z)

        const currentX = rotationRef.current.x
        const currentY = rotationRef.current.y
        const distance = Math.sqrt(
          Math.pow(targetX - currentX, 2) + Math.pow(targetY - currentY, 2)
        )

        const duration = Math.min(2000, Math.max(800, distance * 1000))

        setTargetRotation({
          x: targetX,
          y: targetY,
          startX: currentX,
          startY: currentY,
          distance,
          startTime: performance.now(),
          duration,
        })
        return
      }
    })

    setIsDragging(true)
    setLastMousePos({ x: e.clientX, y: e.clientY })
  }

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const rect = canvasRef.current?.getBoundingClientRect()
    if (rect) {
      const x = e.clientX - rect.left
      const y = e.clientY - rect.top
      setMousePos({ x, y })
    }

    if (isDragging) {
      const deltaX = e.clientX - lastMousePos.x
      const deltaY = e.clientY - lastMousePos.y

      rotationRef.current = {
        x: rotationRef.current.x + deltaY * 0.002,
        y: rotationRef.current.y + deltaX * 0.002,
      }

      setLastMousePos({ x: e.clientX, y: e.clientY })
    }
  }

  const handleMouseUp = () => {
    setIsDragging(false)
  }

  // Animation and rendering
  useEffect(() => {
    const canvas = canvasRef.current
    const ctx = canvas?.getContext("2d")
    if (canvas && ctx) {
      const animate = () => {
        ctx.clearRect(0, 0, canvas.width, canvas.height)

        const centerX = canvas.width / 2
        const centerY = canvas.height / 2
        const maxDistance = Math.sqrt(centerX * centerX + centerY * centerY)
        const dx = mousePos.x - centerX
        const dy = mousePos.y - centerY
        const distance = Math.sqrt(dx * dx + dy * dy)
        const speed = 0.003 + (distance / maxDistance) * 0.01

        if (targetRotation) {
          const elapsed = performance.now() - targetRotation.startTime
          const progress = Math.min(1, elapsed / targetRotation.duration)
          const easedProgress = easeOutCubic(progress)

          rotationRef.current = {
            x:
              targetRotation.startX +
              (targetRotation.x - targetRotation.startX) * easedProgress,
            y:
              targetRotation.startY +
              (targetRotation.y - targetRotation.startY) * easedProgress,
          }

          if (progress >= 1) {
            setTargetRotation(null)
          }
        } else if (!isDragging && !isPaused) {
          rotationRef.current = {
            x: rotationRef.current.x + (dy / canvas.height) * speed,
            y: rotationRef.current.y + (dx / canvas.width) * speed,
          }
        }

        iconPositions.forEach((icon, index) => {
          const cosX = Math.cos(rotationRef.current.x)
          const sinX = Math.sin(rotationRef.current.x)
          const cosY = Math.cos(rotationRef.current.y)
          const sinY = Math.sin(rotationRef.current.y)

          const rotatedX = icon.x * cosY - icon.z * sinY
          const rotatedZ = icon.x * sinY + icon.z * cosY
          const rotatedY = icon.y * cosX + rotatedZ * sinX

          const scale = (rotatedZ + 200) / 300
          const opacity = Math.max(0.2, Math.min(1, (rotatedZ + 150) / 200))

          ctx.save()
          ctx.translate(
            canvas.width / 2 + rotatedX,
            canvas.height / 2 + rotatedY
          )
          ctx.scale(scale, scale)
          ctx.globalAlpha = opacity

          if (icons || images) {
            // Only try to render icons/images if they exist
            if (
              iconCanvasesRef.current[index] &&
              imagesLoadedRef.current[index]
            ) {
              ctx.drawImage(iconCanvasesRef.current[index], -20, -20, 40, 40)
            }
          } else {
            // Show numbered circles if no icons/images are provided
            ctx.beginPath()
            ctx.arc(0, 0, 20, 0, Math.PI * 2)
            ctx.fillStyle = "#4444ff"
            ctx.fill()
            ctx.fillStyle = "white"
            ctx.textAlign = "center"
            ctx.textBaseline = "middle"
            ctx.font = "16px Arial"
            ctx.fillText(`${icon.id + 1}`, 0, 0)
          }

          ctx.restore()
        })

        const hasPendingAssets =
          Boolean(icons || images) &&
          !imagesLoadedRef.current.every((loaded) => loaded)
        const shouldContinue =
          !isPaused || isDragging || targetRotation !== null || hasPendingAssets

        if (shouldContinue) {
          animationFrameRef.current = requestAnimationFrame(animate)
        }
      }

      animate()
    }

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current)
      }
    }
  }, [
    icons,
    images,
    iconPositions,
    isDragging,
    isPaused,
    mousePos,
    targetRotation,
  ])

  return (
    <div className="relative inline-block">
      <canvas
        ref={canvasRef}
        width={400}
        height={400}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        className="rounded-lg"
        aria-label="Interactive 3D Icon Cloud"
        role="img"
      />
      {showControl && (
        <Button
          variant="outline"
          size="icon"
          onClick={() => setIsPaused(!isPaused)}
          aria-label={isPaused ? "Play Animation" : "Pause Animation"}
          className="absolute top-2 right-2"
        >
          {isPaused ? <Play size={16} /> : <Pause size={16} />}
        </Button>
      )}
    </div>
  )
}

