"use client";

import { useSyncExternalStore } from "react";
import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

const noopSubscribe = () => () => {};

interface BackgroundBeamsProps {
  className?: string;
  /** Number of beams */
  count?: number;
}

/**
 * Decorative light beams flowing along curved paths — a full-section
 * background. Place inside a `relative overflow-hidden` container.
 */
export function BackgroundBeams({ className, count = 7 }: BackgroundBeamsProps) {
  // useReducedMotion() already knows the preference on the first client
  // render, but the server can't — keep the animated markup until hydrated.
  const hydrated = useSyncExternalStore(noopSubscribe, () => true, () => false);
  const reducedMotion = useReducedMotion() === true && hydrated;

  const paths = Array.from({ length: count }, (_, i) => {
    const o = i * 90;
    return `M-${300 + o} -${100 + i * 40} C ${-100 + o} ${120 + i * 30}, ${
      200 + o
    } ${180 + i * 30}, ${640 + o} ${440 + i * 40}`;
  });

  return (
    <div
      aria-hidden
      data-slot="background-beams"
      className={cn("pointer-events-none absolute inset-0", className)}
    >
      <svg
        className="size-full"
        viewBox="0 0 960 540"
        fill="none"
        preserveAspectRatio="xMidYMid slice"
      >
        {paths.map((d, i) => (
          <path
            key={`base-${i}`}
            d={d}
            stroke="var(--border)"
            strokeOpacity={0.35}
            strokeWidth={1}
          />
        ))}
        {!reducedMotion &&
          paths.map((d, i) => (
            <path
              key={`beam-${i}`}
              d={d}
              stroke={`url(#beam-gradient-${i})`}
              strokeWidth={1.5}
              strokeLinecap="round"
            />
          ))}
        {!reducedMotion && (
          <defs>
            {paths.map((_, i) => (
              <motion.linearGradient
                key={`grad-${i}`}
                id={`beam-gradient-${i}`}
                gradientUnits="userSpaceOnUse"
                initial={{ x1: "0%", x2: "5%", y1: "0%", y2: "5%" }}
                animate={{
                  x1: ["0%", "100%"],
                  x2: ["5%", "105%"],
                  y1: ["0%", "100%"],
                  y2: ["5%", "105%"],
                }}
                transition={{
                  duration: 6 + (i % 4) * 2,
                  delay: i * 1.1,
                  repeat: Infinity,
                  ease: "linear",
                }}
              >
                <stop stopColor="var(--brand-from)" stopOpacity="0" />
                <stop offset="30%" stopColor="var(--brand-from)" />
                <stop offset="60%" stopColor="var(--brand-to)" />
                <stop offset="100%" stopColor="var(--brand-to)" stopOpacity="0" />
              </motion.linearGradient>
            ))}
          </defs>
        )}
      </svg>
    </div>
  );
}

"use client";

import { useMemo } from "react";

import { cn } from "@/lib/utils";

// Nine tints: each brand stop at three strengths, all theme-aware.
const TINTS = [85, 65, 45].flatMap((p) =>
  ["from", "via", "to"].map((v) => `color-mix(in oklab, var(--brand-${v}) ${p}%, transparent)`)
);

interface BackgroundBoxesProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Number of rows (capped at 40) */
  rows?: number;
  /** Number of columns (capped at 40) */
  cols?: number;
  /** Cell edge length in px, before the isometric tilt */
  cellSize?: number;
  /** How long a lit cell takes to fade back, in ms */
  fade?: number;
}

/**
 * An isometric grid of cells that light up in random brand tints under the
 * pointer and fade slowly back. Absolutely positioned — place inside a
 * `relative overflow-hidden` section. Content above it blocks the pointer, so
 * give text wrappers `pointer-events-none` to keep the grid reactive.
 */
export function BackgroundBoxes({
  rows = 32,
  cols = 32,
  cellSize = 48,
  fade = 1400,
  className,
  ...props
}: BackgroundBoxesProps) {
  const r = Math.min(rows, 40);
  const c = Math.min(cols, 40);

  // Cells never re-render: hover colour is pure CSS, and one delegated
  // listener picks a fresh tint for whichever cell the pointer enters.
  const cells = useMemo(
    () =>
      Array.from({ length: r * c }, (_, i) => (
        <div
          key={i}
          className="border-r border-b border-border transition-[background-color] duration-(--fade) ease-out hover:bg-(--tint) hover:duration-0"
        />
      )),
    [r, c]
  );

  return (
    <div
      aria-hidden
      data-slot="background-boxes"
      className={cn("absolute inset-0 overflow-hidden", className)}
      {...props}
    >
      <div
        className="absolute top-1/2 left-1/2 grid border-t border-l border-border"
        style={
          {
            gridTemplateColumns: `repeat(${c}, ${cellSize}px)`,
            gridAutoRows: cellSize,
            transform: "translate(-50%, -50%) scaleY(0.58) rotate(-45deg)",
            "--fade": `${fade}ms`,
          } as React.CSSProperties
        }
        onPointerOver={(e) => {
          const cell = e.target as HTMLElement;
          if (cell !== e.currentTarget) {
            cell.style.setProperty("--tint", TINTS[(Math.random() * TINTS.length) | 0]);
          }
        }}
      >
        {cells}
      </div>
    </div>
  );
}

"use client"

import { useEffect, useRef, useState, type CSSProperties } from "react"

import { cn } from "@/lib/utils"

/**
 * Each pattern is the GLSL body of `float pattern(vec2 p, vec2 size, float t)`.
 * `p` is the position in CSS pixels from the bottom-left corner, `size` is
 * the field size in CSS pixels and `t` is the time in seconds. Return the
 * light level, where 0 is dark and 1 is full light. Add an entry here to add
 * a pattern; the `pattern` prop type follows.
 */
const PATTERNS = {
  // A low sun on the bottom edge, with haze bands that drift up through it.
  horizon: `
    float r = max(min(size.x * 0.42, size.y * 0.8), 90.0);
    vec2 d = (p - vec2(0.5 * size.x, -0.15 * r)) / vec2(1.25 * r, r);
    float wobble = fbm(vec2(atan(d.y, d.x) * 1.8, t * 0.04)) - 0.5;
    float rim = length(d) * (1.0 + 0.14 * wobble);
    float sun = exp(-3.4 * max(rim - 0.42, 0.0)) * 0.78;
    float h = p.y / r;
    float drift = (fbm(vec2(p.x / 320.0, t * 0.03)) - 0.5) * 2.4;
    float band = 0.5 + 0.5 * sin(log(1.0 + 7.0 * h) * 8.0 - t * 0.45 + drift);
    float haze = smoothstep(0.25, 0.95, band) * exp(-1.9 * h) * 0.5;
    float ground = exp(-p.y / 22.0) * 0.32;
    float sides = smoothstep(0.0, 0.2, p.x / size.x) * smoothstep(1.0, 0.8, p.x / size.x);
    return (sun * (1.0 + haze) + haze * 0.35 + ground) * sides * (1.0 + 0.04 * sin(t * 0.4));
  `,
  // A soft orb in the middle that breathes and wanders a little.
  glow: `
    vec2 c = 0.5 * size + vec2(sin(t * 0.21), cos(t * 0.17)) * 0.05 * size;
    float r = 0.5 * min(size.x, size.y);
    float d = length(p - c) / r;
    float n = fbm(p / 170.0 + vec2(t * 0.05, -t * 0.04));
    return exp(-1.7 * d * d) * (0.75 + 0.45 * n) + 0.12 * n * exp(-d);
  `,
  // Curtains of light that hang from the top and sway.
  aurora: `
    float sway = fbm(vec2(p.x / 600.0, t * 0.05));
    float d = p.y / size.y - (0.45 + 0.35 * (sway - 0.5));
    float curtain = d > 0.0 ? exp(-d * 4.0) : exp(d * 22.0);
    float rays = fbm(vec2(p.x / 70.0 + sway * 6.0, p.y / 900.0 - t * 0.08));
    float shimmer = fbm(vec2(p.x / 40.0 - t * 0.05, 3.0));
    return curtain * (0.25 + 0.75 * smoothstep(0.3, 0.75, rays)) * (0.6 + 0.5 * shimmer);
  `,
  // Slow diagonal swells, like dunes or contour lines.
  waves: `
    vec2 q = p / 32.0;
    float warp = fbm(q * 0.09 + vec2(t * 0.035, t * 0.02));
    float s = 0.5 + 0.5 * sin(q.x * 0.9 + q.y * 0.6 + warp * 5.0 - t * 0.4);
    float crest = s * s * s * s;
    return crest * (0.5 + 0.5 * p.y / size.y) + 0.12 * warp;
  `,
  // Drifting clouds that fill the whole area evenly.
  clouds: `
    float n = fbm(p / 210.0 + vec2(t * 0.03, t * 0.012));
    float m = fbm(p / 80.0 - vec2(t * 0.02, 0.0));
    return smoothstep(0.28, 0.78, n) * (0.7 + 0.5 * m);
  `,
} as const

export type DitherPattern = keyof typeof PATTERNS

/** One colour, or a `[low, mid, high]` ramp from dim dots to bright dots. */
export type DitherColor = string | readonly [string, string, string]

export interface DitherFieldProps extends Omit<
  React.ComponentPropsWithoutRef<"div">,
  "color"
> {
  /**
   * The procedural light field that the dots follow.
   * @default "horizon"
   */
  pattern?: DitherPattern
  /**
   * An image or video URL to dither instead of the pattern. Bright areas get
   * more dots. URLs ending in .mp4, .webm, .ogv, .mov or .m4v (or
   * `data:video/` URLs) play as muted, looping video. Remote files must allow
   * CORS.
   */
  src?: string
  /**
   * Any CSS colour, including `var(--primary)` and `currentColor`, or a
   * `[low, mid, high]` ramp. One colour fades from 35% to full opacity.
   * @default "currentColor"
   */
  color?: DitherColor
  /**
   * The size of one dot in CSS pixels. Dots snap to whole device pixels.
   * @default 1
   */
  dotSize?: number
  /**
   * Brightness of the field. 0 shows only the pointer glow; above 1 fills more.
   * @default 0.75
   */
  intensity?: number
  /**
   * Animation speed multiplier. `0` holds a still frame.
   * @default 1
   */
  speed?: number
  /**
   * Frame rate cap. The dots read as a still texture, so 30 is plenty.
   * @default 30
   */
  fps?: number
  /**
   * Brighten the field around the mouse, the pen or a held finger.
   * @default true
   */
  interactive?: boolean
}

type Rgba = [number, number, number, number]

type Media = HTMLImageElement | HTMLVideoElement

type Renderer = {
  /** Sizes the dot grid (canvas pixels) and the field (CSS pixels). */
  resize: (dotsX: number, dotsY: number, cssX: number, cssY: number) => void
  setRamp: (ramp: Rgba[]) => void
  setIntensity: (intensity: number) => void
  setMedia: (media: Media | null) => void
  draw: (time: number, pointer: [number, number, number]) => void
  dispose: () => void
}

const VERTEX = `#version 300 es
void main() {
  vec2 corner = vec2(gl_VertexID == 1 ? 3.0 : -1.0, gl_VertexID == 2 ? 3.0 : -1.0);
  gl_Position = vec4(corner, 0.0, 1.0);
}`

const FIELD_HEADER = `#version 300 es
precision highp float;
uniform vec2 uSize;
uniform vec2 uView;
uniform float uTime;
out vec4 outColor;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p) {
  float sum = 0.0;
  float amp = 0.5;
  mat2 turn = mat2(0.8, 0.6, -0.6, 0.8);
  for (int i = 0; i < 5; i++) {
    sum += amp * noise(p);
    p = turn * p * 2.0 + 11.7;
    amp *= 0.5;
  }
  return sum;
}
`

const FIELD_MAIN = `
void main() {
  vec2 p = gl_FragCoord.xy / uView * uSize;
  float v = pattern(p, uSize, uTime);
  outColor = vec4(clamp(v, 0.0, 1.0), 0.0, 0.0, 1.0);
}`

// Image and video: luminance under a cover fit, so bright areas get more dots.
const MEDIA_PATTERN = `
uniform sampler2D uMedia;
uniform vec2 uMediaSize;

float pattern(vec2 p, vec2 size, float t) {
  float scale = max(size.x / uMediaSize.x, size.y / uMediaSize.y);
  vec2 uv = (p - 0.5 * size) / (uMediaSize * scale) + 0.5;
  vec4 c = texture(uMedia, vec2(uv.x, 1.0 - uv.y));
  return dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));
}
`

const DITHER = `#version 300 es
precision highp float;
uniform sampler2D uField;
uniform vec2 uView;
uniform vec4 uLow;
uniform vec4 uMid;
uniform vec4 uHigh;
uniform float uIntensity;
uniform vec3 uPointer;
uniform float uDot;
out vec4 outColor;

// 8x8 ordered-dither threshold, built from the 2x2 matrix [0 2; 3 1]. The
// lowest bit of the cell position carries the largest weight.
float threshold(vec2 cell) {
  vec2 c = floor(cell);
  float sum = 0.0;
  float weight = 16.0;
  for (int i = 0; i < 3; i++) {
    vec2 b = mod(c, 2.0);
    sum += weight * mod(2.0 * b.x + 3.0 * b.y, 4.0);
    c = floor(c * 0.5);
    weight *= 0.25;
  }
  return (sum + 0.5) / 64.0;
}

void main() {
  vec2 uv = gl_FragCoord.xy / uView;
  float base = texture(uField, uv).r;
  float halo = textureLod(uField, uv, 1.0).r * 0.45
    + textureLod(uField, uv, 2.2).r * 0.35
    + textureLod(uField, uv, 3.4).r * 0.2;
  float v = base + 0.55 * halo;
  float over = max(v - 0.85, 0.0);
  v = min(v, 0.85) + over / (1.0 + 4.0 * over);
  v = clamp(v * uIntensity, 0.0, 1.0);
  // The pointer glow comes after intensity, so it shows on quiet fields too.
  vec2 away = gl_FragCoord.xy * uDot - uPointer.xy;
  v = min(v + uPointer.z * exp(-dot(away, away) / 28000.0) * (0.35 + 0.5 * v), 1.0);
  // Drop the faintest light, so empty areas stay empty instead of showing
  // a sparse, even grid.
  v = max(v - 0.02, 0.0) / 0.98;
  float on = step(threshold(gl_FragCoord.xy), v);
  vec4 c = v < 0.5 ? mix(uLow, uMid, v * 2.0) : mix(uMid, uHigh, v * 2.0 - 1.0);
  outColor = vec4(c.rgb * c.a, c.a) * on;
}`

/** The light field renders at this fraction of the CSS size, then blooms. */
const FIELD_SCALE = 0.6
const POINTER_EASE = 6
const VIDEO_FILE = /^data:video\/|\.(mp4|webm|ogv|mov|m4v)(\?|#|$)/i

function compile(gl: WebGL2RenderingContext, fragment: string) {
  const program = gl.createProgram()
  for (const [type, source] of [
    [gl.VERTEX_SHADER, VERTEX],
    [gl.FRAGMENT_SHADER, fragment],
  ] as const) {
    const shader = gl.createShader(type)
    if (!shader) return null
    gl.shaderSource(shader, source)
    gl.compileShader(shader)
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      console.warn("DitherField: shader error", gl.getShaderInfoLog(shader))
    }
    gl.attachShader(program, shader)
    gl.deleteShader(shader)
  }
  gl.linkProgram(program)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program)
    return null
  }
  return program
}

function createTexture(gl: WebGL2RenderingContext, mipmaps: boolean) {
  const texture = gl.createTexture()
  gl.bindTexture(gl.TEXTURE_2D, texture)
  const min = mipmaps ? gl.LINEAR_MIPMAP_LINEAR : gl.LINEAR
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, min)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
  return texture
}

/**
 * Two passes: the light field renders small into a mipmapped texture, then
 * the dither pass reads it with a bloom from the blurred mip levels and
 * thresholds it into dots, one canvas pixel per dot. Returns null when the
 * shaders do not compile, so the caller can fall back.
 */
function createRenderer(
  gl: WebGL2RenderingContext,
  patternSource: string
): Renderer | null {
  const field = compile(gl, `${FIELD_HEADER}${patternSource}${FIELD_MAIN}`)
  const dither = compile(gl, DITHER)
  if (!field || !dither) {
    gl.deleteProgram(field)
    gl.deleteProgram(dither)
    return null
  }
  const at = (program: WebGLProgram, name: string) =>
    gl.getUniformLocation(program, name)

  const fieldTexture = createTexture(gl, true)
  const mediaTexture = createTexture(gl, false)
  const framebuffer = gl.createFramebuffer()
  let media: Media | null = null
  // Images upload once; video uploads a new frame on every draw.
  let mediaStale = false
  let view = [1, 1]
  let fieldView = [1, 1]
  let css = [1, 1]

  gl.useProgram(dither)
  gl.uniform1i(at(dither, "uField"), 0)
  gl.useProgram(field)
  gl.uniform1i(at(field, "uMedia"), 1)

  return {
    resize(dotsX, dotsY, cssX, cssY) {
      view = [dotsX, dotsY]
      css = [cssX, cssY]
      fieldView = [
        Math.max(1, Math.round(cssX * FIELD_SCALE)),
        Math.max(1, Math.round(cssY * FIELD_SCALE)),
      ]
      gl.activeTexture(gl.TEXTURE0)
      gl.bindTexture(gl.TEXTURE_2D, fieldTexture)
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        fieldView[0],
        fieldView[1],
        0,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        null
      )
      gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer)
      gl.framebufferTexture2D(
        gl.FRAMEBUFFER,
        gl.COLOR_ATTACHMENT0,
        gl.TEXTURE_2D,
        fieldTexture,
        0
      )
      gl.bindFramebuffer(gl.FRAMEBUFFER, null)
    },
    setRamp([low, mid, high]) {
      gl.useProgram(dither)
      gl.uniform4f(at(dither, "uLow"), ...low)
      gl.uniform4f(at(dither, "uMid"), ...mid)
      gl.uniform4f(at(dither, "uHigh"), ...high)
    },
    setIntensity(intensity) {
      gl.useProgram(dither)
      gl.uniform1f(at(dither, "uIntensity"), intensity)
    },
    setMedia(next) {
      media = next
      mediaStale = true
    },
    draw(time, pointer) {
      gl.useProgram(field)
      if (media) {
        const source = media
        const isVideo = source instanceof HTMLVideoElement
        const width = isVideo ? source.videoWidth : source.naturalWidth
        const height = isVideo ? source.videoHeight : source.naturalHeight
        if (!width || !height) return
        if (mediaStale || isVideo) {
          gl.activeTexture(gl.TEXTURE1)
          gl.bindTexture(gl.TEXTURE_2D, mediaTexture)
          gl.texImage2D(
            gl.TEXTURE_2D,
            0,
            gl.RGBA,
            gl.RGBA,
            gl.UNSIGNED_BYTE,
            source
          )
          gl.uniform2f(at(field, "uMediaSize"), width, height)
          mediaStale = false
        }
      }
      gl.uniform2f(at(field, "uSize"), css[0], css[1])
      gl.uniform2f(at(field, "uView"), fieldView[0], fieldView[1])
      gl.uniform1f(at(field, "uTime"), time)
      gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer)
      gl.viewport(0, 0, fieldView[0], fieldView[1])
      gl.drawArrays(gl.TRIANGLES, 0, 3)
      gl.bindFramebuffer(gl.FRAMEBUFFER, null)
      gl.activeTexture(gl.TEXTURE0)
      gl.bindTexture(gl.TEXTURE_2D, fieldTexture)
      gl.generateMipmap(gl.TEXTURE_2D)

      gl.useProgram(dither)
      gl.uniform2f(at(dither, "uView"), view[0], view[1])
      gl.uniform1f(at(dither, "uDot"), css[0] / view[0])
      gl.uniform3f(at(dither, "uPointer"), ...pointer)
      gl.viewport(0, 0, view[0], view[1])
      gl.drawArrays(gl.TRIANGLES, 0, 3)
    },
    dispose() {
      gl.deleteProgram(field)
      gl.deleteProgram(dither)
      gl.deleteTexture(fieldTexture)
      gl.deleteTexture(mediaTexture)
      gl.deleteFramebuffer(framebuffer)
    },
  }
}

const toRamp = (color: DitherColor) =>
  typeof color === "string" ? [color, color, color] : [...color]

/**
 * Resolves CSS colours (`var(--x)`, `currentColor`, `oklch()`) in the
 * context of `host`, then reads them back as straight RGBA through a
 * 1x1 canvas. A single colour fades from 35% to full opacity.
 */
function resolveRamp(host: HTMLElement, color: DitherColor): Rgba[] {
  const probe = document.createElement("span")
  probe.style.display = "none"
  host.appendChild(probe)
  const context = document
    .createElement("canvas")
    .getContext("2d", { willReadFrequently: true })
  const fades = typeof color === "string" ? [0.35, 0.75, 1] : [1, 1, 1]
  const ramp = toRamp(color).map((value, index): Rgba => {
    probe.style.color = ""
    probe.style.color = value
    if (!context) return [0.5, 0.5, 0.5, fades[index]]
    context.clearRect(0, 0, 1, 1)
    context.fillStyle = "#808080"
    context.fillStyle = getComputedStyle(probe).color
    context.fillRect(0, 0, 1, 1)
    const [r, g, b, a] = context.getImageData(0, 0, 1, 1).data
    return [r / 255, g / 255, b / 255, (a / 255) * fades[index]]
  })
  probe.remove()
  return ramp
}

function loadMedia(
  src: string,
  onReady: (media: Media) => void,
  onError: () => void
) {
  if (VIDEO_FILE.test(src)) {
    const video = document.createElement("video")
    video.crossOrigin = "anonymous"
    video.muted = true
    video.loop = true
    video.playsInline = true
    video.preload = "auto"
    video.addEventListener("loadeddata", () => onReady(video), { once: true })
    video.addEventListener("error", onError, { once: true })
    video.src = src
    return video
  }
  const image = new Image()
  image.crossOrigin = "anonymous"
  image.decoding = "async"
  image.addEventListener("load", () => onReady(image), { once: true })
  image.addEventListener("error", onError, { once: true })
  image.src = src
  return image
}

const ease = (from: number, to: number, rate: number, dt: number) =>
  from + (to - from) * (1 - Math.exp(-rate * dt))

/**
 * An animated ordered-dither background. A soft light field, or an image or
 * video, is thresholded against an 8x8 Bayer matrix into crisp square dots
 * coloured from a three-stop ramp. Children render above the dots.
 */
export function DitherField({
  pattern = "horizon",
  src,
  color = "currentColor",
  dotSize = 1,
  intensity = 0.75,
  speed = 1,
  fps = 30,
  interactive = true,
  className,
  children,
  ...props
}: DitherFieldProps) {
  const rootRef = useRef<HTMLDivElement>(null)
  const layerRef = useRef<HTMLDivElement>(null)
  // The GL context only exists while the field is near the viewport, so a
  // page with many fields stays under the browser's cap of live contexts.
  const [near, setNear] = useState(false)
  const [fallback, setFallback] = useState(false)
  // Bumped when the browser restores a lost WebGL context.
  const [contextKey, setContextKey] = useState(0)
  // Read every frame, so changing them never rebuilds the GL state.
  const live = useRef({ color, intensity, speed, fps, interactive })
  useEffect(() => {
    live.current = { color, intensity, speed, fps, interactive }
  })
  const repaint = useRef(() => {})
  // Kept across rebuilds, so a field that scrolls back into view resumes.
  const time = useRef(10)
  const shown = useRef(false)
  const colorKey = toRamp(color).join("|")

  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    const observer = new IntersectionObserver(
      ([entry]) => setNear(entry.isIntersecting),
      { rootMargin: "100px" }
    )
    observer.observe(root)
    return () => observer.disconnect()
  }, [])

  useEffect(() => {
    const root = rootRef.current
    const layer = layerRef.current
    if (!near || !root || !layer) return

    const canvas = document.createElement("canvas")
    canvas.className =
      "absolute top-0 left-0 opacity-0 transition-opacity duration-700 [image-rendering:pixelated] data-[ready]:opacity-100 motion-reduce:transition-none"
    const gl = canvas.getContext("webgl2", {
      alpha: true,
      premultipliedAlpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      powerPreference: "low-power",
    })
    const renderer = gl
      ? createRenderer(
          gl,
          src
            ? MEDIA_PATTERN
            : `float pattern(vec2 p, vec2 size, float t) {${PATTERNS[pattern]}}`
        )
      : null
    if (!gl || !renderer) {
      gl?.getExtension("WEBGL_lose_context")?.loseContext()
      setFallback(true)
      return
    }
    setFallback(false)
    // A field that comes back into view skips the fade-in.
    if (shown.current) canvas.dataset.ready = ""
    layer.appendChild(canvas)

    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)")
    const pointer = { x: 0, y: 0, clientX: 0, clientY: 0, on: false, hover: 0 }
    let previous = 0
    let frame = 0
    let cssHeight = 0
    let ready = !src
    let lost = false
    let disposed = false

    const draw = () => {
      if (!ready || !cssHeight || lost) return
      renderer.draw(time.current, [pointer.x, pointer.y, pointer.hover])
      canvas.dataset.ready = ""
      shown.current = true
    }

    const paint = () => {
      renderer.setRamp(resolveRamp(root, live.current.color))
      renderer.setIntensity(live.current.intensity)
      draw()
    }
    repaint.current = paint
    // Theme changes can arrive in bursts; resolve the colours once a frame.
    let paintFrame = 0
    const schedulePaint = () => {
      cancelAnimationFrame(paintFrame)
      paintFrame = requestAnimationFrame(paint)
    }

    // One dot is a whole number of device pixels, so dots stay crisp
    // squares on any screen. The canvas may overhang the root by under a
    // dot; the root clips it. Layout size, so transforms on a parent (an
    // entrance animation, say) do not shrink the grid.
    const resize = () => {
      const width = root.clientWidth
      const height = root.clientHeight
      if (!width || !height) return
      const dpr = window.devicePixelRatio || 1
      const devicePerDot = Math.max(1, Math.round(dotSize * dpr))
      const cssPerDot = devicePerDot / dpr
      const dotsX = Math.ceil((width * dpr) / devicePerDot)
      const dotsY = Math.ceil((height * dpr) / devicePerDot)
      cssHeight = dotsY * cssPerDot
      canvas.width = dotsX
      canvas.height = dotsY
      canvas.style.width = `${dotsX * cssPerDot}px`
      canvas.style.height = `${cssHeight}px`
      renderer.resize(dotsX, dotsY, dotsX * cssPerDot, cssHeight)
      draw()
    }

    // Animate only while the tab is visible and motion is allowed.
    // Otherwise hold the last frame.
    const sync = () => {
      const running =
        ready && !lost && !document.hidden && !reducedMotion.matches
      if (running && !frame) {
        previous = 0
        frame = requestAnimationFrame(tick)
        video?.play().catch(() => {})
      } else if (!running && frame) {
        cancelAnimationFrame(frame)
        frame = 0
        video?.pause()
      }
    }

    const tick = (now: number) => {
      frame = requestAnimationFrame(tick)
      const { speed, fps, interactive } = live.current
      if (previous && now - previous < 1000 / Math.max(fps, 1) - 2) return
      // Real time since the last drawn frame, so a low fps keeps the same
      // speed. The clock restarts on resume, and a stalled main thread
      // cannot jump the field by more than 2 s.
      const dt = previous ? Math.min((now - previous) / 1000, 2) : 0
      previous = now
      time.current += dt * speed
      const box = root.getBoundingClientRect()
      const left = box.left + root.clientLeft
      const top = box.top + root.clientTop
      const inside =
        interactive &&
        pointer.on &&
        pointer.clientX >= box.left &&
        pointer.clientX <= box.right &&
        pointer.clientY >= box.top &&
        pointer.clientY <= box.bottom
      pointer.x = ease(pointer.x, pointer.clientX - left, POINTER_EASE, dt)
      pointer.y = ease(
        pointer.y,
        top + cssHeight - pointer.clientY,
        POINTER_EASE,
        dt
      )
      pointer.hover = ease(pointer.hover, inside ? 1 : 0, 4, dt)
      draw()
    }

    const media = src
      ? loadMedia(
          src,
          (source) => {
            if (disposed) return
            renderer.setMedia(source)
            ready = true
            draw()
            sync()
          },
          () => {
            if (!disposed) setFallback(true)
          }
        )
      : null
    const video = media instanceof HTMLVideoElement ? media : null

    const onPointer = (event: PointerEvent) => {
      // A finger only counts while it is down. Hover events from a lifted
      // finger would leave the glow stuck where it last tapped.
      if (event.pointerType === "touch" && event.buttons === 0) return
      if (!pointer.on) {
        const box = root.getBoundingClientRect()
        pointer.x = event.clientX - box.left - root.clientLeft
        pointer.y = box.top + root.clientTop + cssHeight - event.clientY
      }
      pointer.clientX = event.clientX
      pointer.clientY = event.clientY
      pointer.on = true
    }
    const onLeave = () => {
      pointer.on = false
    }
    // Lifting the finger, or the browser taking over the touch to scroll,
    // fades the glow out. The listeners are passive, so scrolling is never
    // blocked.
    const onTouchEnd = (event: PointerEvent) => {
      if (event.pointerType === "touch") pointer.on = false
    }

    // A move to a screen with another pixel ratio changes the dot size
    // without resizing the element.
    let ratioQuery: MediaQueryList | null = null
    const watchRatio = () => {
      ratioQuery?.removeEventListener("change", onRatio)
      ratioQuery = window.matchMedia(
        `(resolution: ${window.devicePixelRatio}dppx)`
      )
      ratioQuery.addEventListener("change", onRatio)
    }
    const onRatio = () => {
      resize()
      watchRatio()
    }

    // A lost context shows the CSS dots until the browser gives it back.
    const onLost = (event: Event) => {
      event.preventDefault()
      lost = true
      sync()
      setFallback(true)
    }
    const onRestored = () => setContextKey((key) => key + 1)

    const resizeObserver = new ResizeObserver(resize)
    // Theme switches usually toggle a class or attribute on <html>.
    const themeObserver = new MutationObserver(schedulePaint)
    const darkQuery = window.matchMedia("(prefers-color-scheme: dark)")

    resize()
    paint()
    sync()
    watchRatio()
    resizeObserver.observe(root)
    themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme"],
    })
    // The root's own class or style can change `currentColor` or a CSS
    // variable in the ramp, for example text-red-500 to text-blue-500.
    themeObserver.observe(root, {
      attributes: true,
      attributeFilter: ["class", "style"],
    })
    darkQuery.addEventListener("change", schedulePaint)
    reducedMotion.addEventListener("change", sync)
    document.addEventListener("visibilitychange", sync)
    window.addEventListener("pointerdown", onPointer, { passive: true })
    window.addEventListener("pointermove", onPointer, { passive: true })
    window.addEventListener("pointerup", onTouchEnd, { passive: true })
    window.addEventListener("pointercancel", onTouchEnd, { passive: true })
    document.documentElement.addEventListener("pointerleave", onLeave)
    canvas.addEventListener("webglcontextlost", onLost)
    canvas.addEventListener("webglcontextrestored", onRestored)

    return () => {
      disposed = true
      cancelAnimationFrame(frame)
      cancelAnimationFrame(paintFrame)
      repaint.current = () => {}
      resizeObserver.disconnect()
      themeObserver.disconnect()
      ratioQuery?.removeEventListener("change", onRatio)
      darkQuery.removeEventListener("change", schedulePaint)
      reducedMotion.removeEventListener("change", sync)
      document.removeEventListener("visibilitychange", sync)
      window.removeEventListener("pointerdown", onPointer)
      window.removeEventListener("pointermove", onPointer)
      window.removeEventListener("pointerup", onTouchEnd)
      window.removeEventListener("pointercancel", onTouchEnd)
      document.documentElement.removeEventListener("pointerleave", onLeave)
      canvas.removeEventListener("webglcontextlost", onLost)
      canvas.removeEventListener("webglcontextrestored", onRestored)
      if (video) {
        video.pause()
        video.removeAttribute("src")
        video.load()
      } else {
        media?.removeAttribute("src")
      }
      renderer.dispose()
      gl.getExtension("WEBGL_lose_context")?.loseContext()
      canvas.remove()
    }
  }, [near, pattern, src, dotSize, contextKey])

  useEffect(() => {
    repaint.current()
  }, [colorKey, intensity])

  const [, mid] = toRamp(color)
  const fallbackStyle: CSSProperties = {
    backgroundImage: `radial-gradient(${mid} 0.6px, transparent 0.9px)`,
    backgroundSize: `${3 * dotSize}px ${3 * dotSize}px`,
    maskImage: "radial-gradient(ellipse at 50% 70%, black, transparent 75%)",
    WebkitMaskImage:
      "radial-gradient(ellipse at 50% 70%, black, transparent 75%)",
    opacity: Math.min(1, intensity),
  }

  return (
    <div
      ref={rootRef}
      className={cn("relative isolate overflow-hidden", className)}
      {...props}
    >
      <div
        ref={layerRef}
        aria-hidden="true"
        className="pointer-events-none absolute inset-0 -z-10"
        style={fallback ? fallbackStyle : undefined}
      />
      {children}
    </div>
  )
}

"use client"

import React, { useEffect, useId, useRef, useState } from "react"
import { motion } from "motion/react"

import { cn } from "@/lib/utils"

/**
 *  DotPattern Component Props
 *
 * @param {number} [width=16] - The horizontal spacing between dots
 * @param {number} [height=16] - The vertical spacing between dots
 * @param {number} [x=0] - The x-offset of the entire pattern
 * @param {number} [y=0] - The y-offset of the entire pattern
 * @param {number} [cx=1] - The x-offset of individual dots
 * @param {number} [cy=1] - The y-offset of individual dots
 * @param {number} [cr=1] - The radius of each dot
 * @param {string} [className] - Additional CSS classes to apply to the SVG container
 * @param {boolean} [glow=false] - Whether dots should have a glowing animation effect
 */
interface DotPatternProps extends React.SVGProps<SVGSVGElement> {
  width?: number
  height?: number
  x?: number
  y?: number
  cx?: number
  cy?: number
  cr?: number
  className?: string
  glow?: boolean
  [key: string]: unknown
}

function Dot({
  cx,
  cy,
  r,
  glow,
  gradientId,
}: {
  cx: number
  cy: number
  r: number
  glow: boolean
  gradientId: string
}) {
  const [timing] = useState(() => ({
    delay: Math.random() * 5,
    duration: Math.random() * 3 + 2,
  }))

  return (
    <motion.circle
      cx={cx}
      cy={cy}
      r={r}
      fill={glow ? `url(#${gradientId})` : "currentColor"}
      initial={glow ? { opacity: 0.4, scale: 1 } : {}}
      animate={
        glow
          ? {
              opacity: [0.4, 1, 0.4],
              scale: [1, 1.5, 1],
            }
          : {}
      }
      transition={
        glow
          ? {
              duration: timing.duration,
              repeat: Infinity,
              repeatType: "reverse",
              delay: timing.delay,
              ease: "easeInOut",
            }
          : {}
      }
    />
  )
}

/**
 * DotPattern Component
 *
 * A React component that creates an animated or static dot pattern background using SVG.
 * The pattern automatically adjusts to fill its container and can optionally display glowing dots.
 *
 * @component
 *
 * @see DotPatternProps for the props interface.
 *
 * @example
 * // Basic usage
 * <DotPattern />
 *
 * // With glowing effect and custom spacing
 * <DotPattern
 *   width={20}
 *   height={20}
 *   glow={true}
 *   className="opacity-50"
 * />
 *
 * @notes
 * - The component is client-side only ("use client")
 * - Automatically responds to container size changes
 * - When glow is enabled, dots will animate with random delays and durations
 * - Uses Motion for animations
 * - Dots color can be controlled via the text color utility classes
 */

export function DotPattern({
  width = 16,
  height = 16,
  x = 0,
  y = 0,
  cx = 1,
  cy = 1,
  cr = 1,
  className,
  glow = false,
  ...props
}: DotPatternProps) {
  const id = useId()
  const containerRef = useRef<SVGSVGElement>(null)
  const [dimensions, setDimensions] = useState({ width: 0, height: 0 })

  useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect()
        setDimensions({ width, height })
      }
    }

    updateDimensions()
    window.addEventListener("resize", updateDimensions)
    return () => window.removeEventListener("resize", updateDimensions)
  }, [])

  const dots = Array.from(
    {
      length:
        Math.ceil(dimensions.width / width) *
        Math.ceil(dimensions.height / height),
    },
    (_, i) => {
      const col = i % Math.ceil(dimensions.width / width)
      const row = Math.floor(i / Math.ceil(dimensions.width / width))
      return {
        x: col * width + cx + x,
        y: row * height + cy + y,
      }
    }
  )

  return (
    <svg
      ref={containerRef}
      aria-hidden="true"
      className={cn(
        "pointer-events-none absolute inset-0 h-full w-full text-neutral-400/80",
        className
      )}
      {...props}
    >
      <defs>
        <radialGradient id={`${id}-gradient`}>
          <stop offset="0%" stopColor="currentColor" stopOpacity="1" />
          <stop offset="100%" stopColor="currentColor" stopOpacity="0" />
        </radialGradient>
      </defs>
      {dots.map((dot) => (
        <Dot
          key={`${dot.x}-${dot.y}`}
          cx={dot.x}
          cy={dot.y}
          r={cr}
          glow={glow}
          gradientId={`${id}-gradient`}
        />
      ))}
    </svg>
  )
}

"use client";

import { useEffect, useRef } from "react";

import { cn } from "@/lib/utils";

interface DottedGlowBackgroundProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Distance between dot centres in px */
  gap?: number;
  /** Dot radius in px (lit dots grow up to 1.6×) */
  radius?: number;
  /** Opacity of unlit dots, 0–1 */
  opacity?: number;
  /** Glow travel speed multiplier */
  speed?: number;
  /** Number of travelling glows */
  glows?: number;
  /** Pause while the pointer is over the parent element (focus inside it always pauses) */
  pauseOnHover?: boolean;
}

const LEVELS = 16;

// Resolves any CSS colour (oklch tokens included) to "r,g,b" via a 1×1 canvas.
function rgb(color: string) {
  const c = document.createElement("canvas").getContext("2d", { willReadFrequently: true })!;
  c.fillStyle = color;
  c.fillRect(0, 0, 1, 1);
  return [...c.getImageData(0, 0, 1, 1).data.slice(0, 3)];
}

/**
 * A canvas dot grid with soft glows drifting across it; dots near a glow
 * brighten, grow and tint toward `--brand`. Unlit dots use the inherited text
 * colour. Absolutely positioned — place inside a `relative overflow-hidden`
 * element.
 */
export function DottedGlowBackground({
  gap = 18,
  radius = 1.2,
  opacity = 0.25,
  speed = 1,
  glows = 3,
  pauseOnHover = true,
  className,
  ...props
}: DottedGlowBackgroundProps) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const el = ref.current!;
    const ctx = el.getContext("2d");
    const host = el.parentElement?.parentElement;
    if (!ctx || !host) return;
    const mq = matchMedia("(prefers-reduced-motion: reduce)");
    let w = 0;
    let h = 0;
    let t = 0;
    let last = 0;
    let raf = 0;
    let seen = false;
    let hover = false;
    let focus = false;
    let tint = "0,0,0";
    let styles: string[] = [];

    const colors = () => {
      const cs = getComputedStyle(el);
      const a = rgb(cs.color);
      const b = rgb(cs.getPropertyValue("--brand") || cs.color);
      tint = b.join();
      styles = Array.from({ length: LEVELS + 1 }, (_, i) => {
        const k = i / LEVELS;
        return `rgba(${a.map((v, j) => Math.round(v + (b[j] - v) * k))},${opacity + (1 - opacity) * k})`;
      });
    };

    const draw = () => {
      ctx.clearRect(0, 0, w, h);
      const s = (t / 1000) * speed * 0.15;
      const R = Math.max(w, h) * 0.13 + 30;
      const lights = Array.from({ length: glows }, (_, i) => {
        const x = w * (0.5 + 0.45 * Math.sin(s * (0.9 + i * 0.37) + i * 2.1));
        const y = h * (0.5 + 0.45 * Math.cos(s * (0.7 + i * 0.23) + i * 1.3));
        // A faint brand halo under each glow
        const g = ctx.createRadialGradient(x, y, 0, x, y, R * 1.5);
        g.addColorStop(0, `rgba(${tint},.1)`);
        g.addColorStop(1, `rgba(${tint},0)`);
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, w, h);
        return [x, y];
      });
      // Batch dots into one path per brightness level: a few fills per frame.
      const paths = styles.map(() => new Path2D());
      const inv = 1 / (2 * R * R);
      const d = Math.max(gap, 4);
      for (let x = (w % d) / 2 + d / 2; x < w; x += d) {
        for (let y = (h % d) / 2 + d / 2; y < h; y += d) {
          let v = 0;
          for (const [lx, ly] of lights) v += Math.exp(-((x - lx) ** 2 + (y - ly) ** 2) * inv);
          const i = Math.round(Math.min(v, 1) * LEVELS);
          const r = radius * (1 + (0.6 * i) / LEVELS);
          paths[i].moveTo(x + r, y);
          paths[i].arc(x, y, r, 0, 7);
        }
      }
      paths.forEach((p, i) => {
        ctx.fillStyle = styles[i];
        ctx.fill(p);
      });
    };

    const frame = (now: number) => {
      t += Math.min(now - last, 50);
      last = now;
      draw();
      raf = requestAnimationFrame(frame);
    };
    // Loop only on screen, in a visible tab, without reduced motion and while
    // nobody is hovering or focused inside; otherwise hold a still frame.
    const sync = () => {
      cancelAnimationFrame(raf);
      if (mq.matches || !seen || document.hidden || focus || (hover && pauseOnHover)) draw();
      else {
        last = performance.now();
        raf = requestAnimationFrame(frame);
      }
    };
    const resize = () => {
      const dpr = Math.min(devicePixelRatio || 1, 2);
      w = el.clientWidth;
      h = el.clientHeight;
      el.width = w * dpr;
      el.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      sync();
    };
    const on = (e: Event) => {
      if (e.type == "pointerenter") hover = true;
      else if (e.type == "pointerleave") hover = false;
      else focus = host.contains((e as FocusEvent).relatedTarget as Node) || e.type == "focusin";
      sync();
    };
    const events = ["pointerenter", "pointerleave", "focusin", "focusout"];

    colors();
    const ro = new ResizeObserver(resize);
    const io = new IntersectionObserver(([e]) => {
      seen = e.isIntersecting;
      sync();
    });
    const mo = new MutationObserver(() => {
      colors();
      sync();
    });
    ro.observe(el);
    io.observe(el);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    events.forEach((n) => host.addEventListener(n, on));
    document.addEventListener("visibilitychange", sync);
    mq.addEventListener("change", sync);
    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      events.forEach((n) => host.removeEventListener(n, on));
      document.removeEventListener("visibilitychange", sync);
      mq.removeEventListener("change", sync);
    };
  }, [gap, radius, opacity, speed, glows, pauseOnHover]);

  return (
    <div
      aria-hidden
      data-slot="dotted-glow-background"
      className={cn("pointer-events-none absolute inset-0 overflow-hidden", className)}
      {...props}
    >
      <canvas ref={ref} className="absolute inset-0 size-full" />
    </div>
  );
}

import { cn } from "@/lib/utils";

interface FlickeringGridProps {
  /** Square size in px */
  squareSize?: number;
  /** Gap between squares in px */
  gap?: number;
  /** Number of columns and rows to render */
  columns?: number;
  rows?: number;
  className?: string;
}

/**
 * Grid of squares that fade in and out on staggered timers. Rendered as a
 * plain DOM grid with CSS animation delays — no canvas, no dependency.
 */
export function FlickeringGrid({
  squareSize = 4,
  gap = 6,
  columns = 40,
  rows = 20,
  className,
}: FlickeringGridProps) {
  const cells = columns * rows;

  return (
    <div
      aria-hidden
      data-slot="flickering-grid"
      style={{
        gridTemplateColumns: `repeat(${columns}, ${squareSize}px)`,
        gap,
      }}
      className={cn(
        "pointer-events-none absolute inset-0 grid h-full w-full justify-center overflow-hidden",
        className
      )}
    >
      {Array.from({ length: cells }).map((_, i) => (
        <span
          key={i}
          // Static under reduced motion: rest halfway between the two flicker levels.
          className="rounded-[1px] bg-current motion-safe:animate-flicker motion-reduce:opacity-[calc((var(--flicker-max,0.45)_+_var(--flicker-min,0.08))/2)]"
          style={{
            width: squareSize,
            height: squareSize,
            // Deterministic pseudo-random delay: stable between server and client.
            animationDelay: `${((i * 37) % 100) / 25}s`,
            animationDuration: `${2 + ((i * 13) % 5) * 0.4}s`,
          }}
        />
      ))}
    </div>
  );
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

export interface Floating3DParticlesProps extends Omit<
  React.CanvasHTMLAttributes<HTMLCanvasElement>,
  "width" | "height"
> {
  /**
   * Number of particles rendered on desktop viewports.
   * On mobile screens (< 768px), particle count automatically scales down
   * to 20 % to preserve smooth frame rates.
   * @default 400
   */
  quantity?: number
  /**
   * Particle color — 3 or 6 digit hex string.
   * @default "#8B5CF6"
   */
  color?: string
  /**
   * Mean particle radius in px. Each particle is randomly assigned a size
   * within ±40 % of this value.
   * @default 5
   */
  size?: number
  /**
   * Mean particle opacity (0–1). Each particle randomly varies within
   * ±0.2 of this value, clamped to [0, 1].
   * @default 0.3
   */
  opacity?: number
  /**
   * Vertical floating speed in px per frame. Positive values drift upward,
   * negative values downward.
   * @default 0.8
   */
  drift?: number
  /**
   * 3-D depth intensity on a 0–1 scale. `0` produces a flat 2D plane; `1`
   * creates strong perspective with pronounced near/far scaling.
   * @default 0.5
   */
  depth?: number
}

// ---------------------------------------------------------------------------
// Particle State (Polar coordinates + 3D perspective projection)
// ---------------------------------------------------------------------------

interface Particle {
  angle: number
  radius: number
  y: number
  size: number
  angularSpeed: number
  opacity: number
  screenX: number
  screenY: number
  projectedScale: number
}

// ---------------------------------------------------------------------------
// Constants & Helpers
// ---------------------------------------------------------------------------

const MOBILE_BREAKPOINT = 768
const SPREAD_FACTOR = 1.2
const MAX_DPR = 2

function hexToRgba(hex: string, alpha: number) {
  const clean = hex.replace("#", "").trim()
  const full =
    clean.length === 3
      ? clean
          .split("")
          .map((c) => c + c)
          .join("")
      : clean

  if (!/^[0-9a-f]{6}$/i.test(full)) return `rgba(139,92,246,${alpha})`

  const n = Number.parseInt(full, 16)
  return `rgba(${(n >> 16) & 0xff},${(n >> 8) & 0xff},${n & 0xff},${alpha})`
}

function deriveProjection(depth: number) {
  const t = Math.max(0, Math.min(1, depth))
  const fov = 800 - t * 600 // [800, 200]
  const perspectiveDistance = 100 + t * 700 // [100, 800]
  // depthRange stays below fov + pd - 1 to ensure positive denominator
  const depthRange = t * Math.min(400, fov + perspectiveDistance - 1)
  return { fov, perspectiveDistance, depthRange }
}

function spawnParticle(
  width: number,
  height: number,
  size: number,
  opacity: number
): Particle {
  const sizeVariance = size * 0.4
  const opacityVariance = 0.2
  return {
    angle: Math.random() * Math.PI * 2,
    radius: Math.random() * Math.max(width, height) * SPREAD_FACTOR,
    y: (Math.random() - 0.5) * height * 2,
    size: Math.max(0.5, size - sizeVariance + Math.random() * sizeVariance * 2),
    angularSpeed: 0.0015 + Math.random() * 0.001,
    opacity: Math.min(
      1,
      Math.max(
        0,
        opacity - opacityVariance + Math.random() * opacityVariance * 2
      )
    ),
    screenX: 0,
    screenY: 0,
    projectedScale: 1,
  }
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function Floating3DParticles({
  quantity = 400,
  color = "#8B5CF6",
  size = 5,
  opacity = 0.3,
  drift = 0.8,
  depth = 0.5,
  className,
  style,
  ...canvasProps
}: Floating3DParticlesProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const ioRef = React.useRef<IntersectionObserver | null>(null)
  const stateRef = React.useRef({
    mounted: false,
    paused: false,
    reducedMotion: false,
    rafId: null as number | null,
  })

  // Read fresh on every frame, so recolouring (e.g. a theme switch) does not
  // tear down the effect and respawn the whole field.
  const colorRef = React.useRef(color)
  React.useEffect(() => {
    colorRef.current = color
  }, [color])

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext("2d", { alpha: true })
    if (!ctx) return

    const s = stateRef.current
    s.mounted = true
    s.paused = false

    let width = 0
    let height = 0
    let particles: Particle[] = []
    let staticDirty = true

    const { fov, perspectiveDistance, depthRange } = deriveProjection(depth)

    // Reduced-motion media query (built-in a11y best practice)
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
    const syncReducedMotion = () => {
      s.reducedMotion = mq.matches
    }
    syncReducedMotion()

    // Draw single particle
    const draw = (p: Particle) => {
      const r = Math.max(0, p.size * p.projectedScale)
      if (r <= 0) return

      ctx.beginPath()
      ctx.fillStyle = hexToRgba(colorRef.current, p.opacity)
      ctx.arc(p.screenX, p.screenY, r, 0, Math.PI * 2)
      ctx.fill()
    }

    // Static frame for reduced motion
    const staticFrame = () => {
      ctx.clearRect(0, 0, width, height)
      const cx = width / 2
      const cy = height / 2

      for (const p of particles) {
        const denom = Math.max(1, fov + perspectiveDistance)
        const scale = fov / denom
        p.screenX = cx + Math.cos(p.angle) * p.radius * scale
        p.screenY = cy + p.y * scale
        p.projectedScale = scale
        draw(p)
      }
    }

    // Animation loop: continuous 3D field rotation and buoyant drift
    const tick = () => {
      if (!s.mounted) return

      if (s.paused) {
        s.rafId = requestAnimationFrame(tick)
        return
      }

      // Reduced motion: paint one static frame, then idle until something
      // invalidates it (resize, or the motion preference being turned off).
      if (s.reducedMotion) {
        if (staticDirty) {
          staticDirty = false
          staticFrame()
        }
        s.rafId = requestAnimationFrame(tick)
        return
      }

      staticDirty = true

      ctx.clearRect(0, 0, width, height)

      const cx = width / 2
      const cy = height / 2

      for (const p of particles) {
        // Continuous organic rotation around the 3D central axis
        p.angle += p.angularSpeed
        p.y -= drift

        // Respawn on the opposite edge, whichever one the particle left
        // through, so a negative drift falls instead of draining the field
        if (p.y < -height) {
          p.y = height
          p.radius = Math.random() * Math.max(width, height) * SPREAD_FACTOR
        } else if (p.y > height) {
          p.y = -height
          p.radius = Math.random() * Math.max(width, height) * SPREAD_FACTOR
        }

        // 3D Perspective Projection
        const denom = Math.max(
          1,
          fov + perspectiveDistance + Math.sin(p.angle) * depthRange
        )
        const scale = fov / denom

        p.screenX = cx + Math.cos(p.angle) * p.radius * scale
        p.screenY = cy + p.y * scale
        p.projectedScale = scale
      }

      // Painter's algorithm: draw farthest particles first
      particles.sort((a, b) => a.projectedScale - b.projectedScale)
      for (const p of particles) draw(p)

      s.rafId = requestAnimationFrame(tick)
    }

    // Resize handling with automatic mobile count scaling
    const resize = () => {
      const rect = canvas.getBoundingClientRect()
      width = Math.max(1, Math.round(rect.width))
      height = Math.max(1, Math.round(rect.height))

      const dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, MAX_DPR))
      canvas.width = Math.round(width * dpr)
      canvas.height = Math.round(height * dpr)
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)

      const isMobile = window.innerWidth < MOBILE_BREAKPOINT
      const count = isMobile ? Math.round(quantity * 0.2) : quantity

      particles = Array.from({ length: Math.max(0, count) }, () =>
        spawnParticle(width, height, size, opacity)
      )

      // Canvas was cleared by the width/height reassignment above.
      staticDirty = true
    }

    const onVisibilityChange = () => {
      s.paused = document.hidden
    }

    // ResizeObserver
    const ro =
      typeof ResizeObserver !== "undefined" ? new ResizeObserver(resize) : null
    if (ro) {
      ro.observe(canvas)
    } else {
      window.addEventListener("resize", resize)
    }

    // IntersectionObserver (built-in performance pause off-screen)
    if (typeof IntersectionObserver !== "undefined") {
      ioRef.current = new IntersectionObserver(
        ([entry]) => {
          if (entry) s.paused = document.hidden || !entry.isIntersecting
        },
        { threshold: 0 }
      )
      ioRef.current.observe(canvas)
    }

    document.addEventListener("visibilitychange", onVisibilityChange)
    mq.addEventListener("change", syncReducedMotion)

    resize()
    s.rafId = requestAnimationFrame(tick)

    return () => {
      s.mounted = false
      if (s.rafId !== null) {
        cancelAnimationFrame(s.rafId)
        s.rafId = null
      }
      ro?.disconnect()
      if (!ro) window.removeEventListener("resize", resize)
      ioRef.current?.disconnect()
      ioRef.current = null
      document.removeEventListener("visibilitychange", onVisibilityChange)
      mq.removeEventListener("change", syncReducedMotion)
    }
  }, [quantity, size, opacity, drift, depth])

  return (
    <canvas
      ref={canvasRef}
      aria-hidden="true"
      className={cn(
        "pointer-events-none absolute inset-0 h-full w-full",
        className
      )}
      style={style}
      {...canvasProps}
    />
  )
}

