"use client";

import { useCallback, useEffect, useRef } from "react";

import { cn } from "@/lib/utils";

type Draw = (t: number, dt: number, still: boolean) => void;
type Build = (ctx: CanvasRenderingContext2D, w: number, h: number, el: HTMLCanvasElement) => Draw;

// Resolves any CSS colour (or a "--custom-property") to RGBA bytes through a
// 1×1 canvas, so oklch() theme tokens can be blended on every browser.
function probe(el: Element, color: string) {
  const c = document.createElement("canvas").getContext("2d", { willReadFrequently: true })!;
  c.fillStyle = color.startsWith("--") ? getComputedStyle(el).getPropertyValue(color) : color;
  c.fillRect(0, 0, 1, 1);
  return c.getImageData(0, 0, 1, 1).data;
}

// Runs `build` on resize and theme change; loops only while on screen, the tab
// is visible and motion is allowed — otherwise paints a single still frame.
function useCanvasLoop(ref: React.RefObject<HTMLCanvasElement | null>, build: Build) {
  useEffect(() => {
    const el = ref.current;
    const ctx = el?.getContext("2d");
    if (!el || !ctx) return;
    const mq = matchMedia("(prefers-reduced-motion: reduce)");
    let draw: Draw | undefined;
    let raf = 0;
    let t = 0;
    let last = 0;
    let seen = false;
    const frame = (now: number) => {
      const dt = Math.max(0, Math.min(now - last, 50));
      last = now;
      t += dt;
      draw?.(t, dt, false);
      raf = requestAnimationFrame(frame);
    };
    const sync = () => {
      cancelAnimationFrame(raf);
      if (!draw) return;
      if (mq.matches) draw(t, 0, true);
      else if (seen && !document.hidden) {
        last = performance.now();
        raf = requestAnimationFrame(frame);
      }
    };
    const setup = () => {
      const dpr = Math.min(devicePixelRatio || 1, 2);
      const w = el.clientWidth;
      const h = el.clientHeight;
      el.width = w * dpr;
      el.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw = w && h ? build(ctx, w, h, el) : undefined;
      sync();
    };
    const ro = new ResizeObserver(setup);
    const io = new IntersectionObserver(([e]) => {
      seen = e.isIntersecting;
      sync();
    });
    const mo = new MutationObserver(setup);
    ro.observe(el);
    io.observe(el);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    mo.observe(document.head, { childList: true, subtree: true, characterData: true });
    document.addEventListener("visibilitychange", sync);
    mq.addEventListener("change", sync);
    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", sync);
      mq.removeEventListener("change", sync);
    };
  }, [ref, build]);
}

interface Particle {
  a: number;
  r: number;
  life: number;
  ttl: number;
  c: number;
  w: number;
}

interface VortexProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Maximum particle count; capped by container area so small screens draw fewer */
  particles?: number;
  /** Rotation speed multiplier */
  speed?: number;
  /** How far the swirl reaches towards the edges, 0–1 */
  range?: number;
}

/**
 * A field of brand-tinted particles spiralling into the centre, leaving
 * fading trails. Absolutely positioned — place inside a `relative
 * overflow-hidden` section. Trails glow additively when the inherited text
 * colour is light (i.e. on a dark section).
 */
export function Vortex({
  particles = 520,
  speed = 1,
  range = 1,
  className,
  ...props
}: VortexProps) {
  const ref = useRef<HTMLCanvasElement>(null);

  const build = useCallback<Build>(
    (ctx, w, h, el) => {
      // Light text means a dark section: let overlapping trails add up to a glow.
      const fg = probe(el, getComputedStyle(el).color);
      const glow = fg[0] * 0.3 + fg[1] * 0.59 + fg[2] * 0.11 > 128;
      // Twelve steps along the brand ramp.
      const [a, b, c] = ["--brand-from", "--brand-via", "--brand-to"].map((v) => probe(el, v));
      const ramp = Array.from({ length: 12 }, (_, i) => {
        const k = i / 11;
        const [x, y] = k < 0.5 ? [a, b] : [b, c];
        const m = k < 0.5 ? k * 2 : k * 2 - 1;
        return `rgb(${[0, 1, 2].map((j) => x[j] + (y[j] - x[j]) * m).join(", ")})`;
      });
      const cx = w / 2;
      const cy = h / 2;
      const rx = (w / 2) * range;
      const ry = (h / 2) * range * 1.15;
      const spawn = (p: Partial<Particle> = {}): Particle =>
        Object.assign(p, {
          a: Math.random() * Math.PI * 2,
          r: 0.2 + Math.sqrt(Math.random()) * 0.8,
          life: 0,
          ttl: 180 + Math.random() * 320,
          c: (Math.random() * 12) | 0,
          w: 0.6 + Math.random() * 1.4,
        });
      const list = Array.from({ length: Math.min(particles, (w * h) / 450) | 0 }, () => {
        const p = spawn();
        p.life = Math.random() * p.ttl;
        return p;
      });

      const step = (f: number) => {
        // Trails: erase a little of every pixel each frame. Erasing (rather
        // than painting the background colour over) leaves no 8-bit ghosting
        // and lets trails fade into whatever sits behind, gradients included.
        ctx.globalCompositeOperation = "destination-out";
        ctx.globalAlpha = 0.18;
        ctx.fillRect(0, 0, w, h);
        ctx.globalCompositeOperation = glow ? "lighter" : "source-over";
        for (const p of list) {
          const x = cx + Math.cos(p.a) * p.r * rx;
          const y = cy + Math.sin(p.a) * p.r * ry;
          // Faster near the centre, with a slow inward drift.
          p.a += (f * speed * 0.008) / (0.15 + p.r);
          p.r -= f * speed * 0.0005 * (0.4 + p.r);
          p.life += f;
          ctx.globalAlpha = Math.sin((Math.PI * p.life) / p.ttl) * 0.9;
          ctx.strokeStyle = ramp[p.c];
          ctx.lineWidth = p.w;
          ctx.beginPath();
          ctx.moveTo(x, y);
          ctx.lineTo(cx + Math.cos(p.a) * p.r * rx, cy + Math.sin(p.a) * p.r * ry);
          ctx.stroke();
          if (p.life > p.ttl || p.r < 0.03) spawn(p);
        }
      };

      ctx.lineCap = "round";
      return (_t, dt, still) => {
        if (!still) return step(dt / 16.7);
        // Reduced motion: run 90 steps at once and show the frozen swirl.
        ctx.clearRect(0, 0, w, h);
        for (let i = 0; i < 90; i++) step(1);
      };
    },
    [particles, speed, range]
  );
  useCanvasLoop(ref, build);

  return (
    <div
      aria-hidden
      data-slot="vortex"
      className={cn("pointer-events-none absolute inset-0 overflow-hidden", className)}
      {...props}
    >
      <canvas ref={ref} className="absolute inset-0 size-full" />
    </div>
  );
}

"use client"

import React, {
  useCallback,
  useMemo,
  useState,
  type HTMLAttributes,
} from "react"
import { motion } from "motion/react"

import { cn } from "@/lib/utils"

interface WarpBackgroundProps extends HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode
  perspective?: number
  beamsPerSide?: number
  beamSize?: number
  beamDelayMax?: number
  beamDelayMin?: number
  beamDuration?: number
  gridColor?: string
}

const Beam = ({
  width,
  x,
  delay,
  duration,
}: {
  width: string | number
  x: string | number
  delay: number
  duration: number
}) => {
  const [hue] = useState(() => Math.floor(Math.random() * 360))
  const [ar] = useState(() => Math.floor(Math.random() * 10) + 1)

  return (
    <motion.div
      style={
        {
          "--x": `${x}`,
          "--width": `${width}`,
          "--aspect-ratio": `${ar}`,
          "--background": `linear-gradient(hsl(${hue} 80% 60%), transparent)`,
        } as React.CSSProperties
      }
      className={`absolute top-0 left-(--x) aspect-[1/var(--aspect-ratio)] w-(--width) [background:var(--background)]`}
      initial={{ y: "100cqmax", x: "-50%" }}
      animate={{ y: "-100%", x: "-50%" }}
      transition={{
        duration,
        delay,
        repeat: Infinity,
        ease: "linear",
      }}
    />
  )
}

export const WarpBackground: React.FC<WarpBackgroundProps> = ({
  children,
  perspective = 100,
  className,
  beamsPerSide = 3,
  beamSize = 5,
  beamDelayMax = 3,
  beamDelayMin = 0,
  beamDuration = 3,
  gridColor = "var(--border)",
  ...props
}) => {
  const generateBeams = useCallback(() => {
    const beams = []
    const cellsPerSide = Math.floor(100 / beamSize)
    const step = cellsPerSide / beamsPerSide

    for (let i = 0; i < beamsPerSide; i++) {
      const x = Math.floor(i * step)
      const delay = Math.random() * (beamDelayMax - beamDelayMin) + beamDelayMin
      beams.push({ x, delay })
    }
    return beams
  }, [beamsPerSide, beamSize, beamDelayMax, beamDelayMin])

  const topBeams = useMemo(() => generateBeams(), [generateBeams])
  const rightBeams = useMemo(() => generateBeams(), [generateBeams])
  const bottomBeams = useMemo(() => generateBeams(), [generateBeams])
  const leftBeams = useMemo(() => generateBeams(), [generateBeams])

  return (
    <div className={cn("relative rounded border p-20", className)} {...props}>
      <div
        style={
          {
            "--perspective": `${perspective}px`,
            "--grid-color": gridColor,
            "--beam-size": `${beamSize}%`,
          } as React.CSSProperties
        }
        className={
          "@container-[size] pointer-events-none absolute top-0 left-0 size-full overflow-hidden [clipPath:inset(0)] perspective-(--perspective) transform-3d"
        }
      >
        {/* top side */}
        <div className="@container absolute z-20 h-[100cqmax] w-[100cqi] origin-[50%_0%] transform-[rotateX(-90deg)] bg-size-[var(--beam-size)_var(--beam-size)] [background:linear-gradient(var(--grid-color)_0_1px,transparent_1px_var(--beam-size))_50%_-0.5px_/var(--beam-size)_var(--beam-size),linear-gradient(90deg,var(--grid-color)_0_1px,transparent_1px_var(--beam-size))_50%_50%_/var(--beam-size)_var(--beam-size)] transform-3d">
          {topBeams.map((beam, index) => (
            <Beam
              key={`top-${index}`}
              width={`${beamSize}%`}
              x={`${beam.x * beamSize}%`}
              delay={beam.delay}
              duration={beamDuration}
            />
          ))}
        </div>
        {/* bottom side */}
        <div className="@container absolute top-full h-[100cqmax] w-[100cqi] origin-[50%_0%] transform-[rotateX(-90deg)] bg-size-[var(--beam-size)_var(--beam-size)] [background:linear-gradient(var(--grid-color)_0_1px,transparent_1px_var(--beam-size))_50%_-0.5px_/var(--beam-size)_var(--beam-size),linear-gradient(90deg,var(--grid-color)_0_1px,transparent_1px_var(--beam-size))_50%_50%_/var(--beam-size)_var(--beam-size)] transform-3d">
          {bottomBeams.map((beam, index) => (
            <Beam
              key={`bottom-${index}`}
              width={`${beamSize}%`}
              x={`${beam.x * beamSize}%`}
              delay={beam.delay}
              duration={beamDuration}
            />
          ))}
        </div>
        {/* left side */}
        <div className="@container absolute top-0 left-0 h-[100cqmax] w-[100cqh] origin-[0%_0%] transform-[rotate(90deg)_rotateX(-90deg)] bg-size-[var(--beam-size)_var(--beam-size)] [background:linear-gradient(var(--grid-color)_0_1px,transparent_1px_var(--beam-size))_50%_-0.5px_/var(--beam-size)_var(--beam-size),linear-gradient(90deg,var(--grid-color)_0_1px,transparent_1px_var(--beam-size))_50%_50%_/var(--beam-size)_var(--beam-size)] transform-3d">
          {leftBeams.map((beam, index) => (
            <Beam
              key={`left-${index}`}
              width={`${beamSize}%`}
              x={`${beam.x * beamSize}%`}
              delay={beam.delay}
              duration={beamDuration}
            />
          ))}
        </div>
        {/* right side */}
        <div className="@container absolute top-0 right-0 h-[100cqmax] w-[100cqh] origin-[100%_0%] transform-[rotate(-90deg)_rotateX(-90deg)] bg-size-[var(--beam-size)_var(--beam-size)] [background:linear-gradient(var(--grid-color)_0_1px,transparent_1px_var(--beam-size))_50%_-0.5px_/var(--beam-size)_var(--beam-size),linear-gradient(90deg,var(--grid-color)_0_1px,transparent_1px_var(--beam-size))_50%_50%_/var(--beam-size)_var(--beam-size)] transform-3d">
          {rightBeams.map((beam, index) => (
            <Beam
              key={`right-${index}`}
              width={`${beamSize}%`}
              x={`${beam.x * beamSize}%`}
              delay={beam.delay}
              duration={beamDuration}
            />
          ))}
        </div>
      </div>
      <div className="relative">{children}</div>
    </div>
  )
}

"use client";

import { useCallback, useEffect, useRef } from "react";

import { cn } from "@/lib/utils";

type Draw = (t: number, dt: number, still: boolean) => void;
type Build = (ctx: CanvasRenderingContext2D, w: number, h: number, el: HTMLCanvasElement) => Draw;

// Resolves any CSS colour (or a "--custom-property") to "r, g, b" through a 1×1
// canvas, so oklch() theme tokens work in gradients on every browser.
function rgb(el: Element, color: string) {
  const c = document.createElement("canvas").getContext("2d", { willReadFrequently: true })!;
  c.fillStyle = color.startsWith("--") ? getComputedStyle(el).getPropertyValue(color) : color;
  c.fillRect(0, 0, 1, 1);
  const [r, g, b] = c.getImageData(0, 0, 1, 1).data;
  return `${r}, ${g}, ${b}`;
}

// Runs `build` on resize and theme change; loops only while on screen, the tab
// is visible and motion is allowed — otherwise paints a single still frame.
function useCanvasLoop(ref: React.RefObject<HTMLCanvasElement | null>, build: Build) {
  useEffect(() => {
    const el = ref.current;
    const ctx = el?.getContext("2d");
    if (!el || !ctx) return;
    const mq = matchMedia("(prefers-reduced-motion: reduce)");
    let draw: Draw | undefined;
    let raf = 0;
    let t = 0;
    let last = 0;
    let seen = false;
    const frame = (now: number) => {
      const dt = Math.max(0, Math.min(now - last, 50));
      last = now;
      t += dt;
      draw?.(t, dt, false);
      raf = requestAnimationFrame(frame);
    };
    const sync = () => {
      cancelAnimationFrame(raf);
      if (!draw) return;
      if (mq.matches) draw(t, 0, true);
      else if (seen && !document.hidden) {
        last = performance.now();
        raf = requestAnimationFrame(frame);
      }
    };
    const setup = () => {
      const dpr = Math.min(devicePixelRatio || 1, 2);
      const w = el.clientWidth;
      const h = el.clientHeight;
      el.width = w * dpr;
      el.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw = w && h ? build(ctx, w, h, el) : undefined;
      sync();
    };
    const ro = new ResizeObserver(setup);
    const io = new IntersectionObserver(([e]) => {
      seen = e.isIntersecting;
      sync();
    });
    const mo = new MutationObserver(setup);
    ro.observe(el);
    io.observe(el);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style"] });
    mo.observe(document.head, { childList: true, subtree: true, characterData: true });
    document.addEventListener("visibilitychange", sync);
    mq.addEventListener("change", sync);
    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      mo.disconnect();
      document.removeEventListener("visibilitychange", sync);
      mq.removeEventListener("change", sync);
    };
  }, [ref, build]);
}

// Stable pseudo-random 0–1 per wave, so every wave keeps its shape across resizes.
const seed = (i: number, k: number) => {
  const s = Math.sin(i * 12.9898 + k * 78.233) * 43758.5453;
  return s - Math.floor(s);
};

interface WavyBackgroundProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Number of layered waves */
  waves?: number;
  /** How quickly the waves drift */
  speed?: "slow" | "fast";
  /** Blur radius in px applied to the wave layer */
  blur?: number;
  /** Any CSS colours or custom property names (e.g. "--brand-from"); cycled across the waves */
  colors?: string[];
  /** Opacity of each wave, 0–1 */
  opacity?: number;
}

/**
 * Layered, blurred ribbons of colour flowing sideways on a canvas. Absolutely
 * positioned — place inside a `relative overflow-hidden` section and layer
 * content above it. Defaults to the brand ramp and follows theme changes;
 * ribbons blend additively when the inherited text colour is light.
 */
export function WavyBackground({
  waves = 5,
  speed = "slow",
  blur = 16,
  colors = ["--brand-from", "--brand-via", "--brand-to"],
  opacity = 0.5,
  className,
  ...props
}: WavyBackgroundProps) {
  const ref = useRef<HTMLCanvasElement>(null);
  const palette = colors.join("|");

  const build = useCallback<Build>(
    (ctx, w, h, el) => {
      const fills = palette.split("|").map((c) => rgb(el, c));
      const rate = speed === "fast" ? 0.0009 : 0.0003;
      const step = 12;
      // Light text means a dark section: let overlapping ribbons add up to a glow.
      const [r, g, b] = rgb(el, getComputedStyle(el).color).split(", ").map(Number);
      ctx.globalCompositeOperation = r * 0.3 + g * 0.59 + b * 0.11 > 128 ? "lighter" : "source-over";
      const tau = Math.PI * 2;
      return (t) => {
        ctx.clearRect(0, 0, w, h);
        ctx.globalAlpha = opacity;
        for (let i = 0; i < waves; i++) {
          const f1 = tau * (0.5 + seed(i, 1));
          const f2 = tau * (1.4 + seed(i, 2) * 1.6);
          const p = seed(i, 3) * tau;
          const s = rate * (0.6 + seed(i, 4) * 0.8) * (i % 2 ? -1 : 1);
          const amp = h * (0.1 + seed(i, 5) * 0.08);
          const base = h * (0.52 + (i - (waves - 1) / 2) * 0.07);
          const top: number[] = [];
          ctx.beginPath();
          for (let x = 0; x <= w + step; x += step) {
            const u = x / w;
            const y =
              base +
              amp * (0.7 * Math.sin(u * f1 + t * s + p) + 0.3 * Math.sin(u * f2 - t * s * 1.7 + p * 2));
            top.push(y);
            ctx.lineTo(x, y);
          }
          // Walk back along the lower edge; the ribbon swells and thins as it goes.
          for (let j = top.length - 1; j >= 0; j--) {
            const u = (j * step) / w;
            ctx.lineTo(j * step, top[j] + amp * (0.45 + 0.35 * Math.sin(u * f1 * 1.3 - t * s + p)));
          }
          const g = ctx.createLinearGradient(0, 0, w, 0);
          g.addColorStop(0, `rgb(${fills[i % fills.length]})`);
          g.addColorStop(1, `rgb(${fills[(i + 1) % fills.length]})`);
          ctx.fillStyle = g;
          ctx.fill();
        }
      };
    },
    [waves, speed, opacity, palette]
  );
  useCanvasLoop(ref, build);

  return (
    <div
      aria-hidden
      data-slot="wavy-background"
      className={cn("pointer-events-none absolute inset-0 overflow-hidden", className)}
      {...props}
    >
      {/* Oversized so the blur never shows a soft edge at the sides */}
      <canvas
        ref={ref}
        className="absolute"
        style={{
          inset: -blur * 2,
          width: `calc(100% + ${blur * 4}px)`,
          height: `calc(100% + ${blur * 4}px)`,
          filter: `blur(${blur}px)`,
        }}
      />
    </div>
  );
}

"use client";

import { createContext, useContext, useRef } from "react";
import {
  motion,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
  useSpring,
  type MotionValue,
} from "motion/react";

import { cn } from "@/lib/utils";

// 0 = flat, 1 = fully lifted. Every Card3DItem scales its own depth by it.
const LiftContext = createContext<MotionValue<number> | null>(null);

const SPRING = { stiffness: 180, damping: 20, mass: 0.6 };
const FOCUS_LIFT = 0.4;

interface Card3DProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Maximum rotation toward the pointer, in degrees */
  maxTilt?: number;
  /** CSS perspective distance in px (smaller = stronger 3D) */
  perspective?: number;
  /** Classes for the rotating surface (avoid overflow-hidden: it flattens the layers) */
  cardClassName?: string;
  /** Card content; wrap layers that should lift in Card3DItem */
  children: React.ReactNode;
}

/**
 * Perspective card that rotates toward the pointer. Wrap parts of its
 * content in `Card3DItem` with a `depth` (px) and they lift off the surface
 * at different heights while the pointer is over the card. Keyboard focus
 * inside the card lifts the items to a gentle resting depth without tilting.
 */
export function Card3D({
  maxTilt = 10,
  perspective = 1000,
  cardClassName,
  className,
  style,
  children,
  ...props
}: Card3DProps) {
  const reducedMotion = useReducedMotion();
  const rotateX = useMotionValue(0);
  const rotateY = useMotionValue(0);
  const liftTarget = useMotionValue(0);
  const lift = useSpring(liftTarget, SPRING);
  const springX = useSpring(rotateX, SPRING);
  const springY = useSpring(rotateY, SPRING);
  const state = useRef({ hover: false, focus: false });

  const settle = () => {
    const { hover, focus } = state.current;
    liftTarget.set(reducedMotion ? 0 : hover ? 1 : focus ? FOCUS_LIFT : 0);
  };

  return (
    <div
      {...props}
      data-slot="3d-card"
      className={cn("group/card3d", className)}
      style={{ perspective, ...style }}
      onPointerMove={(e) => {
        props.onPointerMove?.(e);
        if (reducedMotion) return;
        const rect = e.currentTarget.getBoundingClientRect();
        const x = (e.clientX - rect.left) / rect.width - 0.5;
        const y = (e.clientY - rect.top) / rect.height - 0.5;
        rotateX.set(-y * maxTilt * 2);
        rotateY.set(x * maxTilt * 2);
        state.current.hover = true;
        settle();
      }}
      onPointerLeave={(e) => {
        props.onPointerLeave?.(e);
        rotateX.set(0);
        rotateY.set(0);
        state.current.hover = false;
        settle();
      }}
      onFocus={(e) => {
        props.onFocus?.(e);
        state.current.focus = e.target.matches(":focus-visible");
        settle();
      }}
      onBlur={(e) => {
        props.onBlur?.(e);
        if (e.currentTarget.contains(e.relatedTarget)) return;
        state.current.focus = false;
        settle();
      }}
    >
      <motion.div
        style={{ rotateX: springX, rotateY: springY }}
        className={cn(
          "relative transform-3d [&_*]:transform-3d",
          cardClassName
        )}
      >
        <LiftContext.Provider value={lift}>{children}</LiftContext.Provider>
      </motion.div>
    </div>
  );
}

interface Card3DItemProps extends React.HTMLAttributes<HTMLDivElement> {
  /** How far the item lifts toward the viewer, in px (translateZ) */
  depth?: number;
  /** Extra rotation around the X axis at full lift, in degrees */
  rotateX?: number;
  /** Extra rotation around the Y axis at full lift, in degrees */
  rotateY?: number;
  /** Extra rotation around the Z axis at full lift, in degrees */
  rotateZ?: number;
}

/**
 * A layer inside `Card3D` that floats `depth` px above the card surface.
 */
export function Card3DItem({
  depth = 40,
  rotateX = 0,
  rotateY = 0,
  rotateZ = 0,
  className,
  children,
  ...props
}: Card3DItemProps) {
  const ref = useRef<HTMLDivElement>(null);
  const fallback = useMotionValue(0);
  const lift = useContext(LiftContext) ?? fallback;

  useMotionValueEvent(lift, "change", (v) => {
    if (!ref.current) return;
    ref.current.style.transform =
      v < 0.001
        ? ""
        : `translateZ(${v * depth}px) rotateX(${v * rotateX}deg) rotateY(${v * rotateY}deg) rotateZ(${v * rotateZ}deg)`;
  });

  return (
    <div
      {...props}
      ref={ref}
      data-slot="3d-card-item"
      className={className}
    >
      {children}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

interface Pin3DProps
  extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "title"> {
  /** Label shown in the chip at the top of the pin */
  title: string;
  /** Makes the whole card a link; without it the root is a plain div */
  href?: string;
  /** Classes for the card surface that holds the children */
  cardClassName?: string;
  /** Card content, drawn on the tilting surface */
  children: React.ReactNode;
}

const RINGS = [0, 1, 2];

/**
 * Card that tilts back in perspective on hover or keyboard focus while a
 * glowing pin rises from its centre, topped by a `title` chip, with rings
 * rippling out across the card at the pin's base. Pass `href` to make the
 * whole card a link. Leave room above the card for the pin (about 1.5rem).
 */
export function Pin3D({
  title,
  href,
  cardClassName,
  className,
  children,
  ...props
}: Pin3DProps) {
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const rings = useRef<(HTMLSpanElement | null)[]>([]);
  const active = hovered || focused;

  useEffect(() => {
    if (!active || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const animations = rings.current.map((ring, i) =>
      ring?.animate(
        [
          { transform: "scale(0.1)", opacity: 0 },
          { opacity: 1, offset: 0.25 },
          { transform: "scale(1)", opacity: 0 },
        ],
        { duration: 3600, delay: i * 1200, iterations: Infinity, easing: "ease-out", fill: "backwards" }
      )
    );
    return () => animations.forEach((a) => a?.cancel());
  }, [active]);

  const Root = (href ? "a" : "div") as "a";

  return (
    <Root
      {...props}
      href={href}
      data-slot="3d-pin"
      data-active={active || undefined}
      className={cn(
        "group/pin relative block outline-none perspective-[1000px]",
        className
      )}
      onPointerEnter={(e) => {
        setHovered(true);
        props.onPointerEnter?.(e);
      }}
      onPointerLeave={(e) => {
        setHovered(false);
        props.onPointerLeave?.(e);
      }}
      onFocus={(e) => {
        if (e.target.matches(":focus-visible")) setFocused(true);
        props.onFocus?.(e);
      }}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget)) setFocused(false);
        props.onBlur?.(e);
      }}
    >
      <div className="relative transform-3d transition-transform duration-700 ease-[cubic-bezier(0.2,0.8,0.2,1)] motion-reduce:transition-none motion-safe:group-data-active/pin:scale-84 motion-safe:group-data-active/pin:rotate-x-40">
        <div
          className={cn(
            "relative overflow-hidden rounded-2xl border bg-card p-3 text-card-foreground shadow-sm transition-shadow duration-700 group-focus-visible/pin:ring-2 group-focus-visible/pin:ring-ring group-focus-visible/pin:ring-offset-2 group-focus-visible/pin:ring-offset-background group-data-active/pin:shadow-2xl group-data-active/pin:shadow-brand/15",
            cardClassName
          )}
        >
          {children}
        </div>
        <span
          aria-hidden
          className="pointer-events-none absolute top-1/2 left-1/2 opacity-0 transition-opacity duration-500 group-data-active/pin:opacity-100 motion-reduce:transition-none"
        >
          {RINGS.map((i) => (
            <span
              key={i}
              ref={(el) => {
                rings.current[i] = el;
              }}
              style={{ transform: `scale(${0.3 + i * 0.2})`, opacity: 0.7 - i * 0.2 }}
              className="absolute -top-24 -left-24 size-48 rounded-full border border-brand/60 bg-brand/5 shadow-[0_0_28px_-6px_var(--brand)]"
            />
          ))}
        </span>
      </div>

      <span className="pointer-events-none absolute inset-x-0 -top-5 bottom-1/2 z-10 flex flex-col items-center opacity-0 transition duration-500 group-data-active/pin:opacity-100 motion-safe:translate-y-4 motion-safe:group-data-active/pin:translate-y-0 motion-safe:group-data-active/pin:delay-150 motion-reduce:transition-none">
        <span className="relative flex items-center gap-1.5 rounded-full border bg-background/85 px-3 py-1 text-xs font-medium whitespace-nowrap text-foreground shadow-lg shadow-brand/10 backdrop-blur">
          <span aria-hidden className="size-1.5 rounded-full bg-brand" />
          {title}
          <span
            aria-hidden
            className="absolute inset-x-3 -bottom-px h-px bg-linear-to-r from-transparent via-brand to-transparent"
          />
        </span>
        <span
          aria-hidden
          className="relative w-px flex-1 origin-bottom bg-linear-to-b from-transparent via-brand/60 to-brand transition-transform duration-700 motion-safe:scale-y-0 motion-safe:group-data-active/pin:scale-y-100 motion-reduce:transition-none"
        >
          <span className="absolute inset-y-0 -left-px w-[3px] [background:inherit] blur-[2px]" />
        </span>
        <span
          aria-hidden
          className="-mb-1 size-2 rounded-full bg-brand shadow-[0_0_12px_2px_var(--brand)] ring-4 ring-brand/20"
        />
      </span>
    </Root>
  );
}

