import { useEffect, useRef, useState } from "react";
import { motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

interface CardStackProps {
  /** Each entry becomes one card; the first is on top */
  items: { id: string | number; content: React.ReactNode }[];
  /** Seconds between automatic shuffles; 0 disables */
  interval?: number;
  /** Vertical offset per card, in px */
  offset?: number;
  className?: string;
}

/**
 * Deck of cards that shuffles the top card to the back. Good for rotating
 * quotes or tips in a fixed-height slot.
 */
export function CardStack({
  items,
  interval = 4,
  offset = 12,
  className,
}: CardStackProps) {
  // Rotation is a single counter, so card order stays derived from props —
  // no copy of `items` in state to keep in sync.
  const [shift, setShift] = useState(0);
  const reducedMotion = useReducedMotion();
  const count = items.length;
  // Held while hovered or focused so the top card can be read (WCAG 2.2.2).
  const paused = useRef(false);

  useEffect(() => {
    // Reduced motion: no auto-shuffle, the first card stays on top.
    if (!interval || count < 2 || reducedMotion !== false) return;
    const id = window.setInterval(() => {
      if (paused.current || document.hidden) return;
      setShift((value) => value + 1);
    }, interval * 1000);
    return () => window.clearInterval(id);
  }, [interval, count, reducedMotion]);

  const pause = () => {
    paused.current = true;
  };
  const resume = () => {
    paused.current = false;
  };

  return (
    <div
      data-slot="card-stack"
      onMouseEnter={pause}
      onMouseLeave={resume}
      onFocus={pause}
      onBlur={resume}
      className={cn("relative h-56 w-full max-w-sm", className)}
    >
      {items.map((card, i) => {
        // Where this card currently sits in the deck, 0 = on top.
        const depth = (i - (shift % count) + count) % count;
        return (
          <motion.div
            key={card.id}
            initial={false}
            animate={{
              top: depth * -offset,
              scale: 1 - depth * 0.05,
              zIndex: count - depth,
            }}
            transition={
              reducedMotion
                ? { duration: 0 }
                : { type: "spring", stiffness: 260, damping: 26 }
            }
            className="absolute inset-x-0 flex h-56 flex-col justify-between rounded-2xl border bg-card p-5 shadow-xl shadow-foreground/5"
          >
            {card.content}
          </motion.div>
        );
      })}
    </div>
  );
}

"use client";

import { useRef, useState } from "react";

import { cn } from "@/lib/utils";

type Edge = "top" | "right" | "bottom" | "left";

const ENTER: Record<Edge, string> = {
  top: "-translate-y-full",
  right: "translate-x-full",
  bottom: "translate-y-full",
  left: "-translate-x-full",
};

interface DirectionAwareHoverProps {
  children: React.ReactNode;
  /** Slides in from whichever edge the cursor crossed */
  overlay: React.ReactNode;
  className?: string;
}

/**
 * Overlay that enters from the edge the cursor actually crossed and leaves the
 * same way. Zero dependencies — the maths is one arctangent.
 */
export function DirectionAwareHover({
  children,
  overlay,
  className,
}: DirectionAwareHoverProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [edge, setEdge] = useState<Edge>("bottom");
  const [hovered, setHovered] = useState(false);

  const edgeFrom = (event: React.MouseEvent<HTMLDivElement>): Edge => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return "bottom";
    // Angle from the centre, corrected for aspect ratio, mapped to quadrants.
    const x = (event.clientX - rect.left - rect.width / 2) * (rect.height / rect.width);
    const y = event.clientY - rect.top - rect.height / 2;
    const quadrant = Math.round(Math.atan2(y, x) / (Math.PI / 2) + 4) % 4;
    return (["right", "bottom", "left", "top"] as const)[quadrant];
  };

  return (
    <div
      ref={ref}
      // Focusable so keyboard users can reveal the overlay too.
      tabIndex={0}
      data-slot="direction-aware-hover"
      onPointerEnter={(event) => {
        if (event.pointerType !== "mouse") return;
        setEdge(edgeFrom(event));
        setHovered(true);
      }}
      onPointerLeave={(event) => {
        if (event.pointerType !== "mouse") return;
        setEdge(edgeFrom(event));
        setHovered(false);
      }}
      // Touch and pen have no hover: a tap toggles the overlay instead.
      onPointerUp={(event) => {
        if (event.pointerType !== "mouse") setHovered((value) => !value);
      }}
      onFocus={(event) => {
        // Keyboard focus only; a tap is already handled by onPointerUp.
        if ((event.target as HTMLElement).matches(":focus-visible")) {
          setHovered(true);
        }
      }}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) {
          setHovered(false);
        }
      }}
      className={cn(
        "relative overflow-hidden rounded-2xl border bg-card focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        className
      )}
    >
      {children}
      <div
        className={cn(
          "absolute inset-0 flex items-center justify-center bg-gradient-to-br from-brand-from to-brand-to text-brand-foreground transition-transform duration-300 ease-out motion-reduce:transition-none",
          hovered ? "translate-x-0 translate-y-0" : ENTER[edge]
        )}
      >
        {overlay}
      </div>
    </div>
  );
}

"use client";

import {
  Children,
  createContext,
  useContext,
  useId,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
  useVelocity,
} from "motion/react";

import { cn } from "@/lib/utils";

const noopSubscribe = () => () => {};

interface Board {
  ref: React.RefObject<HTMLDivElement | null>;
  hint: string;
  count: number;
  top: () => number;
}

const BoardContext = createContext<Board | null>(null);
const IndexContext = createContext(0);

// Integer hash → [0, 1). Same result on server and client (no Math.random).
const seeded = (i: number, salt: number) =>
  ((Math.imul(i + 1, 2654435761) ^ Math.imul(salt, 40503)) >>> 0) % 1000 / 1000;

interface DraggableCardContainerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** `DraggableCard` elements */
  children: React.ReactNode;
}

/**
 * The board that scatters its `DraggableCard`s and keeps them inside its
 * bounds. Give it a height (default h-96).
 */
export function DraggableCardContainer({
  children,
  className,
  ...props
}: DraggableCardContainerProps) {
  const ref = useRef<HTMLDivElement>(null);
  const hint = useId();
  const z = useRef(Children.count(children));
  const board: Board = { ref, hint, count: Children.count(children), top: () => ++z.current };

  return (
    <div
      {...props}
      ref={ref}
      data-slot="draggable-card-container"
      className={cn("relative h-96 w-full", className)}
    >
      <p id={hint} hidden>
        Arrow keys move the card; Enter or Space brings it to the front.
      </p>
      <BoardContext value={board}>
        {Children.map(children, (child, i) => (
          <IndexContext value={i}>{child}</IndexContext>
        ))}
      </BoardContext>
    </div>
  );
}

interface DraggableCardProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onDrag" | "onDragStart" | "onDragEnd" | "onAnimationStart"> {
  /** Accessible name for the card, e.g. its caption */
  label?: string;
  /** Resting tilt in degrees (defaults to a seeded ±7° per card) */
  rotate?: number;
}

/**
 * A photo-style card for `DraggableCardContainer`: drag or fling it (it
 * tilts with the motion and springs back inside the board), nudge it with
 * arrow keys, and press Enter or Space to bring it to the front.
 */
export function DraggableCard({
  label,
  rotate,
  className,
  style,
  children,
  ...props
}: DraggableCardProps) {
  const ref = useRef<HTMLDivElement>(null);
  const board = useContext(BoardContext);
  const index = useContext(IndexContext);
  const count = board?.count ?? 1;
  const hydrated = useSyncExternalStore(noopSubscribe, () => true, () => false);
  const reduced = !!useReducedMotion() && hydrated;
  const [z, setZ] = useState(index + 1);
  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const base = rotate ?? Math.round((seeded(index, 1) - 0.5) * 14);
  // Lean toward the direction of travel, springing upright when released
  const lean = useSpring(useTransform(useVelocity(x), [-2000, 2000], [-12, 12], { clamp: true }), {
    stiffness: 300,
    damping: 30,
  });
  const tilt = useTransform(lean, (v) => base + v);
  // Resting spot as a % of the board, in a loose zigzag. The card is also
  // translated by -p% of its own size, so it always starts fully inside.
  const place = (p: number) => Math.round(Math.min(Math.max(p, 0), 100) * 100) / 100;
  const px = place(((index + 0.5) / count) * 100 + (seeded(index, 2) - 0.5) * 8);
  const py = place(50 + (index % 2 ? 30 : -30) + (seeded(index, 3) - 0.5) * 16);

  const front = () => board && setZ(board.top());

  // Keyboard nudge, clamped to the board. Offsets come from layout (offset*)
  // plus the motion values, so rapid key repeats never read a stale frame.
  const nudge = (dx: number, dy: number) => {
    const card = ref.current;
    const box = board?.ref.current;
    if (!card || !box) return;
    const move = (mv: typeof x, d: number, start: number, size: number, room: number, p: number) => {
      const from = start - (size * p) / 100 + mv.get();
      mv.set(mv.get() + Math.min(Math.max(d, Math.min(0, -from)), Math.max(0, room - size - from)));
    };
    move(x, dx, card.offsetLeft, card.offsetWidth, box.clientWidth, px);
    move(y, dy, card.offsetTop, card.offsetHeight, box.clientHeight, py);
  };

  return (
    <motion.div
      {...props}
      ref={ref}
      tabIndex={0}
      role="group"
      aria-roledescription="draggable card"
      aria-label={label}
      aria-describedby={board?.hint}
      data-slot="draggable-card"
      drag
      dragConstraints={board?.ref}
      dragElastic={reduced ? 0 : 0.25}
      dragMomentum={!reduced}
      dragTransition={{ bounceStiffness: 260, bounceDamping: 22 }}
      whileDrag={reduced ? undefined : { scale: 1.04 }}
      onPointerDown={(e) => {
        front();
        props.onPointerDown?.(e);
      }}
      onKeyDown={(e) => {
        props.onKeyDown?.(e);
        const step = e.shiftKey ? 48 : 12;
        const moves: Record<string, [number, number]> = {
          ArrowLeft: [-step, 0],
          ArrowRight: [step, 0],
          ArrowUp: [0, -step],
          ArrowDown: [0, step],
        };
        if (moves[e.key]) nudge(...moves[e.key]);
        else if (e.key === "Enter" || e.key === " ") front();
        else return;
        e.preventDefault();
      }}
      style={{
        x,
        y,
        rotate: reduced ? base : tilt,
        zIndex: z,
        left: `${px}%`,
        top: `${py}%`,
        translate: `-${px}% -${py}%`,
        ...style,
      }}
      className={cn(
        "absolute w-48 cursor-grab touch-none rounded-lg border bg-card p-2.5 pb-4 text-card-foreground shadow-xl select-none focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background active:cursor-grabbing sm:w-56",
        className
      )}
    >
      {children}
    </motion.div>
  );
}

