/**
 * Card that reveals a field of random, brand-tinted characters through a
 * soft circular mask that follows the pointer; the characters reshuffle as
 * it moves. Keyboard focus inside the card reveals the mask at the centre.
 * `label` renders a centred badge; `children` render below it.
 */
export function EvervaultCard({
  label,
  radius = 140,
  interval = 60,
  className,
  style,
  children,
  ...props
}: EvervaultCardProps) {
  const ref = useRef<HTMLDivElement>(null);
  const field = useRef<HTMLParagraphElement>(null);
  const last = useRef(0);

  const scramble = (force = false) => {
    const el = ref.current;
    const p = field.current;
    if (!el || !p) return;
    const now = performance.now();
    const still = matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (!force && (still || now - last.current < interval)) return;
    if (still && p.textContent) return;
    last.current = now;
    const count = Math.ceil((el.offsetWidth * el.offsetHeight) / 60);
    let text = "";
    for (let i = 0; i < count; i++) text += CHARS[(Math.random() * CHARS.length) | 0];
    p.textContent = text;
  };

  const place = (x: string, y: string) => {
    ref.current?.style.setProperty("--ev-x", x);
    ref.current?.style.setProperty("--ev-y", y);
  };

  return (
    <div
      {...props}
      ref={ref}
      data-slot="evervault-card"
      style={{ "--ev-r": `${radius}px`, ...style } as React.CSSProperties}
      className={cn(
        "group/ev relative isolate flex flex-col overflow-hidden rounded-3xl border bg-card text-card-foreground [--ev-x:50%] [--ev-y:50%]",
        className
      )}
      onPointerEnter={(e) => {
        props.onPointerEnter?.(e);
        scramble(true);
      }}
      onPointerMove={(e) => {
        props.onPointerMove?.(e);
        if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
        const rect = e.currentTarget.getBoundingClientRect();
        place(`${e.clientX - rect.left}px`, `${e.clientY - rect.top}px`);
        scramble();
      }}
      onFocus={(e) => {
        props.onFocus?.(e);
        if (!e.target.matches(":focus-visible")) return;
        place("50%", "50%");
        scramble(true);
      }}
    >
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 -z-10 opacity-0 transition-opacity duration-500 [mask-image:radial-gradient(circle_var(--ev-r)_at_var(--ev-x)_var(--ev-y),#000_15%,transparent)] group-hover/ev:opacity-100 group-has-[:focus-visible]/ev:opacity-100"
      >
        <div className="absolute inset-0 bg-linear-to-br from-brand-from/25 via-brand-via/15 to-brand-to/25" />
        <p
          ref={field}
          className="absolute inset-0 overflow-hidden bg-linear-to-br from-brand-from via-brand-via to-brand-to bg-clip-text font-mono text-[10px] leading-3 font-semibold break-all text-transparent"
        />
      </div>
      {label != null && (
        <div className="flex flex-1 items-center justify-center p-8">
          <div className="relative">
            <span
              aria-hidden
              className="absolute -inset-3 rounded-full bg-linear-to-br from-brand-from via-brand-via to-brand-to opacity-0 blur-xl transition-opacity duration-500 group-hover/ev:opacity-50 group-has-[:focus-visible]/ev:opacity-50"
            />
            <div className="relative flex size-32 items-center justify-center rounded-full border bg-card/85 text-center text-2xl font-semibold tracking-tight shadow-xl backdrop-blur-sm">
              {label}
            </div>
          </div>
        </div>
      )}
      {children}
    </div>
  );
}

"use client";

import { useEffect, useId, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

interface ExpandableCardProps {
  title: string;
  subtitle?: string;
  /** Shown only once the card is expanded */
  children: React.ReactNode;
  /** Rendered in both the collapsed card and the expanded panel */
  media?: React.ReactNode;
  className?: string;
}

/**
 * Card that expands into a centred panel, with the title and media animating
 * between the two positions via a shared layout id.
 */
export function ExpandableCard({
  title,
  subtitle,
  children,
  media,
  className,
}: ExpandableCardProps) {
  const [open, setOpen] = useState(false);
  const id = useId();
  const reducedMotion = useReducedMotion();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);

  // Modal focus handling: move focus in, keep Tab inside, Escape closes, and
  // hand focus back to the trigger however the dialog was closed.
  useEffect(() => {
    if (!open) return;
    const trigger = triggerRef.current;
    const dialog = dialogRef.current;
    dialog?.focus({ preventScroll: true });

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false);
        return;
      }
      if (event.key !== "Tab" || !dialog) return;
      const focusable = Array.from(
        dialog.querySelectorAll<HTMLElement>(
          'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
        )
      );
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      const active = document.activeElement;
      if (!first || !dialog.contains(active)) {
        event.preventDefault();
        (first ?? dialog).focus();
      } else if (event.shiftKey && (active === first || active === dialog)) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      trigger?.focus({ preventScroll: true });
    };
  }, [open]);

  const spring = reducedMotion
    ? { duration: 0 }
    : { type: "spring" as const, stiffness: 320, damping: 32 };

  return (
    <>
      <motion.button
        ref={triggerRef}
        type="button"
        layoutId={`card-${id}`}
        onClick={() => setOpen(true)}
        transition={spring}
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={open ? `dialog-${id}` : undefined}
        data-slot="expandable-card"
        className={cn(
          "flex w-full max-w-sm cursor-pointer flex-col gap-3 rounded-2xl border bg-card p-4 text-left transition-colors hover:bg-muted/50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
          className
        )}
      >
        {media && (
          <motion.div
            layoutId={`media-${id}`}
            transition={spring}
            className="overflow-hidden rounded-xl"
          >
            {media}
          </motion.div>
        )}
        {/* Buttons only allow phrasing content, so the title is a span here
            and becomes the dialog's heading once expanded. */}
        <motion.span
          layoutId={`title-${id}`}
          transition={spring}
          className="font-medium"
        >
          {title}
        </motion.span>
        {subtitle && (
          <span className="-mt-2 text-sm text-muted-foreground">{subtitle}</span>
        )}
      </motion.button>

      <AnimatePresence>
        {open && (
          <div className="fixed inset-0 z-50 grid place-items-center p-4">
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setOpen(false)}
              className="absolute inset-0 bg-background/70 backdrop-blur-sm"
            />
            <motion.div
              ref={dialogRef}
              id={`dialog-${id}`}
              layoutId={`card-${id}`}
              transition={spring}
              role="dialog"
              aria-modal="true"
              aria-labelledby={`title-${id}`}
              tabIndex={-1}
              className="relative flex w-full max-w-lg flex-col gap-4 rounded-2xl border bg-card p-6 shadow-2xl outline-none"
            >
              {media && (
                <motion.div
                  layoutId={`media-${id}`}
                  transition={spring}
                  className="overflow-hidden rounded-xl"
                >
                  {media}
                </motion.div>
              )}
              <motion.h3
                id={`title-${id}`}
                layoutId={`title-${id}`}
                transition={spring}
                className="text-lg font-semibold"
              >
                {title}
              </motion.h3>
              <div className="text-sm text-muted-foreground">{children}</div>
              <button
                type="button"
                onClick={() => setOpen(false)}
                className="self-start rounded-lg border px-3 py-1.5 text-sm transition-colors hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                Close
              </button>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </>
  );
}

import { cn } from "@/lib/utils";

interface FocusCard {
  /** Shown over the card while it has the focus; always read by screen readers */
  title: string;
  /** Image URL */
  src: string;
  /** Describes the photo; leave empty when the title says enough */
  alt?: string;
  /** Makes the card a link */
  href?: string;
}

interface FocusCardsProps extends React.HTMLAttributes<HTMLUListElement> {
  /** The cards, in order */
  cards: FocusCard[];
  /** Extra classes for every card, e.g. a different aspect ratio */
  cardClassName?: string;
}

// Blur and shrink every card while a sibling is hovered or keyboard-focused;
// the card under the pointer or focus opts back out.
const card = cn(
  "group/focus-card relative block aspect-[4/3] overflow-hidden rounded-2xl bg-muted shadow-sm transition-[filter,scale] duration-300 ease-out motion-reduce:transition-none",
  "group-has-[[data-focus-card]:hover]/focus-cards:blur-[3px] group-has-[[data-focus-card]:focus-visible]/focus-cards:blur-[3px]",
  "motion-safe:group-has-[[data-focus-card]:hover]/focus-cards:scale-[0.97] motion-safe:group-has-[[data-focus-card]:focus-visible]/focus-cards:scale-[0.97]",
  // `!` because the :has() selectors above out-rank a plain :hover/:focus-visible.
  "hover:scale-100! hover:blur-none! focus-visible:scale-100! focus-visible:blur-none!",
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
);

// Titles show on hover and keyboard focus, and always on touch screens.
const reveal =
  "opacity-0 transition duration-300 group-hover/focus-card:opacity-100 group-focus-visible/focus-card:opacity-100 pointer-coarse:opacity-100 motion-reduce:transition-none";

/**
 * Image grid where the card you point at (or tab to) stays sharp while the
 * rest soften and step back, and its title rises over a gradient. Pure CSS —
 * no client JavaScript. Cards with an `href` are links; the others are
 * focusable figures so keyboard users can reveal their titles too.
 */
export function FocusCards({
  cards,
  cardClassName,
  className,
  ...props
}: FocusCardsProps) {
  return (
    <ul
      data-slot="focus-cards"
      className={cn("group/focus-cards grid gap-4 sm:grid-cols-2 md:grid-cols-3", className)}
      {...props}
    >
      {cards.map(({ title, src, alt = "", href }) => {
        const Caption = href ? "span" : "figcaption";
        const body = (
          <>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={src}
              alt={alt}
              loading="lazy"
              decoding="async"
              className="absolute inset-0 size-full object-cover transition-transform duration-500 ease-out motion-safe:group-hover/focus-card:scale-105 motion-safe:group-focus-visible/focus-card:scale-105"
            />
            <div
              aria-hidden
              className={cn("absolute inset-0 bg-linear-to-t from-black/75 via-black/20 to-transparent", reveal)}
            />
            <Caption
              className={cn(
                "absolute inset-x-0 bottom-0 p-5 text-lg font-semibold tracking-tight text-white pointer-fine:motion-safe:translate-y-2 motion-safe:group-hover/focus-card:translate-y-0 motion-safe:group-focus-visible/focus-card:translate-y-0",
                reveal
              )}
            >
              {title}
            </Caption>
          </>
        );
        return (
          <li key={src + title}>
            {href ? (
              <a href={href} data-focus-card="" className={cn(card, cardClassName)}>
                {body}
              </a>
            ) : (
              <figure tabIndex={0} data-focus-card="" className={cn(card, cardClassName)}>
                {body}
              </figure>
            )}
          </li>
        );
      })}
    </ul>
  );
}

"use client";

import { useRef, useState } from "react";

import { cn } from "@/lib/utils";

interface GlareCardProps {
  children: React.ReactNode;
  className?: string;
}

/**
 * Card with a sheet of light that tracks the cursor across its surface, like
 * a foil trading card. CSS custom properties do the work — no dependency.
 */
export function GlareCard({ children, className }: GlareCardProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState(false);

  const handleMouseMove = (event: React.MouseEvent<HTMLDivElement>) => {
    const element = ref.current;
    if (!element) return;
    const rect = element.getBoundingClientRect();
    element.style.setProperty(
      "--glare-x",
      `${((event.clientX - rect.left) / rect.width) * 100}%`
    );
    element.style.setProperty(
      "--glare-y",
      `${((event.clientY - rect.top) / rect.height) * 100}%`
    );
  };

  return (
    <div
      ref={ref}
      data-slot="glare-card"
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setActive(true)}
      onMouseLeave={() => setActive(false)}
      className={cn(
        "group/glare relative overflow-hidden rounded-2xl border bg-card p-6 [--glare-x:50%] [--glare-y:50%]",
        className
      )}
    >
      <span
        aria-hidden
        style={{ opacity: active ? 1 : 0 }}
        className="pointer-events-none absolute inset-0 bg-[radial-gradient(circle_at_var(--glare-x)_var(--glare-y),color-mix(in_oklch,var(--brand)_28%,transparent),transparent_55%)] transition-opacity duration-300 motion-reduce:transition-none"
      />
      <div className="relative">{children}</div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

import { cn } from "@/lib/utils";

interface GlowingEffectProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Distance in px outside the card at which the glow starts to fade in */
  proximity?: number;
  /** Length of the lit arc, in degrees of the border */
  spread?: number;
  /** Thickness of the glowing border in px */
  borderWidth?: number;
  /** Add a soft blurred halo behind the lit border */
  halo?: boolean;
}

const OFF = -1e5;

/**
 * A glowing arc on a card's border that turns to face the pointer and fades
 * in as the pointer comes within `proximity` px. Place it as a direct child
 * of a `relative` card; it inherits the card's border radius. Keyboard focus
 * inside the card lights the whole border.
 */
export function GlowingEffect({
  proximity = 64,
  spread = 80,
  borderWidth = 2,
  halo = true,
  className,
  style,
  ...props
}: GlowingEffectProps) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const reduce = matchMedia("(prefers-reduced-motion: reduce)");
    let x = OFF;
    let y = OFF;
    let angle = 0;
    let lit = false;
    let raf = 0;

    const frame = () => {
      raf = 0;
      if (reduce.matches) {
        el.style.removeProperty("--glow-o");
        return;
      }
      const r = el.getBoundingClientRect();
      const dx = Math.max(r.left - x, 0, x - r.right);
      const dy = Math.max(r.top - y, 0, y - r.bottom);
      const near = Math.max(0, 1 - Math.hypot(dx, dy) / Math.max(proximity, 1));
      el.style.setProperty("--glow-o", near.toFixed(3));
      if (!near) {
        lit = false;
        return;
      }
      const target =
        (Math.atan2(x - r.left - r.width / 2, r.top + r.height / 2 - y) * 180) / Math.PI;
      // Ease along the shortest way round; snap when the glow first appears.
      const d = ((((target - angle) % 360) + 540) % 360) - 180;
      angle += !lit || Math.abs(d) < 0.5 ? d : d * 0.2;
      lit = true;
      el.style.setProperty("--glow-a", `${angle.toFixed(2)}deg`);
      if (angle !== target && Math.abs(d) >= 0.5) raf = requestAnimationFrame(frame);
    };
    const queue = () => {
      if (!raf) raf = requestAnimationFrame(frame);
    };
    const onMove = (e: PointerEvent) => {
      x = e.clientX;
      y = e.clientY;
      queue();
    };
    const onOut = (e: PointerEvent) => {
      if (e.relatedTarget) return;
      x = y = OFF;
      queue();
    };

    const listen = (on: boolean) => {
      if (on) {
        document.addEventListener("pointermove", onMove, { passive: true });
        document.addEventListener("pointerout", onOut);
        window.addEventListener("scroll", queue, { passive: true });
        queue();
      } else {
        document.removeEventListener("pointermove", onMove);
        document.removeEventListener("pointerout", onOut);
        window.removeEventListener("scroll", queue);
      }
    };
    // Listen only while the card is on screen.
    const io = new IntersectionObserver((entries) =>
      listen(entries[entries.length - 1].isIntersecting)
    );
    io.observe(el);
    return () => {
      io.disconnect();
      listen(false);
      cancelAnimationFrame(raf);
    };
  }, [proximity]);

  const arc = (ring: string) => (
    <div className="absolute inset-0 rounded-[inherit] [mask-image:conic-gradient(from_calc(var(--glow-a)-var(--glow-s)/2),var(--glow-m),#000_calc(var(--glow-s)*0.35),#000_calc(var(--glow-s)*0.65),var(--glow-m)_var(--glow-s),var(--glow-m))]">
      <div className="absolute inset-0 rounded-[inherit] bg-[conic-gradient(from_var(--glow-a),var(--brand-from),var(--brand-via),var(--brand-to),var(--brand-via),var(--brand-from))] [mask:linear-gradient(#000_0_0)_content-box_exclude,linear-gradient(#000_0_0)]" style={{ padding: ring }} />
    </div>
  );

  return (
    <div
      {...props}
      ref={ref}
      aria-hidden
      data-slot="glowing-effect"
      style={
        { "--glow-s": `${spread}deg`, "--glow-w": `${borderWidth}px`, ...style } as React.CSSProperties
      }
      className={cn(
        "pointer-events-none absolute -inset-px rounded-[inherit] opacity-(--glow-o,0) transition-opacity duration-300 [--glow-a:0deg] [--glow-m:transparent]",
        "motion-reduce:[:hover>&]:opacity-70 motion-reduce:[:hover>&]:[--glow-m:#000]",
        "[:is(:focus-visible,:has(:focus-visible))>&]:opacity-100 [:is(:focus-visible,:has(:focus-visible))>&]:[--glow-m:#000]",
        className
      )}
    >
      {halo && (
        <div className="absolute -inset-1 rounded-[inherit] opacity-70 blur-[6px]">
          {arc("calc(var(--glow-w) + 6px)")}
        </div>
      )}
      {arc("var(--glow-w)")}
    </div>
  );
}

"use client"

import React, { useCallback, useEffect, useRef } from "react"
import {
  motion,
  useMotionTemplate,
  useMotionValue,
  useSpring,
} from "motion/react"

import { cn } from "@/lib/utils"

interface MagicCardBaseProps {
  children?: React.ReactNode
  className?: string
  gradientSize?: number
  gradientFrom?: string
  gradientTo?: string
}

interface MagicCardGradientProps extends MagicCardBaseProps {
  mode?: "gradient"

  gradientColor?: string
  gradientOpacity?: number

  glowFrom?: never
  glowTo?: never
  glowAngle?: never
  glowSize?: never
  glowBlur?: never
  glowOpacity?: never
}

interface MagicCardOrbProps extends MagicCardBaseProps {
  mode: "orb"

  glowFrom?: string
  glowTo?: string
  glowAngle?: number
  glowSize?: number
  glowBlur?: number
  glowOpacity?: number

  gradientColor?: never
  gradientOpacity?: never
}

type MagicCardProps = MagicCardGradientProps | MagicCardOrbProps
type ResetReason = "enter" | "leave" | "global" | "init"

function isOrbMode(props: MagicCardProps): props is MagicCardOrbProps {
  return props.mode === "orb"
}

export function MagicCard(props: MagicCardProps) {
  const {
    children,
    className,
    gradientSize = 200,
    gradientColor = "#262626",
    gradientOpacity = 0.8,
    gradientFrom = "#9E7AFF",
    gradientTo = "#FE8BBB",
    mode = "gradient",
  } = props

  const glowFrom = isOrbMode(props) ? (props.glowFrom ?? "#ee4f27") : "#ee4f27"
  const glowTo = isOrbMode(props) ? (props.glowTo ?? "#6b21ef") : "#6b21ef"
  const glowAngle = isOrbMode(props) ? (props.glowAngle ?? 90) : 90
  const glowSize = isOrbMode(props) ? (props.glowSize ?? 420) : 420
  const glowBlur = isOrbMode(props) ? (props.glowBlur ?? 60) : 60
  const glowOpacity = isOrbMode(props) ? (props.glowOpacity ?? 0.9) : 0.9

  const mouseX = useMotionValue(-gradientSize)
  const mouseY = useMotionValue(-gradientSize)

  const orbX = useSpring(mouseX, { stiffness: 250, damping: 30, mass: 0.6 })
  const orbY = useSpring(mouseY, { stiffness: 250, damping: 30, mass: 0.6 })
  const orbVisible = useSpring(0, { stiffness: 300, damping: 35 })

  const modeRef = useRef(mode)
  const glowOpacityRef = useRef(glowOpacity)
  const gradientSizeRef = useRef(gradientSize)

  useEffect(() => {
    modeRef.current = mode
  }, [mode])

  useEffect(() => {
    glowOpacityRef.current = glowOpacity
  }, [glowOpacity])

  useEffect(() => {
    gradientSizeRef.current = gradientSize
  }, [gradientSize])

  const reset = useCallback(
    (reason: ResetReason = "leave") => {
      const currentMode = modeRef.current

      if (currentMode === "orb") {
        if (reason === "enter") orbVisible.set(glowOpacityRef.current)
        else orbVisible.set(0)
        return
      }

      const off = -gradientSizeRef.current
      mouseX.set(off)
      mouseY.set(off)
    },
    [mouseX, mouseY, orbVisible]
  )

  const handlePointerMove = useCallback(
    (e: React.PointerEvent<HTMLDivElement>) => {
      const rect = e.currentTarget.getBoundingClientRect()
      mouseX.set(e.clientX - rect.left)
      mouseY.set(e.clientY - rect.top)
    },
    [mouseX, mouseY]
  )

  useEffect(() => {
    reset("init")
  }, [reset])

  useEffect(() => {
    const handleGlobalPointerOut = (e: PointerEvent) => {
      if (!e.relatedTarget) reset("global")
    }
    const handleBlur = () => reset("global")
    const handleVisibility = () => {
      if (document.visibilityState !== "visible") reset("global")
    }

    window.addEventListener("pointerout", handleGlobalPointerOut)
    window.addEventListener("blur", handleBlur)
    document.addEventListener("visibilitychange", handleVisibility)

    return () => {
      window.removeEventListener("pointerout", handleGlobalPointerOut)
      window.removeEventListener("blur", handleBlur)
      document.removeEventListener("visibilitychange", handleVisibility)
    }
  }, [reset])

  return (
    <motion.div
      className={cn(
        "group relative isolate overflow-hidden rounded-[inherit] border border-transparent",
        className
      )}
      onPointerMove={handlePointerMove}
      onPointerLeave={() => reset("leave")}
      onPointerEnter={() => reset("enter")}
      style={{
        background: useMotionTemplate`
          linear-gradient(var(--color-background) 0 0) padding-box,
          radial-gradient(${gradientSize}px circle at ${mouseX}px ${mouseY}px,
            ${gradientFrom},
            ${gradientTo},
            var(--color-border) 100%
          ) border-box
        `,
      }}
    >
      <div className="bg-background absolute inset-px z-20 rounded-[inherit]" />

      {mode === "gradient" && (
        <motion.div
          suppressHydrationWarning
          className="pointer-events-none absolute inset-px z-30 rounded-[inherit] opacity-0 transition-opacity duration-300 group-hover:opacity-100"
          style={{
            background: useMotionTemplate`
              radial-gradient(${gradientSize}px circle at ${mouseX}px ${mouseY}px,
                ${gradientColor},
                transparent 100%
              )
            `,
            opacity: gradientOpacity,
          }}
        />
      )}

      {mode === "orb" && (
        <motion.div
          suppressHydrationWarning
          aria-hidden="true"
          className="pointer-events-none absolute z-30 mix-blend-multiply dark:mix-blend-screen"
          style={{
            width: glowSize,
            height: glowSize,
            x: orbX,
            y: orbY,
            translateX: "-50%",
            translateY: "-50%",
