"use client";

import { useEffect, useRef } from "react";
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useScroll,
  useTransform,
  useVelocity,
} from "motion/react";

import { cn } from "@/lib/utils";

interface ScrollVelocityProps {
  children: React.ReactNode;
  /** Base speed in percent of content width per second */
  baseVelocity?: number;
  className?: string;
}

/**
 * A marquee whose speed and direction respond to how fast you are scrolling.
 * Holds a steady drift when the page is still, pauses while hovered or
 * focused, and stays still under `prefers-reduced-motion`.
 */
export function ScrollVelocity({
  children,
  baseVelocity = 4,
  className,
}: ScrollVelocityProps) {
  const baseX = useMotionValue(0);
  const direction = useRef(1);
  const reducedMotion = useReducedMotion();
  const hovered = useRef(false);
  const focused = useRef(false);

  const { scrollY } = useScroll();
  const scrollVelocity = useVelocity(scrollY);
  const velocityFactor = useTransform(scrollVelocity, [-1200, 1200], [-4, 4], {
    clamp: false,
  });

  const root = useRef<HTMLDivElement>(null);

  // Own rAF loop (not useAnimationFrame) so nothing ticks under reduced
  // motion or while the marquee is offscreen.
  useEffect(() => {
    const el = root.current;
    if (reducedMotion !== false || !el) return;
    let frame = 0;
    let last = 0;
    let visible = false;

    const tick = (now: number) => {
      const delta = last ? now - last : 0;
      last = now;
      if (!hovered.current && !focused.current) {
        let moveBy = direction.current * baseVelocity * (delta / 1000);
        const factor = velocityFactor.get();
        // Scrolling backwards flips the marquee's direction.
        if (factor < 0) direction.current = -1;
        else if (factor > 0) direction.current = 1;
        moveBy += direction.current * moveBy * Math.abs(factor);
        // One copy is 25% of the four-copy track, so wrap there.
        baseX.set(((baseX.get() + moveBy) % 25) - 25);
      }
      frame = visible ? requestAnimationFrame(tick) : 0;
    };

    const observer = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (visible && !frame) {
        last = 0;
        frame = requestAnimationFrame(tick);
      }
    });
    observer.observe(el);
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
    };
  }, [reducedMotion, baseVelocity, baseX, velocityFactor]);

  const x = useTransform(baseX, (value) => `${value}%`);

  return (
    <div
      ref={root}
      data-slot="scroll-velocity"
      onMouseEnter={() => (hovered.current = true)}
      onMouseLeave={() => (hovered.current = false)}
      onFocus={() => (focused.current = true)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
          focused.current = false;
        }
      }}
      className={cn("w-full overflow-hidden whitespace-nowrap", className)}
    >
      <motion.div style={{ x }} className="flex w-max gap-8">
        {Array.from({ length: 4 }).map((_, i) => (
          <span
            key={i}
            aria-hidden={i > 0 || undefined}
            inert={i > 0}
            className="shrink-0"
          >
            {children}
          </span>
        ))}
      </motion.div>
    </div>
  );
}

"use client";

import { useRef, useState } from "react";
import {
  motion,
  useMotionValueEvent,
  useReducedMotion,
  useScroll,
} from "motion/react";

import { cn } from "@/lib/utils";

export interface StickyScrollItem {
  title: string;
  description: string;
  /** Rendered in the pinned panel while this item is active */
  content?: React.ReactNode;
}

interface StickyScrollProps {
  items: StickyScrollItem[];
  /** Scrollable element to track instead of the window */
  container?: React.RefObject<HTMLElement | null>;
  className?: string;
}

/**
 * Long-form copy that scrolls past a pinned panel; the panel swaps as each
 * section takes over. The classic "how it works" section. Heights use `cqh`,
 * which resolves against the viewport unless an ancestor is a size container
 * (e.g. a fixed-height scroll box with `@container-size`).
 */
export function StickyScroll({ items, container, className }: StickyScrollProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [active, setActive] = useState(0);
  const reducedMotion = useReducedMotion();
  const duration = reducedMotion ? 0 : 0.3;
  const { scrollYProgress } = useScroll({
    container,
    target: ref,
    offset: ["start start", "end end"],
  });

  useMotionValueEvent(scrollYProgress, "change", (progress) => {
    if (!items.length) return;
    // Split the scrollable range into one band per item.
    const next = Math.min(
      items.length - 1,
      Math.floor(progress * items.length)
    );
    setActive(next);
  });

  if (!items.length) return null;

  return (
    <div
      ref={ref}
      data-slot="sticky-scroll"
      className={cn("relative flex gap-12", className)}
    >
      <div className="flex-1 py-[30cqh]">
        {items.map((item, i) => (
          <div key={item.title} className="flex min-h-[60cqh] flex-col justify-center">
            {/* Only the large title dims, and only to a level that keeps
                3:1 contrast; the description stays at full strength. */}
            <motion.h3
              animate={{ opacity: active === i ? 1 : 0.6 }}
              transition={{ duration }}
              className="text-2xl font-semibold"
            >
              {item.title}
            </motion.h3>
            <p className="mt-3 max-w-md text-muted-foreground">
              {item.description}
            </p>
          </div>
        ))}
      </div>

      <div className="sticky top-[20cqh] hidden h-[60cqh] flex-1 lg:block">
        <div className="relative size-full overflow-hidden rounded-2xl border bg-gradient-to-br from-brand-from/10 to-brand-to/10">
          {items.map((item, i) => (
            <motion.div
              key={item.title}
              initial={false}
              animate={{
                opacity: active === i ? 1 : 0,
                scale: active === i ? 1 : 0.97,
              }}
              transition={{ duration, ease: "easeOut" }}
              aria-hidden={active !== i}
              inert={active !== i}
              className="absolute inset-0 flex items-center justify-center p-8"
            >
              {item.content ?? (
                <span className="text-xl font-medium">{item.title}</span>
              )}
            </motion.div>
          ))}
        </div>
      </div>
    </div>
  );
}

