"use client";

import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { useInView, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

const noopSubscribe = () => () => {};

interface TerminalProps {
  /** Lines to type. Prefix with "$ " to render a prompt-colored command. */
  lines: string[];
  title?: string;
  /** ms per character */
  speed?: number;
  className?: string;
}

/**
 * A terminal window that types its lines when scrolled into view.
 */
export function Terminal({
  lines,
  title = "bash",
  speed = 18,
  className,
}: TerminalProps) {
  const ref = useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { once: true, margin: "0px 0px -15% 0px" });
  // useReducedMotion() already knows the preference on the first client
  // render, but the server can't — keep the animated markup until hydrated.
  const hydrated = useSyncExternalStore(noopSubscribe, () => true, () => false);
  const reducedMotion = useReducedMotion() === true && hydrated;
  const [progress, setProgress] = useState({ line: 0, char: 0 });

  const done =
    reducedMotion ||
    (progress.line >= lines.length - 1 &&
      progress.char >= (lines[lines.length - 1]?.length ?? 0));

  useEffect(() => {
    if (!inView || reducedMotion || done) return;
    const current = lines[progress.line] ?? "";
    const timeout = setTimeout(
      () =>
        setProgress((p) =>
          p.char < current.length
            ? { ...p, char: p.char + 1 }
            : { line: p.line + 1, char: 0 }
        ),
      progress.char === 0 ? 260 : speed
    );
    return () => clearTimeout(timeout);
  }, [inView, reducedMotion, done, progress, lines, speed]);

  const visibleLines = reducedMotion
    ? lines
    : lines
        .slice(0, progress.line + 1)
        .map((l, i) => (i === progress.line ? l.slice(0, progress.char) : l));

  return (
    <div
      ref={ref}
      data-slot="terminal"
      className={cn(
        "relative w-full overflow-hidden rounded-xl border bg-neutral-950 font-mono text-sm shadow-xl",
        className
      )}
    >
      <div className="flex items-center gap-3 border-b border-white/10 px-4 py-2.5">
        <div className="flex gap-1.5">
          <span className="size-3 rounded-full bg-red-500/80" />
          <span className="size-3 rounded-full bg-yellow-500/80" />
          <span className="size-3 rounded-full bg-green-500/80" />
        </div>
        <span className="text-xs text-neutral-500">{title}</span>
      </div>
      <div className="sr-only">
        {lines.map((line, i) => (
          <p key={i}>{line}</p>
        ))}
      </div>
      <div aria-hidden className="min-h-32 space-y-1.5 p-4 text-neutral-300">
        {visibleLines.map((line, i) => {
          const isCommand = lines[i]?.startsWith("$ ");
          const isLast = i === visibleLines.length - 1;
          return (
            <p key={i} className="leading-relaxed">
              {isCommand ? (
                <>
                  <span className="text-emerald-400">$ </span>
                  <span className="text-neutral-100">{line.slice(2)}</span>
                </>
              ) : (
                <span className="text-neutral-400">{line}</span>
              )}
              {isLast && !done && (
                <span className="text-neutral-100 motion-safe:animate-pulse">▍</span>
              )}
            </p>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  AnimatePresence,
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
} from "motion/react";

import { cn } from "@/lib/utils";

const SPRING = { stiffness: 520, damping: 38, mass: 0.5 };

interface FollowingPointerProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "color"> {
  /** Content of the name tag next to the arrow; leave empty for an arrow only */
  label?: React.ReactNode;
  /** Any CSS colour for the arrow and tag */
  color?: string;
  children: React.ReactNode;
}

/**
 * Wrap a region to swap the system cursor for a coloured arrow and name tag,
 * like a collaborator's cursor, that trail the pointer on a spring. It only
 * takes over for a mouse on a fine-pointer device; touch keeps the defaults,
 * and the overlay never blocks clicks.
 */
export function FollowingPointer({
  label,
  color = "var(--brand)",
  className,
  children,
  ...props
}: FollowingPointerProps) {
  const ref = useRef<HTMLDivElement>(null);
  const last = useRef({ x: 0, y: 0 });
  const [active, setActive] = useState(false);
  const reducedMotion = useReducedMotion();

  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const springX = useSpring(x, SPRING);
  const springY = useSpring(y, SPRING);

  // Position relative to the region, from the last known client point.
  const place = useCallback((jump: boolean) => {
    const rect = ref.current?.getBoundingClientRect();
    if (!rect) return;
    const nx = last.current.x - rect.left;
    const ny = last.current.y - rect.top;
    x.set(nx);
    y.set(ny);
    if (jump) {
      springX.jump(nx);
      springY.jump(ny);
    }
  }, [x, y, springX, springY]);

  const track = (event: React.PointerEvent<HTMLDivElement>) => {
    if (event.pointerType !== "mouse" || !matchMedia("(pointer: fine)").matches) return;
    last.current = { x: event.clientX, y: event.clientY };
    place(!active);
    setActive(true);
  };

  // Keep the arrow under the (hidden) pointer while the page scrolls.
  useEffect(() => {
    if (!active) return;
    const onScroll = () => place(false);
    addEventListener("scroll", onScroll, { capture: true, passive: true });
    return () => removeEventListener("scroll", onScroll, { capture: true });
  }, [active, place]);

  return (
    <div
      ref={ref}
      data-slot="following-pointer"
      className={cn("relative", active && "cursor-none! [&_*]:cursor-none!", className)}
      {...props}
      onPointerMove={(event) => {
        track(event);
        props.onPointerMove?.(event);
      }}
      onPointerLeave={(event) => {
        setActive(false);
        props.onPointerLeave?.(event);
      }}
    >
      {children}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0 z-50 overflow-hidden rounded-[inherit]"
      >
        <AnimatePresence>
          {active && (
            <motion.div
              className="absolute top-0 left-0"
              style={reducedMotion ? { x, y } : { x: springX, y: springY }}
              initial={reducedMotion ? false : { scale: 0, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={reducedMotion ? undefined : { scale: 0, opacity: 0 }}
              transition={{ duration: 0.15 }}
            >
              <svg
                viewBox="0 0 20 20"
                className="absolute -top-0.5 -left-0.5 size-5 drop-shadow-sm"
              >
                <path
                  d="M2.5 2.5 17 8.4l-6.4 2.2L8.4 17Z"
                  fill={color}
                  stroke="white"
                  strokeWidth="1.5"
                  strokeLinejoin="round"
                />
              </svg>
              {label != null && label !== "" && (
                <div
                  style={{ backgroundColor: color }}
                  className="absolute top-4 left-3.5 rounded-full px-2.5 py-1 text-xs font-medium whitespace-nowrap text-brand-foreground shadow-md ring-1 ring-white/70"
                >
                  {label}
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

"use client";

import { useRef, useState } from "react";

import { cn } from "@/lib/utils";

interface LensProps extends React.HTMLAttributes<HTMLDivElement> {
  /** The content to magnify, usually an `<img>` that fills the box */
  children: React.ReactNode;
  /** How many times the lens magnifies */
  zoomFactor?: number;
  /** Lens radius in px */
  radius?: number;
  /** Pin the lens open at this spot (percentages of width and height) and ignore the pointer — handy for touch screens and product callouts */
  staticPosition?: { x: number; y: number };
}

/**
 * A circular magnifier that follows the pointer over an image (or any
 * content). Keyboard users can focus it, move the lens with the arrow keys
 * (Shift for bigger steps) and hide it with Escape. The magnified copy is
 * aria-hidden and inert.
 */
export function Lens({
  children,
  zoomFactor = 2,
  radius = 80,
  staticPosition,
  className,
  style,
  ...props
}: LensProps) {
  const ref = useRef<HTMLDivElement>(null);
  const start = staticPosition ?? { x: 50, y: 50 };
  // Position lives in CSS variables, so pointer moves never re-render.
  const pos = useRef(start);
  const [shown, setShown] = useState(false);
  const visible = shown || !!staticPosition;

  const moveTo = (x: number, y: number) => {
    pos.current = { x: Math.min(100, Math.max(0, x)), y: Math.min(100, Math.max(0, y)) };
    ref.current?.style.setProperty("--x", `${pos.current.x}%`);
    ref.current?.style.setProperty("--y", `${pos.current.y}%`);
    setShown(true);
  };

  const track = (event: React.PointerEvent<HTMLDivElement>) => {
    if (staticPosition) return;
    const rect = event.currentTarget.getBoundingClientRect();
    moveTo(
      ((event.clientX - rect.left) / rect.width) * 100,
      ((event.clientY - rect.top) / rect.height) * 100
    );
  };

  const keys: Record<string, [number, number]> = {
    ArrowLeft: [-1, 0],
    ArrowRight: [1, 0],
    ArrowUp: [0, -1],
    ArrowDown: [0, 1],
  };

  return (
    <div
      ref={ref}
      tabIndex={0}
      data-slot="lens"
      onPointerMove={track}
      onPointerDown={track}
      onPointerLeave={(event) => event.pointerType === "mouse" && setShown(false)}
      onFocus={(event) => event.target.matches(":focus-visible") && setShown(true)}
      onBlur={() => setShown(false)}
      onKeyDown={(event) => {
        if (event.key === "Escape") setShown(false);
        const step = keys[event.key];
        if (!step || staticPosition) return;
        event.preventDefault();
        const size = event.shiftKey ? 12 : 4;
        moveTo(pos.current.x + step[0] * size, pos.current.y + step[1] * size);
      }}
      className={cn(
        "relative overflow-hidden rounded-2xl focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        !staticPosition && "cursor-crosshair",
        className
      )}
      style={
        {
          "--x": `${start.x}%`,
          "--y": `${start.y}%`,
          "--r": `${radius}px`,
          ...style,
        } as React.CSSProperties
      }
      {...props}
    >
      {children}
      <div
        aria-hidden
        inert
        className={cn(
          "pointer-events-none absolute inset-0 bg-background transition-[opacity,clip-path,transform-origin] duration-150 ease-out motion-reduce:transition-none",
          !visible && "opacity-0"
        )}
        style={{
          transform: `scale(${zoomFactor})`,
          transformOrigin: "var(--x) var(--y)",
          clipPath: `circle(calc(var(--r) / ${zoomFactor}) at var(--x) var(--y))`,
        }}
      >
        {children}
      </div>
      <div
        aria-hidden
        className={cn(
          "pointer-events-none absolute top-(--y) left-(--x) size-[calc(var(--r)*2)] -translate-1/2 rounded-full border-2 border-white/80 shadow-[0_10px_40px_-8px_rgb(0_0_0/0.45)] ring-1 ring-black/10 transition-[opacity,scale,top,left] duration-150 ease-out motion-reduce:transition-none",
          !visible && "scale-90 opacity-0"
        )}
      />
    </div>
  );
}

"use client"

import { useEffect, useRef, useState } from "react"
import {
  AnimatePresence,
  motion,
  useMotionValue,
  type HTMLMotionProps,
} from "motion/react"

import { cn } from "@/lib/utils"

/**
 * A custom pointer component that displays an animated cursor.
 * Add this as a child to any component to enable a custom pointer when hovering.
 * You can pass custom children to render as the pointer.
 *
 * @component
 * @param {HTMLMotionProps<"div">} props - The component props
 */
export function Pointer({
  className,
  style,
  children,
  ...props
}: HTMLMotionProps<"div">): React.ReactNode {
  const x = useMotionValue(0)
  const y = useMotionValue(0)
  const [isActive, setIsActive] = useState<boolean>(false)
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const parentElement =
      typeof window !== "undefined"
        ? (containerRef.current?.parentElement ?? null)
        : null

    const handleMouseMove = (e: MouseEvent) => {
      x.set(e.clientX)
      y.set(e.clientY)
      setIsActive(true)
    }

    const handleMouseEnter = (e: MouseEvent) => {
      x.set(e.clientX)
      y.set(e.clientY)
      setIsActive(true)
    }

    const handleMouseLeave = () => {
      setIsActive(false)
    }

    if (parentElement) {
      parentElement.style.cursor = "none"
      parentElement.addEventListener("mousemove", handleMouseMove)
      parentElement.addEventListener("mouseenter", handleMouseEnter)
      parentElement.addEventListener("mouseleave", handleMouseLeave)
    }

    return () => {
      if (parentElement) {
        parentElement.style.cursor = ""
        parentElement.removeEventListener("mousemove", handleMouseMove)
        parentElement.removeEventListener("mouseenter", handleMouseEnter)
        parentElement.removeEventListener("mouseleave", handleMouseLeave)
      }
    }
  }, [x, y])

  return (
    <>
      <div ref={containerRef} />
      <AnimatePresence>
        {isActive && (
          <motion.div
            className="pointer-events-none fixed z-50 transform-[translate(-50%,-50%)]"
            style={{
              top: y,
              left: x,
              ...style,
            }}
            initial={{
              scale: 0,
              opacity: 0,
            }}
            animate={{
              scale: 1,
              opacity: 1,
            }}
            exit={{
              scale: 0,
              opacity: 0,
            }}
            {...props}
          >
            {children || (
              <svg
                stroke="currentColor"
                fill="currentColor"
                strokeWidth="1"
                viewBox="0 0 16 16"
                height="24"
                width="24"
