"use client";

import { useRef } from "react";
import { motion, useInView, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

const EASE = [0.22, 1, 0.36, 1] as const;

interface PointerHighlightProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** The phrase to frame */
  children: React.ReactNode;
  /** Classes for the drawn outline (border colour, width, radius, fill) */
  rectangleClassName?: string;
  /** Classes for the pointer icon (colour, size) */
  pointerClassName?: string;
  /** Play only the first time the phrase enters the viewport */
  once?: boolean;
}

/**
 * Frames an inline phrase when it scrolls into view: an outline draws out
 * from the top-left corner, then a small pointer glides in to rest on its
 * bottom-right corner, like a selection someone just made. The phrase
 * becomes an inline-block, so keep it short enough not to wrap.
 */
export function PointerHighlight({
  children,
  rectangleClassName,
  pointerClassName,
  once = true,
  className,
  ...props
}: PointerHighlightProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once, amount: 0.6 });
  const reducedMotion = useReducedMotion();
  const instant = { duration: 0 };

  return (
    <span
      ref={ref}
      data-slot="pointer-highlight"
      className={cn("relative inline-block", className)}
      {...props}
    >
      {children}
      {/* Reduced motion: the !important classes beat motion's inline styles,
          so the finished frame shows from the first paint. */}
      <span
        aria-hidden
        className="pointer-events-none absolute -inset-x-[0.2em] -inset-y-[0.06em]"
      >
        <motion.span
          initial={{ width: "0%", height: "0%", opacity: 0 }}
          animate={
            inView
              ? { width: "100%", height: "100%", opacity: 1 }
              : { width: "0%", height: "0%", opacity: 0 }
          }
          transition={
            reducedMotion
              ? instant
              : { duration: 0.7, ease: EASE, opacity: { duration: 0.1 } }
          }
          className={cn(
            "absolute top-0 left-0 block border-2 border-primary bg-primary/5 motion-reduce:size-full! motion-reduce:opacity-100!",
            rectangleClassName
          )}
        />
        <motion.svg
          viewBox="0 0 20 20"
          initial={{ opacity: 0, x: 18, y: 18 }}
          animate={inView ? { opacity: 1, x: 0, y: 0 } : { opacity: 0, x: 18, y: 18 }}
          transition={
            reducedMotion ? instant : { duration: 0.5, ease: EASE, delay: inView ? 0.55 : 0 }
          }
          className={cn(
            "absolute top-full left-full -mt-1 -ml-1 size-[clamp(1rem,0.45em,1.75rem)] text-primary drop-shadow-sm motion-reduce:transform-none! motion-reduce:opacity-100!",
            pointerClassName
          )}
        >
          <path
            d="M2.5 2.5 17 8.4l-6.4 2.2L8.4 17Z"
            fill="currentColor"
            stroke="var(--background)"
            strokeWidth="1.5"
            strokeLinejoin="round"
          />
        </motion.svg>
      </span>
    </span>
  );
}

"use client";

import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import { createPortal } from "react-dom";
import { motion, useMotionValue, useReducedMotion, useSpring } from "motion/react";

import { cn } from "@/lib/utils";

const FINE = "(pointer: fine)";
const subscribeFine = (onChange: () => void) => {
  const query = matchMedia(FINE);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const SPRING = { stiffness: 300, damping: 28, mass: 0.6 };

interface SmoothCursorProps {
  /** Limit the cursor to this element; defaults to the whole document */
  container?: React.RefObject<HTMLElement | null>;
  /** Hide the system cursor while the custom one is showing */
  hideNativeCursor?: boolean;
  /** CSS selector for elements that make the ring grow */
  interactiveSelector?: string;
  /** Classes for the dot */
  dotClassName?: string;
  /** Classes for the trailing ring */
  ringClassName?: string;
}

/**
 * A page-level custom cursor: a dot that sits on the pointer and a ring that
 * trails it on a spring and grows over links, buttons and form controls.
 * Mount it once (e.g. in a layout). It only runs for a mouse on a
 * fine-pointer device, hides while the pointer is outside the window or
 * container, and never receives pointer events.
 */
export function SmoothCursor({
  container,
  hideNativeCursor = true,
  interactiveSelector = "a, button, [role=button], input, select, textarea, label, summary",
  dotClassName,
  ringClassName,
}: SmoothCursorProps) {
  // false on the server and on touch screens, so nothing renders there.
  const fine = useSyncExternalStore(subscribeFine, () => matchMedia(FINE).matches, () => false);
  const reducedMotion = useReducedMotion();
  const [visible, setVisible] = useState(false);
  const [hovering, setHovering] = useState(false);
  const [pressed, setPressed] = useState(false);
  const shown = useRef(false);

  const x = useMotionValue(0);
  const y = useMotionValue(0);
  const ringX = useSpring(x, SPRING);
  const ringY = useSpring(y, SPRING);

  useEffect(() => {
    if (!fine) return;
    const root = container ? container.current : document.documentElement;
    if (!root) return;

    const hide = () => {
      shown.current = false;
      setVisible(false);
      setPressed(false);
    };
    const move = (event: PointerEvent) => {
      if (event.pointerType !== "mouse") return hide();
      x.set(event.clientX);
      y.set(event.clientY);
      if (!shown.current) {
        ringX.jump(event.clientX);
        ringY.jump(event.clientY);
        shown.current = true;
        setVisible(true);
      }
      const target = event.target as Element | null;
      setHovering(!!target?.closest?.(interactiveSelector));
    };
    const down = () => setPressed(true);
    const up = () => setPressed(false);
    // relatedTarget is null when the pointer leaves the window.
    const out = (event: PointerEvent) => !event.relatedTarget && hide();

    root.addEventListener("pointermove", move, { passive: true });
    root.addEventListener("pointerdown", down);
    root.addEventListener("pointerleave", hide);
    addEventListener("pointerup", up);
    addEventListener("blur", hide);
    document.addEventListener("pointerout", out);
    return () => {
      root.removeEventListener("pointermove", move);
      root.removeEventListener("pointerdown", down);
      root.removeEventListener("pointerleave", hide);
      removeEventListener("pointerup", up);
      removeEventListener("blur", hide);
      document.removeEventListener("pointerout", out);
      hide();
    };
  }, [fine, container, interactiveSelector, x, y, ringX, ringY]);

  // Hide the system cursor only while ours is on screen; restored on unmount.
  useEffect(() => {
    const root = container ? container.current : document.documentElement;
    if (!root || !visible || !hideNativeCursor) return;
    root.setAttribute("data-smooth-cursor", "");
    return () => root.removeAttribute("data-smooth-cursor");
  }, [visible, hideNativeCursor, container]);

  if (!fine) return null;

  const snap = reducedMotion ? { duration: 0 } : { duration: 0.2 };
  const scale = (hovering ? 1.8 : 1) * (pressed ? 0.8 : 1);

  return createPortal(
    <div
      aria-hidden
      data-slot="smooth-cursor"
      className="pointer-events-none fixed top-0 left-0 z-[9999]"
    >
      <style>{"[data-smooth-cursor],[data-smooth-cursor] *{cursor:none!important}"}</style>
      <motion.div
        style={reducedMotion ? { x, y } : { x: ringX, y: ringY }}
        className="absolute top-0 left-0"
      >
        <motion.div
          initial={false}
          animate={{ scale, opacity: visible ? 1 : 0 }}
          transition={snap}
          className={cn(
            "-mt-4 -ml-4 size-8 rounded-full border-[1.5px] border-primary/60 transition-colors motion-reduce:transition-none",
            hovering && "bg-primary/10",
            ringClassName
          )}
        />
      </motion.div>
      <motion.div
        style={{ x, y }}
        initial={false}
        animate={{ opacity: visible ? 1 : 0, scale: hovering ? 0.5 : 1 }}
        transition={snap}
        className={cn("absolute -top-1 -left-1 size-2 rounded-full bg-primary", dotClassName)}
      />
    </div>,
    document.body
  );
}

"use client";

import { useEffect, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { cn } from "@/lib/utils";

export interface Testimonial {
  quote: string;
  name: string;
  role: string;
  /** Optional image URL; falls back to the person's initials */
  src?: string;
}

interface AnimatedTestimonialsProps {
  testimonials: Testimonial[];
  /** Seconds between slides; 0 disables autoplay */
  interval?: number;
  className?: string;
}

const initials = (name: string) =>
  name
    .split(" ")
    .map((part) => part[0])
    .slice(0, 2)
    .join("");

/**
 * Testimonial carousel that crossfades portraits behind the quote.
 * Autoplay pauses on hover and focus, has a pause button, and is off under
 * `prefers-reduced-motion`; the controls still work.
 */
export function AnimatedTestimonials({
  testimonials,
  interval = 6,
  className,
}: AnimatedTestimonialsProps) {
  const [index, setIndex] = useState(0);
  const [paused, setPaused] = useState(false);
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const reducedMotion = useReducedMotion();
  const count = testimonials.length;
  const autoplay = Boolean(interval) && count > 1;

  useEffect(() => {
    if (!autoplay || reducedMotion || paused || hovered || focused) return;
    const id = window.setInterval(
      () => setIndex((i) => (i + 1) % count),
      interval * 1000
    );
    return () => window.clearInterval(id);
  }, [autoplay, interval, count, reducedMotion, paused, hovered, focused]);

  if (!count) return null;
  const active = testimonials[index];
  const duration = reducedMotion ? 0 : 0.35;

  return (
    <div
      data-slot="animated-testimonials"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onFocus={() => setFocused(true)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) {
          setFocused(false);
        }
      }}
      className={cn("flex flex-col gap-6 sm:flex-row sm:items-center", className)}
    >
      <div className="relative size-24 shrink-0 sm:size-32">
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.div
            key={index}
            initial={{ opacity: 0, scale: 0.92, rotate: -4 }}
            animate={{ opacity: 1, scale: 1, rotate: 0 }}
            exit={{ opacity: 0, scale: 0.92, rotate: 4 }}
            transition={{ duration, ease: "easeOut" }}
            className="absolute inset-0 overflow-hidden rounded-2xl border bg-muted"
          >
            {active.src ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img loading="lazy" decoding="async"
                src={active.src}
                alt={active.name}
                className="size-full object-cover"
              />
            ) : (
              <span className="flex size-full items-center justify-center bg-gradient-to-br from-brand-from to-brand-to text-2xl font-semibold text-brand-foreground">
                {initials(active.name)}
              </span>
            )}
          </motion.div>
        </AnimatePresence>
      </div>

      <div className="min-w-0 flex-1">
        <AnimatePresence mode="wait" initial={false}>
          <motion.blockquote
            key={index}
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            transition={{ duration, ease: "easeOut" }}
          >
            <p className="text-lg leading-relaxed text-balance">
              &ldquo;{active.quote}&rdquo;
            </p>
            <footer className="mt-3 text-sm text-muted-foreground">
              <span className="font-medium text-foreground">{active.name}</span>
              {" — "}
              {active.role}
            </footer>
          </motion.blockquote>
        </AnimatePresence>

        {count > 1 && (
          <div className="mt-4 flex items-center">
            {autoplay && (
              // Hidden by CSS under reduced motion, where autoplay is off.
              <button
                type="button"
                onClick={() => setPaused((value) => !value)}
                aria-label={paused ? "Play testimonials" : "Pause testimonials"}
                className="mr-2 grid size-6 place-items-center rounded-full text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring motion-reduce:hidden"
              >
                <svg
                  width="12"
                  height="12"
                  viewBox="0 0 12 12"
                  fill="currentColor"
                  aria-hidden
                >
                  {paused ? (
                    <path d="M3 1.5v9l7.5-4.5z" />
                  ) : (
                    <path d="M2.5 1.5h2.5v9H2.5zM7 1.5h2.5v9H7z" />
                  )}
                </svg>
              </button>
            )}
            {/* Each 24px button is the hit area; the pill inside is visual. */}
            {testimonials.map((testimonial, i) => (
              <button
                key={testimonial.name}
                type="button"
                onClick={() => setIndex(i)}
                aria-label={`Show testimonial from ${testimonial.name}`}
                aria-current={i === index}
                className="group/dot grid h-6 min-w-6 place-items-center rounded-full focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                <span
                  className={cn(
                    "h-1.5 rounded-full transition-all motion-reduce:transition-none",
                    i === index
                      ? "w-6 bg-brand"
                      : "w-1.5 bg-muted-foreground/30 group-hover/dot:bg-muted-foreground/60"
                  )}
                />
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

