/** Colours @mentions so they read like a real post. */
function withMentions(text: string) {
  return text.split(/(@\w+)/g).map((part, i) =>
    part.startsWith("@") ? (
      <span key={i} className="text-brand">
        {part}
      </span>
    ) : (
      part
    )
  );
}

