  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Spinner } from "@/components/ui/spinner"
import { cn } from "@/lib/utils"
import { IconPlaceholder } from "@/components/icons/icon-placeholder"

interface UploadFile {
  id: number
  name: string
  size: string
  progress: number
}

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

export default function FileUploadBlock() {
  const [files, setFiles] = React.useState<UploadFile[]>([])
  const [isDragging, setIsDragging] = React.useState(false)
  const inputRef = React.useRef<HTMLInputElement>(null)
  const nextId = React.useRef(1)
  const timers = React.useRef<Record<number, ReturnType<typeof setInterval>>>(
    {}
  )

  React.useEffect(() => {
    const running = timers.current
    return () => {
      Object.values(running).forEach((t) => clearInterval(t))
    }
  }, [])

  function simulateUpload(id: number) {
    timers.current[id] = setInterval(() => {
      setFiles((prev) =>
        prev.map((f) => {
          if (f.id !== id) return f
          const next = Math.min(100, f.progress + 8)
          if (next >= 100) {
            clearInterval(timers.current[id])
            delete timers.current[id]
          }
          return { ...f, progress: next }
        })
      )
    }, 180)
  }

  function addFiles(fileList: FileList | null) {
    if (!fileList || fileList.length === 0) return
    const incoming: UploadFile[] = Array.from(fileList).map((file) => ({
      id: nextId.current++,
      name: file.name,
      size: formatSize(file.size),
      progress: 0,
    }))
    setFiles((prev) => [...prev, ...incoming])
    incoming.forEach((f) => simulateUpload(f.id))
  }

  function removeFile(id: number) {
    if (timers.current[id]) {
      clearInterval(timers.current[id])
      delete timers.current[id]
    }
    setFiles((prev) => prev.filter((f) => f.id !== id))
  }

  function clearAll() {
    Object.values(timers.current).forEach((t) => clearInterval(t))
    timers.current = {}
    setFiles([])
  }

  return (
    <section className="flex w-full items-center justify-center bg-background px-6 py-12 text-foreground">
      <Card className="w-full max-w-md">
        <CardHeader>
          <CardTitle>Upload files</CardTitle>
          <CardDescription>
            Attach documents, images, or other assets to this project.
          </CardDescription>
        </CardHeader>
        <CardContent className="flex flex-col gap-4">
          <input
            ref={inputRef}
            type="file"
            multiple
            className="sr-only"
            onChange={(e) => {
              addFiles(e.target.files)
              e.target.value = ""
            }}
          />

          <div
            onDragOver={(e) => {
              e.preventDefault()
              setIsDragging(true)
            }}
            onDragLeave={(e) => {
              e.preventDefault()
              setIsDragging(false)
            }}
            onDrop={(e) => {
              e.preventDefault()
              setIsDragging(false)
              addFiles(e.dataTransfer.files)
            }}
            className={cn(
              "flex flex-col items-center justify-center gap-3 rounded-lg border border-dashed border-border bg-muted/40 px-6 py-10 transition-colors",
              isDragging && "border-primary bg-muted"
            )}
          >
            <div className="flex size-10 items-center justify-center rounded-lg border border-border bg-background">
              <IconPlaceholder
                lucide="UploadCloud"
                tabler="IconCloudUpload"
                hugeicons="CloudUploadIcon"
                phosphor="CloudArrowUp"
                remixicon="RiUploadCloud2Line"
                className="size-5 text-muted-foreground"
                aria-hidden="true"
              />
            </div>
            <div className="flex flex-col items-center gap-1 text-center">
              <p className="text-sm font-medium text-foreground">
                Drag &amp; drop files or browse
              </p>
              <p className="text-xs text-muted-foreground">
                Supports PDF, PNG, JPG up to 25 MB
              </p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => inputRef.current?.click()}
            >
              <IconPlaceholder
                lucide="UploadCloud"
                tabler="IconCloudUpload"
                hugeicons="CloudUploadIcon"
                phosphor="CloudArrowUp"
                remixicon="RiUploadCloud2Line"
                data-icon="inline-start"
                aria-hidden="true"
              />
              Browse Files
            </Button>
          </div>

          {files.length > 0 && (
            <div className="flex flex-col gap-2">
              <div className="flex items-center justify-between">
                <p className="text-xs text-muted-foreground tabular-nums">
                  <span className="font-medium text-foreground">
                    {files.length}
                  </span>{" "}
                  {files.length === 1 ? "File" : "Files"}
                </p>
                <button
                  type="button"
                  onClick={clearAll}
                  className="text-xs font-medium text-muted-foreground transition-colors hover:text-foreground"
                >
                  Clear All
                </button>
              </div>
              <ul className="flex flex-col gap-2">
                {files.map((file) => {
                  const done = file.progress >= 100
                  return (
                    <li key={file.id}>
                      <Attachment
                        state={done ? "done" : "uploading"}
                        size="sm"
                        className="w-full"
                      >
                        <AttachmentMedia>
                          {done ? (
                            <IconPlaceholder
                              lucide="Check"
                              tabler="IconCheck"
                              hugeicons="Tick02Icon"
                              phosphor="Check"
                              remixicon="RiCheckLine"
                              className="text-primary"
                              aria-hidden="true"
                            />
                          ) : (
                            <Spinner />
                          )}
                        </AttachmentMedia>
                        <AttachmentContent>
                          <AttachmentTitle>{file.name}</AttachmentTitle>
                          <AttachmentDescription className="tabular-nums">
                            {done
                              ? `Uploaded ${file.size}`
                              : `Uploading ${file.progress}%`}
                          </AttachmentDescription>
                        </AttachmentContent>
                        <AttachmentActions>
                          <AttachmentAction
                            aria-label={`Remove ${file.name}`}
                            onClick={() => removeFile(file.id)}
                          >
                            <IconPlaceholder
                              lucide="X"
                              tabler="IconX"
                              hugeicons="Cancel01Icon"
                              phosphor="X"
                              remixicon="RiCloseLine"
                              aria-hidden="true"
                            />
                          </AttachmentAction>
                        </AttachmentActions>
                      </Attachment>
                    </li>
                  )
                })}
              </ul>
            </div>
          )}
        </CardContent>
      </Card>
    </section>
  )
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"
import { toast } from "sonner"

import {
  Attachment,
  AttachmentAction,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentTitle,
} from "@/components/ui/attachment"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Spinner } from "@/components/ui/spinner"
import { Toaster } from "@/components/ui/sonner"
import { cn } from "@/lib/utils"
import { IconPlaceholder } from "@/components/icons/icon-placeholder"

const MAX_SIZE = 25 * 1024 * 1024
const ACCEPTED = ["image/png", "image/jpeg", "application/pdf"]

type UploadStatus = "uploading" | "done" | "error"

type UploadItem = {
  id: string
  name: string
  size: number
  progress: number
  status: UploadStatus
  error?: string
}

function formatSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

function validate(file: File) {
  if (!ACCEPTED.includes(file.type)) return "Unsupported file type"
  if (file.size > MAX_SIZE) return "File exceeds 25 MB limit"
  return undefined
}

const seedFiles: UploadItem[] = [
  {
    id: "seed-1",
    name: "Acme-brand-guidelines.pdf",
    size: 4_812_345,
    progress: 100,
    status: "done",
  },
  {
    id: "seed-2",
    name: "homepage-hero@2x.png",
    size: 1_204_576,
    progress: 64,
    status: "uploading",
  },
]

export default function FileUploadBlock() {
  const [items, setItems] = useState<UploadItem[]>(seedFiles)
  const [isDragging, setIsDragging] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)
  const dragDepth = useRef(0)
  const hasActiveUploads = items.some((i) => i.status === "uploading")
  const toastedRef = useRef<Set<string>>(
    new Set(seedFiles.filter((f) => f.status === "done").map((f) => f.id))
  )

  useEffect(() => {
    if (!hasActiveUploads) return
    const timer = setInterval(() => {
      setItems((prev) =>
        prev.map((item) => {
          if (item.status !== "uploading") return item
          const next = Math.min(100, item.progress + Math.random() * 18 + 6)
          if (next >= 100) {
            return { ...item, progress: 100, status: "done" }
          }
          return { ...item, progress: next }
        })
      )
    }, 600)
    return () => clearInterval(timer)
  }, [hasActiveUploads])

  useEffect(() => {
    for (const item of items) {
      if (item.status === "done" && !toastedRef.current.has(item.id)) {
        toastedRef.current.add(item.id)
        toast.success(`${item.name} uploaded`)
      }
    }
  }, [items])

  const addFiles = useCallback((fileList: FileList | null) => {
    if (!fileList) return
    const next: UploadItem[] = Array.from(fileList).map((file) => {
      const error = validate(file)
      return {
        id: `${file.name}-${file.size}-${Date.now()}-${Math.random()}`,
        name: file.name,
        size: file.size,
        progress: 0,
        status: error ? "error" : "uploading",
        error,
      }
    })
    setItems((prev) => [...next, ...prev])
  }, [])

  const removeItem = useCallback((id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id))
  }, [])

  const onDrop = useCallback(
    (event: React.DragEvent<HTMLDivElement>) => {
      event.preventDefault()
      dragDepth.current = 0
      setIsDragging(false)
      addFiles(event.dataTransfer.files)
    },
    [addFiles]
  )

  return (
    <section className="flex w-full items-center justify-center bg-muted/30 px-6 py-16 text-foreground">
      <Toaster />
      <Card className="w-full max-w-xl">
        <CardHeader>
          <CardTitle>Upload assets</CardTitle>
          <CardDescription>
            Drag and drop your files or browse to attach them to Acme.
          </CardDescription>
        </CardHeader>
        <CardContent className="flex flex-col gap-5">
          <div
            role="button"
            tabIndex={0}
            onClick={() => inputRef.current?.click()}
            onKeyDown={(event) => {
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault()
                inputRef.current?.click()
              }
            }}
            onDragOver={(event) => {
              event.preventDefault()
            }}
            onDragEnter={(event) => {
              event.preventDefault()
              dragDepth.current += 1
              setIsDragging(true)
            }}
            onDragLeave={(event) => {
              event.preventDefault()
              dragDepth.current -= 1
              if (dragDepth.current <= 0) {
                dragDepth.current = 0
                setIsDragging(false)
              }
            }}
            onDrop={onDrop}
            className={cn(
              "flex cursor-pointer flex-col items-center justify-center gap-3 rounded-lg border border-dashed px-6 py-12 text-center transition-colors outline-none",
              "focus-visible:ring-[3px] focus-visible:ring-ring/50",
              isDragging
                ? "border-primary bg-primary/5"
                : "border-border bg-muted/40 hover:bg-muted/60"
            )}
          >
            <input
              ref={inputRef}
              type="file"
              multiple
              accept={ACCEPTED.join(",")}
              className="sr-only"
              onChange={(event) => {
                addFiles(event.target.files)
                event.target.value = ""
              }}
            />
            <div
              className={cn(
                "flex size-12 items-center justify-center rounded-lg border transition-colors",
                isDragging
                  ? "border-primary bg-background text-primary"
                  : "border-border bg-background text-muted-foreground"
              )}
            >
              <IconPlaceholder
                lucide="UploadCloud"
                tabler="IconCloudUpload"
                hugeicons="CloudUploadIcon"
                phosphor="CloudArrowUp"
                remixicon="RiUploadCloud2Line"
                className="size-6"
                aria-hidden="true"
              />
            </div>
            <div className="flex flex-col gap-1">
              <p className="text-sm font-medium text-foreground">
                {isDragging
                  ? "Release to upload"
                  : "Drag & drop files or click to browse"}
              </p>
              <p className="text-xs text-muted-foreground">
                Supports PDF, PNG, JPG up to 25 MB
              </p>
            </div>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={(event) => {
                event.stopPropagation()
                inputRef.current?.click()
              }}
            >
              <IconPlaceholder
                lucide="UploadCloud"
                tabler="IconCloudUpload"
                hugeicons="CloudUploadIcon"
                phosphor="CloudArrowUp"
                remixicon="RiUploadCloud2Line"
                data-icon="inline-start"
                aria-hidden="true"
              />
              Browse Files
            </Button>
          </div>

          {items.length > 0 && (
            <div className="flex flex-col gap-2">
              <div className="flex items-center justify-between">
                <p className="text-xs text-muted-foreground tabular-nums">
                  <span className="font-medium text-foreground">
                    {items.length}
                  </span>{" "}
                  {items.length === 1 ? "File" : "Files"}
                </p>
                <button
                  type="button"
                  onClick={() => setItems([])}
                  className="text-xs font-medium text-muted-foreground transition-colors hover:text-foreground"
                >
                  Clear All
                </button>
              </div>

              <ul className="flex flex-col gap-2">
                {items.map((item) => (
                  <li key={item.id}>
                    <Attachment
                      state={item.status}
                      size="sm"
                      className="w-full"
                    >
                      <AttachmentMedia>
                        {item.status === "error" ? (
                          <IconPlaceholder
                            lucide="TriangleAlert"
                            tabler="IconAlertTriangle"
                            hugeicons="Alert01Icon"
                            phosphor="Warning"
                            remixicon="RiAlertLine"
                            aria-hidden="true"
                          />
                        ) : item.status === "done" ? (
                          <IconPlaceholder
                            lucide="Check"
                            tabler="IconCheck"
                            hugeicons="Tick02Icon"
                            phosphor="Check"
                            remixicon="RiCheckLine"
                            className="text-primary"
                            aria-hidden="true"
                          />
                        ) : (
                          <Spinner />
                        )}
                      </AttachmentMedia>
                      <AttachmentContent>
                        <AttachmentTitle>{item.name}</AttachmentTitle>
                        <AttachmentDescription className="tabular-nums">
                          {item.status === "error"
                            ? item.error
                            : item.status === "done"
                              ? `Uploaded ${formatSize(item.size)}`
                              : `Uploading ${Math.round(item.progress)}%`}
                        </AttachmentDescription>
                      </AttachmentContent>
                      <AttachmentActions>
                        <AttachmentAction
                          aria-label={`Remove ${item.name}`}
                          onClick={() => removeItem(item.id)}
                        >
                          <IconPlaceholder
                            lucide="X"
                            tabler="IconX"
                            hugeicons="Cancel01Icon"
                            phosphor="X"
                            remixicon="RiCloseLine"
                            aria-hidden="true"
                          />
                        </AttachmentAction>
                      </AttachmentActions>
                    </Attachment>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </CardContent>
      </Card>
    </section>
  )
}

