            </div>
            {task.commentCount > 0 && (
              <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                <IconPlaceholder
                  lucide="MessageCircle"
                  tabler="IconMessageCircle"
                  hugeicons="Message01Icon"
