  IconCopy,
  IconMicrophone,
  IconPaperclip,
  IconPhoto,
  IconPlayerStopFilled,
  IconPlus,
  IconRefresh,
  IconThumbDown,
  IconThumbUp,
  IconWorldSearch,
} from '@tabler/icons-react';
import type React from 'react';
import { useState } from 'react';
import { Bubble, BubbleContent } from '@/components/ui/bubble';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from '@/components/ui/input-group';
import {
  Message,
  MessageContent,
  MessageFooter,
} from '@/components/ui/message';
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from '@/components/ui/message-scroller';
import { Textarea } from '@/components/ui/textarea';
import { cn } from '@/lib/utils';

type Turn = {
  id: string;
  role: 'user' | 'assistant';
  text: string;
  streaming?: boolean;
};

const thread: Turn[] = [
  {
    id: '1',
    role: 'user',
    text: 'Is it true that a day on Venus is longer than its year?',
  },
  {
    id: '2',
    role: 'assistant',
    text: 'Yes. Venus takes 243 Earth days to rotate once, but only 225 days to orbit the Sun, so its day is longer than its year.\n\nIt also spins in the opposite direction to most planets, which means the Sun rises in the west there.',
  },
  { id: '3', role: 'user', text: 'How hot does it get on the surface?' },
  {
    id: '4',
    role: 'assistant',
    text: 'The surface sits around 465°C, hot enough to melt lead. The atmosphere traps so much heat that Venus stays hotter than Mercury, even though Mercury is much closer to the Sun.',
  },
];

const replies = [
  'Good question. Venus has no moons and no rings, which makes it unusual among the inner planets. Most explanations point to its slow, retrograde spin: any moon it once had would have drifted inward and been pulled apart by tidal forces.\n\nMercury is the only other moonless planet in the solar system.',
  'The clouds are mostly sulfuric acid droplets, sitting about 50 to 70 km above the surface. They reflect roughly 75% of incoming sunlight, which is why Venus is the brightest object in our sky after the Moon.\n\nBelow the clouds the air is almost entirely carbon dioxide, with pressure about 92 times that of Earth at sea level.',
  'Several landers have made it down. The Soviet Venera 7 was the first to transmit from the surface in 1970, and Venera 13 survived for 127 minutes in 1982, long enough to send back the first color photos.\n\nNothing has lasted more than a couple of hours; the heat and pressure destroy electronics quickly.',
];

const thinkDelay = 600;
const wordDelay = 35;

const easeOut = 'ease-[cubic-bezier(0.23,1,0.32,1)]';
const press = `${easeOut} transition-[scale,background-color] duration-150 active:scale-[0.96]`;
const enter = `${easeOut} motion-reduce:slide-in-from-bottom-0 fade-in slide-in-from-bottom-1 animate-in duration-200`;
const swap = `${easeOut} fade-in zoom-in-95 animate-in duration-150`;

export default function Chat01() {
  const [turns, setTurns] = useState(thread);
  const [draft, setDraft] = useState('');
  const [listening, setListening] = useState(false);
  const [replyIndex, setReplyIndex] = useState(0);
  const [edit, setEdit] = useState<{ id: string; text: string } | null>(null);
  const streaming = turns.some((t) => t.streaming);

  const stream = (replyId: string) => {
    const words = replies[replyIndex % replies.length].split(' ');
    setReplyIndex(replyIndex + 1);
    setTurns((prev) =>
      prev.map((t) =>
        t.id === replyId ? { ...t, text: '', streaming: true } : t
      )
    );
    let shown = 0;
    setTimeout(() => {
      const timer = setInterval(() => {
        shown += 1;
        const done = shown >= words.length;
        setTurns((prev) =>
          prev.map((t) =>
            t.id === replyId
              ? {
                  ...t,
                  text: words.slice(0, shown).join(' '),
                  streaming: !done,
                }
              : t
          )
        );
        if (done) {
          clearInterval(timer);
        }
      }, wordDelay);
    }, thinkDelay);
  };

  const send = (e: React.FormEvent) => {
    e.preventDefault();
    const text = draft.trim();
    if (!text || streaming) {
      return;
    }
    const replyId = crypto.randomUUID();
    setTurns([
      ...turns,
      { id: crypto.randomUUID(), role: 'user', text },
      { id: replyId, role: 'assistant', text: '' },
    ]);
    setDraft('');
    stream(replyId);
  };

  const resend = () => {
    const text = edit?.text.trim();
    if (!(edit && text) || streaming) {
      return;
    }
    const at = turns.findIndex((t) => t.id === edit.id);
    const replyId = crypto.randomUUID();
    setTurns([
      ...turns.slice(0, at),
      { id: edit.id, role: 'user', text },
      { id: replyId, role: 'assistant', text: '' },
    ]);
    setEdit(null);
    stream(replyId);
  };

  const editLast = (e: React.KeyboardEvent) => {
    const last = turns.findLast((t) => t.role === 'user');
    if (e.key === 'ArrowUp' && !draft && last) {
      e.preventDefault();
      setEdit({ id: last.id, text: last.text });
    }
  };

  const body = (turn: Turn) => {
    const mine = turn.role === 'user';
    if (edit?.id === turn.id) {
      return (
        <>
          <Textarea
            aria-label="Edit message"
            autoFocus
            className={cn(
              enter,
              'min-h-0 w-md max-w-full resize-none rounded-[22px] border-0 bg-muted px-4 py-3 font-medium text-[15px]/6 focus-visible:ring-0 md:text-[15px]/6'
            )}
            onChange={(e) => setEdit({ ...edit, text: e.target.value })}
            onKeyDown={(e) => {
              if (e.key === 'Escape') {
                setEdit(null);
              }
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                resend();
              }
            }}
            value={edit.text}
          />
          <div className={cn(enter, 'flex items-center gap-1.5 self-end')}>
            <Button
              aria-label="Copy"
              className={cn(press, 'rounded-full')}
              onClick={() => navigator.clipboard.writeText(turn.text)}
              size="icon-sm"
              variant="ghost"
            >
              <IconCopy stroke={1.6} />
            </Button>
            <Button
              className={cn(press, 'rounded-full')}
              onClick={() => setEdit(null)}
              size="sm"
              variant="secondary"
            >
              Cancel
            </Button>
            <Button
              className={cn(press, 'rounded-full')}
              disabled={!edit.text.trim() || streaming}
              onClick={resend}
              size="sm"
            >
              Send
            </Button>
          </div>
        </>
      );
    }
    if (turn.streaming && !turn.text) {
      return (
        <span className="shimmer text-[15px]/6 text-muted-foreground">
          Thinking…
        </span>
      );
    }
    return turn.text.split('\n\n').map((paragraph) => (
      <Bubble
        align={mine ? 'end' : 'start'}
        className={
          mine
            ? '-mx-2.5 -my-1 box-content max-w-md cursor-pointer rounded-xl px-2.5 py-1 text-right font-medium transition-colors duration-150 ease-out hover:bg-muted'
            : undefined
        }
        key={paragraph}
        onDoubleClick={
          mine ? () => setEdit({ id: turn.id, text: turn.text }) : undefined
        }
        title={mine ? 'Double-click to edit' : undefined}
        variant="ghost"
      >
        <BubbleContent className="text-[15px]/6">{paragraph}</BubbleContent>
      </Bubble>
    ));
  };

  return (
    <div className="flex h-dvh w-full flex-col bg-background">
      <MessageScrollerProvider autoScroll>
        <MessageScroller>
          <MessageScrollerViewport>
            <MessageScrollerContent className="mx-auto w-full max-w-2xl gap-3.5 px-1.5 pt-12 pb-4">
              {turns.map((turn) => {
                const mine = turn.role === 'user';
                return (
                  <MessageScrollerItem
                    className={cn(
                      'px-2.5',
                      mine && 'pt-5.5 pb-1 first:pt-1',
                      !thread.some((t) => t.id === turn.id) && enter
                    )}
                    key={turn.id}
                    messageId={turn.id}
                  >
                    <Message align={mine ? 'end' : 'start'}>
                      <MessageContent className="gap-2">
                        {body(turn)}
                        {!(mine || turn.streaming) && (
                          <MessageFooter className={cn(enter, 'gap-0.5')}>
                            <Button
                              aria-label="Copy"
                              className={press}
                              onClick={() =>
                                navigator.clipboard.writeText(turn.text)
                              }
                              size="icon-sm"
                              variant="ghost"
                            >
                              <IconCopy stroke={1.6} />
                            </Button>
                            <Button
                              aria-label="Good response"
                              className={press}
                              size="icon-sm"
                              variant="ghost"
                            >
                              <IconThumbUp stroke={1.6} />
                            </Button>
                            <Button
                              aria-label="Bad response"
                              className={press}
                              size="icon-sm"
                              variant="ghost"
                            >
                              <IconThumbDown stroke={1.6} />
                            </Button>
                            <Button
                              aria-label="Regenerate"
                              className={press}
                              onClick={() => stream(turn.id)}
                              size="icon-sm"
                              variant="ghost"
                            >
                              <IconRefresh stroke={1.6} />
                            </Button>
                          </MessageFooter>
                        )}
                      </MessageContent>
                    </Message>
                  </MessageScrollerItem>
                );
              })}
            </MessageScrollerContent>
          </MessageScrollerViewport>
          <MessageScrollerButton className={easeOut} />
        </MessageScroller>
      </MessageScrollerProvider>

      <form
        className="mx-auto flex w-full max-w-2xl flex-col items-center gap-2.5 px-4 pt-3 pb-4"
        onSubmit={send}
      >
        <InputGroup className="h-13 rounded-full border-0 bg-muted px-2.5 has-[[data-slot=input-group-control]:focus-visible]:ring-0">
          <InputGroupAddon>
            <DropdownMenu>
              <DropdownMenuTrigger
                render={
                  <InputGroupButton
                    aria-label="Add attachment"
                    className={cn(press, 'rounded-full hover:bg-foreground/10')}
                    size="icon-sm"
                  />
                }
              >
                <IconPlus stroke={1.8} />
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="start"
                className="w-60 rounded-[20px] p-2 shadow-[0_0_0_1px_oklch(0_0_0/0.06),0_8px_24px_-6px_oklch(0_0_0/0.14)]"
                sideOffset={10}
              >
                <DropdownMenuGroup className="flex flex-col gap-0.5">
                  <DropdownMenuItem className="gap-3 rounded-xl px-3 py-2.5 text-[15px] [&>svg]:text-muted-foreground">
                    <IconPaperclip className="size-4.5" stroke={1.6} />
                    Add files
                  </DropdownMenuItem>
                  <DropdownMenuItem className="gap-3 rounded-xl px-3 py-2.5 text-[15px] [&>svg]:text-muted-foreground">
                    <IconPhoto className="size-4.5" stroke={1.6} />
                    Add photos
                  </DropdownMenuItem>
                  <DropdownMenuItem className="gap-3 rounded-xl px-3 py-2.5 text-[15px] [&>svg]:text-muted-foreground">
                    <IconWorldSearch className="size-4.5" stroke={1.6} />
                    Search the web
                  </DropdownMenuItem>
                </DropdownMenuGroup>
              </DropdownMenuContent>
            </DropdownMenu>
          </InputGroupAddon>
          <InputGroupInput
            className="text-[15px] md:text-[15px]"
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={editLast}
            placeholder={listening ? 'Listening…' : 'Ask anything'}
            value={draft}
          />
          <InputGroupAddon align="inline-end">
            {draft.trim() ? (
              <InputGroupButton
                aria-label="Send"
                className={cn(swap, press, 'rounded-full')}
                disabled={streaming}
                size="icon-sm"
                type="submit"
                variant="default"
              >
                <IconArrowUp stroke={2} />
              </InputGroupButton>
            ) : (
              <InputGroupButton
                aria-label={listening ? 'Stop listening' : 'Voice input'}
                aria-pressed={listening}
                className={cn(
                  swap,
                  press,
                  'rounded-full',
                  listening
                    ? 'bg-destructive/15 text-destructive hover:bg-destructive/25'
                    : 'hover:bg-foreground/10'
                )}
                onClick={() => setListening(!listening)}
                size="icon-sm"
              >
                {listening ? (
                  <IconPlayerStopFilled className="animate-pulse motion-reduce:animate-none" />
                ) : (
                  <IconMicrophone stroke={1.8} />
                )}
              </InputGroupButton>
            )}
          </InputGroupAddon>
        </InputGroup>
        <p className="text-muted-foreground text-xs">
          AI can make mistakes. Check important info.
        </p>
      </form>
    </div>
  );
}

'use client';

import {
  IconArrowUp,
  IconChevronDown,
  IconCopy,
  IconDots,
  IconMicrophone,
  IconPaperclip,
  IconPencil,
  IconPhoto,
  IconPlayerStopFilled,
  IconPlus,
  IconRefresh,
  IconThumbDown,
  IconThumbUp,
  IconVolume,
  IconWorldSearch,
} from '@tabler/icons-react';
import type React from 'react';
import { useState } from 'react';
import { Bubble, BubbleContent } from '@/components/ui/bubble';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupTextarea,
} from '@/components/ui/input-group';
import {
  Message,
  MessageContent,
  MessageFooter,
} from '@/components/ui/message';
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from '@/components/ui/message-scroller';
import { Textarea } from '@/components/ui/textarea';
import { cn } from '@/lib/utils';

type Turn = {
  id: string;
  role: 'user' | 'assistant';
  text: string;
  streaming?: boolean;
};

const thread: Turn[] = [
  {
    id: '1',
    role: 'user',
    text: 'Is it true that a day on Venus is longer than its year?',
  },
  {
    id: '2',
    role: 'assistant',
    text: 'Yes. Venus takes 243 Earth days to rotate once, but only 225 days to orbit the Sun, so its day is longer than its year.\n\nIt also spins in the opposite direction to most planets, which means the Sun rises in the west there.',
  },
  { id: '3', role: 'user', text: 'How hot does it get on the surface?' },
  {
    id: '4',
    role: 'assistant',
    text: 'The surface sits around 465°C, hot enough to melt lead. The atmosphere traps so much heat that Venus stays hotter than Mercury, even though Mercury is much closer to the Sun.',
  },
  {
    id: '5',
    role: 'user',
    text: 'How long would a person survive there without a suit?',
  },
  {
    id: '6',
    role: 'assistant',
    text: "A few seconds at most. The pressure down there is 92 times Earth's, similar to being 900 meters underwater, and the heat alone would be fatal almost immediately.\n\nFor reference, the Soviet Venera landers were built for those conditions and still failed within about two hours.",
  },
];

const replies = [
  'Good question. Venus has no moons and no rings, which makes it unusual among the inner planets. Most explanations point to its slow, retrograde spin: any moon it once had would have drifted inward and been pulled apart by tidal forces.\n\nMercury is the only other moonless planet in the solar system.',
  'The clouds are mostly sulfuric acid droplets, sitting about 50 to 70 km above the surface. They reflect roughly 75% of incoming sunlight, which is why Venus is the brightest object in our sky after the Moon.\n\nBelow the clouds the air is almost entirely carbon dioxide, with pressure about 92 times that of Earth at sea level.',
  'Several landers have made it down. The Soviet Venera 7 was the first to transmit from the surface in 1970, and Venera 13 survived for 127 minutes in 1982, long enough to send back the first color photos.\n\nNothing has lasted more than a couple of hours; the heat and pressure destroy electronics quickly.',
];

const levels = [
  { name: 'Instant', hint: '5.5' },
  { name: 'Medium' },
  { name: 'High' },
  { name: 'Extra High' },
  { name: 'Pro' },
];

const models = [
  'GPT-6',
  'GPT-5.6 Sol',
  'GPT-6 Astra',
  'GPT-5.6 Terra',
  'GPT-5.6 Luna',
];

const thinkDelay = 600;
const wordDelay = 35;

const easeOut = 'ease-[cubic-bezier(0.23,1,0.32,1)]';
const press = `${easeOut} transition-[scale,background-color] duration-150 active:scale-[0.96] motion-reduce:active:scale-100`;
const enter = `${easeOut} motion-reduce:slide-in-from-bottom-0 fade-in slide-in-from-bottom-1 animate-in duration-200`;
const swap = `${easeOut} fade-in zoom-in-95 motion-reduce:zoom-in-100 animate-in duration-150`;
const item = 'rounded-lg px-2.5 py-1.75 text-[13px]';

export default function Chat02() {
  const [turns, setTurns] = useState(thread);
  const [draft, setDraft] = useState('');
  const [tall, setTall] = useState(false);
  const [listening, setListening] = useState(false);
  const [level, setLevel] = useState('Extra High');
  const [model, setModel] = useState('GPT-5.6 Sol');
  const [replyIndex, setReplyIndex] = useState(0);
  const [edit, setEdit] = useState<{ id: string; text: string } | null>(null);
  const streaming = turns.some((t) => t.streaming);

  const stream = (replyId: string) => {
    const words = replies[replyIndex % replies.length].split(' ');
    setReplyIndex(replyIndex + 1);
    setTurns((prev) =>
      prev.map((t) =>
        t.id === replyId ? { ...t, text: '', streaming: true } : t
      )
    );
    let shown = 0;
    setTimeout(() => {
      const timer = setInterval(() => {
        shown += 1;
        const done = shown >= words.length;
        setTurns((prev) =>
          prev.map((t) =>
            t.id === replyId
              ? {
                  ...t,
                  text: words.slice(0, shown).join(' '),
                  streaming: !done,
                }
              : t
          )
        );
        if (done) {
          clearInterval(timer);
        }
      }, wordDelay);
    }, thinkDelay);
  };

  const send = (e: React.FormEvent) => {
    e.preventDefault();
    const text = draft.trim();
    if (!text || streaming) {
      return;
    }
    const replyId = crypto.randomUUID();
    setTurns([
      ...turns,
      { id: crypto.randomUUID(), role: 'user', text },
      { id: replyId, role: 'assistant', text: '' },
    ]);
    setDraft('');
    setTall(false);
    stream(replyId);
  };

  const resend = () => {
    const text = edit?.text.trim();
    if (!(edit && text) || streaming) {
      return;
    }
    const at = turns.findIndex((t) => t.id === edit.id);
    const reply = turns[at + 1];
    setTurns(turns.map((t) => (t.id === edit.id ? { ...t, text } : t)));
    setEdit(null);
    if (reply?.role === 'assistant') {
      stream(reply.id);
    }
  };

  const body = (turn: Turn, align: 'start' | 'end') => {
    if (edit?.id === turn.id) {
      return (
        <>
          <Textarea
            aria-label="Edit message"
            autoFocus
            className={cn(
              enter,
              'min-h-0 w-md max-w-full resize-none rounded-[18px] border-0 bg-muted px-3.5 py-2.5 text-[15px]/6 focus-visible:ring-0 md:text-[15px]/6'
            )}
            onChange={(e) => setEdit({ ...edit, text: e.target.value })}
            onKeyDown={(e) => {
              if (e.key === 'Escape') {
                setEdit(null);
              }
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                resend();
              }
            }}
            value={edit.text}
          />
          <div className={cn(enter, 'flex items-center gap-1.5 self-end')}>
            <Button
              className={cn(press, 'rounded-full')}
              onClick={() => setEdit(null)}
              size="sm"
              variant="secondary"
            >
              Cancel
            </Button>
            <Button
              className={cn(press, 'rounded-full')}
              disabled={!edit.text.trim() || streaming}
              onClick={resend}
              size="sm"
            >
              Send
            </Button>
          </div>
        </>
      );
    }
    if (turn.streaming && !turn.text) {
      return (
        <span className="shimmer text-[15px]/6 text-muted-foreground">
          Thinking…
        </span>
      );
    }
    return turn.text.split('\n\n').map((paragraph) => (
      <Bubble
        align={align}
        className="max-w-md data-[variant=ghost]:max-w-full"
        key={paragraph}
        variant={turn.role === 'user' ? 'muted' : 'ghost'}
      >
        <BubbleContent className="rounded-[18px] px-3.5 py-1.75 text-[15px]/5.5 group-data-[variant=ghost]/bubble:text-[15px]/6">
          {paragraph}
        </BubbleContent>
      </Bubble>
    ));
  };

  const action = (
    label: string,
    icon: React.ReactNode,
    onClick?: () => void
  ) => (
    <Button
      aria-label={label}
      className={cn(press, 'rounded-lg')}
      onClick={onClick}
      size="icon-sm"
      variant="ghost"
    >
      {icon}
    </Button>
  );

  return (
    <div className="flex h-dvh w-full flex-col bg-background">
      <MessageScrollerProvider autoScroll>
        <MessageScroller>
          <MessageScrollerViewport>
            <MessageScrollerContent className="mx-auto w-full max-w-2xl gap-4.5 px-4 pt-10 pb-4">
              {turns.map((turn) => {
                const mine = turn.role === 'user';
                const align = mine ? 'end' : 'start';
                return (
                  <MessageScrollerItem
                    className={cn(
                      mine && 'pt-4.5 first:pt-0',
                      !thread.some((t) => t.id === turn.id) && enter
                    )}
                    key={turn.id}
                    messageId={turn.id}
                  >
                    <Message align={align}>
                      <MessageContent className="gap-2.5">
                        {body(turn, align)}
                        {turn.text && edit?.id !== turn.id && (
                          <MessageFooter className="-mx-2 gap-0.5">
                            {action('Copy', <IconCopy stroke={1.6} />, () =>
                              navigator.clipboard.writeText(turn.text)
                            )}
                            {mine
                              ? action(
                                  'Edit',
                                  <IconPencil stroke={1.6} />,
                                  () =>
                                    setEdit({ id: turn.id, text: turn.text })
                                )
                              : action(
                                  'Regenerate',
                                  <IconRefresh stroke={1.6} />,
                                  () => stream(turn.id)
                                )}
                            {!mine && (
                              <DropdownMenu>
                                <DropdownMenuTrigger
                                  render={action(
                                    'More',
                                    <IconDots stroke={1.6} />
                                  )}
                                />
                                <DropdownMenuContent
                                  align="start"
                                  className="w-44 rounded-[14px] p-1.5"
                                >
                                  <DropdownMenuGroup className="flex flex-col gap-0.5">
                                    <DropdownMenuItem
                                      className={cn(item, 'gap-2.5')}
                                    >
                                      <IconThumbUp stroke={1.6} />
                                      Good response
                                    </DropdownMenuItem>
                                    <DropdownMenuItem
                                      className={cn(item, 'gap-2.5')}
                                    >
                                      <IconThumbDown stroke={1.6} />
                                      Bad response
                                    </DropdownMenuItem>
                                    <DropdownMenuItem
                                      className={cn(item, 'gap-2.5')}
                                    >
                                      <IconVolume stroke={1.6} />
                                      Read aloud
                                    </DropdownMenuItem>
                                  </DropdownMenuGroup>
                                </DropdownMenuContent>
                              </DropdownMenu>
                            )}
                          </MessageFooter>
                        )}
                      </MessageContent>
                    </Message>
                  </MessageScrollerItem>
                );
              })}
            </MessageScrollerContent>
          </MessageScrollerViewport>
          <MessageScrollerButton
            className={cn(
              easeOut,
              'bottom-2 h-7 gap-1.5 rounded-full border-0 px-3.5 font-medium text-muted-foreground text-xs shadow-[0_0_0_1px_oklch(0_0_0/0.06),0_2px_8px_oklch(0_0_0/0.08)] transition-[translate,scale,opacity,background-color] hover:text-foreground active:not-aria-[haspopup]:translate-y-0 data-[active=true]:active:scale-[0.96] dark:shadow-[0_0_0_1px_oklch(1_0_0/0.1),0_2px_8px_oklch(0_0_0/0.3)]'
            )}
            size="sm"
          >
            <IconChevronDown className="size-3.5" stroke={1.75} />
            Jump to latest
          </MessageScrollerButton>
        </MessageScroller>
      </MessageScrollerProvider>

      <form
        className="mx-auto flex w-full max-w-2xl flex-col items-center gap-2.5 px-4 pt-2 pb-3.5"
        onSubmit={send}
      >
        <InputGroup
          className={cn(
            'min-h-11 items-end rounded-[22px] bg-background px-0.5 shadow-xs has-[[data-slot=input-group-control]:focus-visible]:ring-0',
            tall && 'flex-wrap rounded-3xl'
          )}
        >
          <InputGroupAddon
            className={cn('pb-1.25 pl-2.5', tall && 'order-none')}
          >
            <DropdownMenu>
              <DropdownMenuTrigger
                render={
                  <InputGroupButton
                    aria-label="Add attachment"
                    className={cn(press, 'rounded-full')}
                    size="icon-sm"
                  />
                }
              >
                <IconPlus stroke={1.8} />
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="start"
                className="w-56 rounded-[14px] p-1.5"
                sideOffset={10}
              >
                <DropdownMenuGroup className="flex flex-col gap-0.5">
                  <DropdownMenuItem className={cn(item, 'gap-2.5')}>
                    <IconPaperclip stroke={1.6} />
                    Add files
                  </DropdownMenuItem>
                  <DropdownMenuItem className={cn(item, 'gap-2.5')}>
                    <IconPhoto stroke={1.6} />
                    Add photos
                  </DropdownMenuItem>
                  <DropdownMenuItem className={cn(item, 'gap-2.5')}>
                    <IconWorldSearch stroke={1.6} />
                    Search the web
                  </DropdownMenuItem>
                </DropdownMenuGroup>
              </DropdownMenuContent>
            </DropdownMenu>
          </InputGroupAddon>
          <InputGroupTextarea
            className={cn(
              'max-h-48 min-h-0 py-2.5 pl-1 text-[15px]/6 md:text-[15px]/6',
              tall && '-order-1 basis-full px-2.75 py-1.5'
            )}
            onChange={(e) => {
              setDraft(e.target.value);
              setTall(e.target.scrollHeight > 44);
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                e.currentTarget.form?.requestSubmit();
              }
            }}
            placeholder={listening ? 'Listening…' : 'Ask anything'}
            rows={1}
            value={draft}
          />
          <InputGroupAddon
            align="inline-end"
            className={cn('gap-1.5 pr-2.5 pb-1.25', tall && 'ml-auto')}
          >
            {draft.trim() ? (
              <InputGroupButton
                aria-label="Send"
                className={cn(swap, press, 'rounded-full')}
                disabled={streaming}
                size="icon-sm"
                type="submit"
                variant="default"
              >
                <IconArrowUp stroke={2} />
              </InputGroupButton>
            ) : (
              <InputGroupButton
                aria-label={listening ? 'Stop listening' : 'Voice input'}
                aria-pressed={listening}
                className={cn(
                  swap,
                  press,
                  'rounded-full',
                  listening &&
                    'bg-destructive/15 text-destructive hover:bg-destructive/25'
                )}
                onClick={() => setListening(!listening)}
                size="icon-sm"
              >
                {listening ? (
                  <IconPlayerStopFilled className="animate-pulse motion-reduce:animate-none" />
                ) : (
                  <IconMicrophone stroke={1.8} />
                )}
              </InputGroupButton>
            )}
            <DropdownMenu>
              <DropdownMenuTrigger
                render={
                  <InputGroupButton
                    aria-label="Intelligence level"
                    className={cn(
                      press,
                      'h-8 gap-1.25 rounded-full bg-muted px-3 font-medium text-[13px] text-muted-foreground hover:bg-muted'
                    )}
                    size="sm"
                  />
                }
              >
                {level}
                <IconChevronDown className="size-3" stroke={2} />
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="end"
                className="w-49 rounded-[14px] p-1.5"
                side="top"
                sideOffset={10}
              >
                <DropdownMenuGroup className="flex flex-col gap-0.5">
                  <DropdownMenuLabel className="px-2.5 pt-1 pb-0.5 text-[11px]">
                    Intelligence
                  </DropdownMenuLabel>
                  <DropdownMenuRadioGroup
                    onValueChange={setLevel}
                    value={level}
                  >
                    {levels.map((l) => (
                      <DropdownMenuRadioItem
                        className={cn(item, 'pr-8 pl-2.5')}
                        key={l.name}
                        value={l.name}
                      >
                        {l.name}
                        {l.hint && (
                          <span className="text-muted-foreground text-xs">
                            {l.hint}
                          </span>
                        )}
                      </DropdownMenuRadioItem>
                    ))}
                  </DropdownMenuRadioGroup>
                  <DropdownMenuSeparator className="mx-1.5 my-1" />
                  <DropdownMenuSub>
                    <DropdownMenuSubTrigger
                      className={cn(
                        item,
                        '[&>svg]:size-3.5 [&>svg]:text-muted-foreground'
                      )}
                    >
                      {model}
                    </DropdownMenuSubTrigger>
                    <DropdownMenuSubContent className="w-44 rounded-[14px] p-1.5">
                      <DropdownMenuRadioGroup
                        className="flex flex-col gap-0.5"
                        onValueChange={setModel}
                        value={model}
                      >
                        {models.map((m) => (
                          <DropdownMenuRadioItem
                            className={cn(item, 'pr-8 pl-2.5')}
                            key={m}
                            value={m}
                          >
                            {m}
                          </DropdownMenuRadioItem>
                        ))}
                      </DropdownMenuRadioGroup>
                    </DropdownMenuSubContent>
                  </DropdownMenuSub>
                </DropdownMenuGroup>
              </DropdownMenuContent>
            </DropdownMenu>
          </InputGroupAddon>
        </InputGroup>
        <p className="text-muted-foreground text-xs">
          AI can make mistakes. Check important info.
        </p>
      </form>
    </div>
  );
}

'use client';

import {
  IconArrowUp,
  IconMicrophone,
  IconPaperclip,
  IconPhoto,
  IconPlayerStopFilled,
  IconPlus,
  IconWorld,
  IconX,
} from '@tabler/icons-react';
import { useState } from 'react';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Textarea } from '@/components/ui/textarea';
import { cn } from '@/lib/utils';

export type Attachment = { name: string; meta: string; kind: string };

const easeOut = 'ease-[cubic-bezier(0.23,1,0.32,1)]';
const press = `${easeOut} transition-[scale,background-color] duration-150 active:scale-[0.96] motion-reduce:active:scale-100`;
const swap = `${easeOut} fade-in zoom-in-95 motion-reduce:zoom-in-100 animate-in duration-150`;
const round = 'size-7.5 rounded-full';

type Props = {
  draft: string;
  onDraft: (v: string) => void;
  attachment: Attachment | null;
  onAttachment: (a: Attachment | null) => void;
  streaming: boolean;
  onSend: () => void;
  onStop: () => void;
};

export function Composer({
  draft,
  onDraft,
  attachment,
  onAttachment,
  streaming,
  onSend,
  onStop,
}: Props) {
  const [search, setSearch] = useState(false);
  const [listening, setListening] = useState(false);
  const canSend = draft.trim().length > 0 && !streaming;

  return (
    <form
      className="mx-auto flex w-full max-w-160 flex-col px-4 pt-3 pb-5"
      onSubmit={(e) => {
        e.preventDefault();
        if (canSend) {
          onSend();
        }
      }}
    >
      <div
        className={cn(
          easeOut,
          'flex flex-col gap-2.5 rounded-3xl border border-border bg-background p-3 shadow-[0_1px_2px_oklch(0_0_0/0.04),0_8px_24px_oklch(0_0_0/0.05)] transition-[box-shadow,border-color] duration-150 focus-within:border-primary focus-within:ring-4 focus-within:ring-primary/12'
        )}
      >
        {attachment && (
          <div className={cn(swap, 'flex')}>
            <div className="flex h-12 items-center gap-2.5 rounded-xl border border-border bg-muted/50 pr-3 pl-2">
              <span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-destructive/10 font-mono font-semibold text-[9px] text-destructive tracking-[0.04em]">
                {attachment.kind}
              </span>
              <span className="flex flex-col gap-1">
                <span className="font-medium text-[13px]/4">
                  {attachment.name}
                </span>
                <span className="text-[11px]/3.5 text-muted-foreground">
                  {attachment.meta}
                </span>
              </span>
              <button
                aria-label="Remove attachment"
                className="rounded-md p-0.5 text-muted-foreground transition-colors hover:text-foreground"
                onClick={() => onAttachment(null)}
                type="button"
              >
                <IconX className="size-3.5" stroke={2} />
              </button>
            </div>
          </div>
        )}
        <Textarea
          aria-label="Message"
          className="field-sizing-content max-h-48 min-h-0 resize-none rounded-none border-0 bg-transparent px-1.5 py-0.5 text-sm/5 shadow-none focus-visible:ring-0 md:text-sm/5 dark:bg-transparent"
          onChange={(e) => onDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault();
              e.currentTarget.form?.requestSubmit();
            }
          }}
          placeholder={listening ? 'Listening…' : 'Ask anything'}
          rows={1}
          value={draft}
        />
        <div className="flex items-center gap-2">
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <Button
                  aria-label="Add attachment"
                  className={cn(press, round)}
                  size="icon-sm"
                  variant="outline"
                />
              }
            >
              <IconPlus stroke={2} />
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="start"
              className="w-52 rounded-xl p-1.5"
              side="top"
              sideOffset={10}
            >
              <DropdownMenuGroup className="flex flex-col gap-0.5">
                <DropdownMenuItem
                  className="h-8 gap-2.5 rounded-md px-2.5 text-[13px]"
                  onClick={() =>
                    onAttachment({
                      name: 'installer-quote.pdf',
                      meta: '2 pages · 412 KB',
                      kind: 'PDF',
                    })
                  }
                >
                  <IconPaperclip stroke={1.8} />
                  Add files
                </DropdownMenuItem>
                <DropdownMenuItem
                  className="h-8 gap-2.5 rounded-md px-2.5 text-[13px]"
                  onClick={() =>
                    onAttachment({
                      name: 'boiler-room.jpg',
                      meta: '3024 × 4032 · 2.1 MB',
                      kind: 'JPG',
                    })
                  }
                >
                  <IconPhoto stroke={1.8} />
                  Add photos
                </DropdownMenuItem>
              </DropdownMenuGroup>
            </DropdownMenuContent>
          </DropdownMenu>
          <Button
            aria-pressed={search}
            className={cn(
              press,
              'h-7.5 rounded-full px-2.75 text-xs',
              search &&
                'border-primary/30 bg-primary/8 text-primary hover:bg-primary/12'
            )}
            onClick={() => setSearch(!search)}
            size="sm"
            variant="outline"
          >
            <IconWorld stroke={2} />
            Search
          </Button>
          <div className="grow" />
          <Button
            aria-label={listening ? 'Stop listening' : 'Voice input'}
            aria-pressed={listening}
            className={cn(
              press,
              round,
              listening &&
                'bg-destructive/15 text-destructive hover:bg-destructive/25'
            )}
            onClick={() => setListening(!listening)}
            size="icon-sm"
            variant="ghost"
          >
            {listening ? (
              <IconPlayerStopFilled className="animate-pulse motion-reduce:animate-none" />
            ) : (
              <IconMicrophone stroke={2} />
            )}
          </Button>
          {streaming ? (
            <Button
              aria-label="Stop generating"
              className={cn(swap, press, round)}
              onClick={onStop}
              size="icon-sm"
            >
              <IconPlayerStopFilled className="size-3" />
            </Button>
          ) : (
            <Button
              aria-label="Send"
              className={cn(
                swap,
                press,
                round,
                !canSend &&
                  'bg-muted text-muted-foreground/70 hover:bg-muted disabled:opacity-100'
              )}
              disabled={!canSend}
              size="icon-sm"
              type="submit"
            >
              <IconArrowUp stroke={2.2} />
            </Button>
          )}
        </div>
      </div>
    </form>
  );
}

'use client';

import {
  IconAlertCircle,
  IconChevronDown,
  IconChevronRight,
  IconCopy,
  IconPencil,
  IconRefresh,
  IconThumbDown,
  IconThumbUp,
} from '@tabler/icons-react';
import React, { Fragment } from 'react';
import { Button } from '@/components/ui/button';
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/components/ui/collapsible';
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from '@/components/ui/message-scroller';
import { cn } from '@/lib/utils';

export type Turn = {
  id: string;
  role: 'user' | 'assistant';
  text: string;
  reasoning?: string;
  thought?: number;
  streaming?: boolean;
  error?: boolean;
  day?: Thread['group'];
};

export type Thread = {
  id: string;
  title: string;
  preview: string;
  updated: string;
  group: 'today' | 'yesterday' | 'week';
  pinned?: boolean;
  turns: Turn[];
};

const easeOut = 'ease-[cubic-bezier(0.23,1,0.32,1)]';
const press = `${easeOut} transition-[scale,background-color] duration-150 active:scale-[0.96] motion-reduce:active:scale-100`;
const enter = `${easeOut} motion-reduce:slide-in-from-bottom-0 fade-in slide-in-from-bottom-1 animate-in duration-200`;

type Props = {
  thread: Thread | null;
  recent: Thread[];
  altModel: string;
  onOpen: (id: string) => void;
  onEdit: (turn: Turn) => void;
  onRetry: (turnId: string, model?: string) => void;
};

export function Conversation({
  thread,
  recent,
  altModel,
  onOpen,
  onEdit,
  onRetry,
}: Props) {
  if (!thread) {
    return (
      <div className="flex grow items-center justify-center px-8">
        <div className={cn(enter, 'flex w-full max-w-160 flex-col gap-10')}>
          <div className="flex flex-col gap-1.5">
            <h1 className="font-semibold text-[34px]/10 tracking-[-0.025em]">
              Where were we?
            </h1>
            <p className="text-[15px]/5.5 text-muted-foreground">
              Nothing here yet. Ask anything, or pick up a thread.
            </p>
          </div>
          <div className="flex flex-col">
            <p className="pb-1 font-semibold text-[10px] text-muted-foreground/80 uppercase tracking-[0.08em]">
              Continue
            </p>
            {recent.map((t) => (
              <button
                className="-mx-2 flex h-13 items-center gap-3.5 rounded-lg not-last:border-muted not-last:border-b px-2 text-left transition-colors hover:bg-muted/60"
                key={t.id}
                onClick={() => onOpen(t.id)}
                type="button"
              >
                <span className="flex grow flex-col gap-0.5">
                  <span className="font-medium text-sm/4.5">{t.title}</span>
                  <span className="text-muted-foreground text-xs">
                    {t.preview}
                  </span>
                </span>
                <span className="font-mono text-[11px] text-muted-foreground/80">
                  {t.updated}
                </span>
              </button>
            ))}
          </div>
        </div>
      </div>
    );
  }

  const action = (
    label: string,
    icon: React.ReactNode,
    onClick?: () => void
  ) => (
    <Button
      aria-label={label}
      className={cn(press, 'size-6.5 rounded-lg text-muted-foreground')}
      onClick={onClick}
      size="icon-sm"
      variant="ghost"
    >
      {icon}
    </Button>
  );

  return (
    <MessageScrollerProvider autoScroll>
      <MessageScroller className="grow">
        <MessageScrollerViewport>
          <MessageScrollerContent className="mx-auto w-full max-w-160 gap-4.5 px-4 pt-6 pb-4">
            {thread.turns.map((turn, i) => {
              const day = turn.day ?? thread.group;
              const prev = thread.turns[i - 1];
              const divider = !prev || (prev.day ?? thread.group) !== day;
              return (
                <Fragment key={turn.id}>
                  {divider && (
                    <div className="flex items-center gap-3">
                      <div className="h-px grow bg-muted" />
                      <span className="font-medium text-[11px] text-muted-foreground/80">
                        {
                          {
                            today: 'Today',
                            yesterday: 'Yesterday',
                            week: 'This week',
                          }[day]
                        }
                      </span>
                      <div className="h-px grow bg-muted" />
                    </div>
                  )}
                  {turn.role === 'user' ? (
                    <MessageScrollerItem
                      className="group/turn flex flex-row-reverse items-center gap-2"
                      key={turn.id}
                      messageId={turn.id}
                    >
                      <div className="max-w-105 rounded-[20px] bg-muted px-4 py-2.5 text-[15px]/5.5">
                        {turn.text}
                      </div>
                      <div className="flex shrink-0 items-center gap-0.5 opacity-0 transition-opacity group-focus-within/turn:opacity-100 group-hover/turn:opacity-100">
                        {action('Edit', <IconPencil stroke={1.8} />, () =>
                          onEdit(turn)
                        )}
                        {action('Copy', <IconCopy stroke={1.8} />, () =>
                          navigator.clipboard.writeText(turn.text)
                        )}
                      </div>
                    </MessageScrollerItem>
                  ) : (
                    <MessageScrollerItem
                      className={cn(
                        'flex flex-col gap-2.5',
                        turn.streaming && enter
                      )}
                      key={turn.id}
                      messageId={turn.id}
                    >
                      {turn.error ? (
                        <>
                          <div className="flex items-start gap-3 rounded-xl bg-destructive/5 px-4 py-3.5 ring-1 ring-destructive/15">
                            <IconAlertCircle
                              className="mt-px size-4 shrink-0 text-destructive"
                              stroke={2}
                            />
                            <div className="flex flex-col gap-1">
                              <p className="font-semibold text-destructive text-sm/5">
                                The response was interrupted
                              </p>
                              <p className="text-[13px]/5 text-destructive/80">
                                The model stopped before finishing. Your message
                                was not lost. Retry with the same model or
                                switch to a different one.
                              </p>
                            </div>
                          </div>
                          <div className="flex items-center gap-2 pt-0.5">
                            <Button
                              className={cn(press, 'text-[13px]')}
                              onClick={() => onRetry(turn.id)}
                            >
                              <IconRefresh className="size-3.5" stroke={2} />
                              Retry
                            </Button>
                            <Button
                              className={cn(press, 'text-[13px]')}
                              onClick={() => onRetry(turn.id, altModel)}
                              variant="outline"
                            >
                              Retry with {altModel}
                            </Button>
                          </div>
                        </>
                      ) : (
                        <>
                          <Collapsible className="flex flex-col gap-2">
                            <CollapsibleTrigger
                              className={cn(
                                'group/thought flex w-fit items-center gap-2 rounded-md font-medium text-[13px] text-muted-foreground outline-none focus-visible:ring-3 focus-visible:ring-ring/50',
                                turn.streaming &&
                                  !turn.text &&
                                  'shimmer text-primary'
                              )}
                            >
                              <IconChevronRight
                                className="size-3.5 transition-transform group-data-[panel-open]/thought:rotate-90"
                                stroke={2}
                              />
                              {turn.thought
                                ? `Thought for ${turn.thought}s`
                                : 'Thinking…'}
                            </CollapsibleTrigger>
                            <CollapsibleContent className="border-muted border-l-2 pl-3.5 text-[13px]/5 text-muted-foreground">
                              {turn.reasoning}
                            </CollapsibleContent>
                          </Collapsible>
                          {turn.text && (
                            <p className="text-[15px]/6">{turn.text}</p>
                          )}
                          {!turn.streaming && (
                            <div className="-ml-1.5 flex items-center gap-0.5">
                              {action('Copy', <IconCopy stroke={1.8} />, () =>
                                navigator.clipboard.writeText(turn.text)
                              )}
                              {action(
                                'Good response',
                                <IconThumbUp stroke={1.8} />
                              )}
                              {action(
                                'Bad response',
                                <IconThumbDown stroke={1.8} />
                              )}
                              {action(
                                'Regenerate',
                                <IconRefresh stroke={1.8} />,
                                () => onRetry(turn.id)
                              )}
                            </div>
                          )}
                        </>
                      )}
                    </MessageScrollerItem>
                  )}
                </Fragment>
              );
            })}
          </MessageScrollerContent>
        </MessageScrollerViewport>
        <MessageScrollerButton
          className={cn(
            easeOut,
            'bottom-2 h-8 gap-1.5 rounded-full border-border bg-background px-3.5 font-medium text-[13px] shadow-xs transition-[translate,scale,opacity,background-color]'
          )}
          size="sm"
          variant="outline"
        >
          <IconChevronDown className="size-3.5" stroke={2} />
          Jump to latest
        </MessageScrollerButton>
      </MessageScroller>
    </MessageScrollerProvider>
  );
}

