            <DropdownMenuSeparator />
            <DropdownMenuGroup className="flex flex-col gap-0.5 py-0.5">
              <DropdownMenuItem className={item}>
                <IconSettings stroke={1.8} />
                Settings
                <KbdGroup className="ml-auto">
                  <Kbd>⌘</Kbd>
