                    key={result.id}
                    onSelect={onSelect}
                    result={result}
                  />
                ))}
              </CommandGroup>
              <CommandGroup
                className="mt-5 p-0 **:[[cmdk-group-heading]]:px-6 **:[[cmdk-group-heading]]:py-2 **:[[cmdk-group-heading]]:font-normal! **:[[cmdk-group-heading]]:text-sm!"
                heading="Recent chats"
